englishB1Plans[0]={"title": "Treinando para a meia-maratona", "file": "", "grammar": "Present perfect contínuo: atividades em andamento (have been + -ing)", "goal": "Conte o que você vem fazendo com I’ve been training… e since/for.", "words": [["improvement", "melhora, progresso"], ["regularly", "regularmente"], ["physical", "físico"], ["steadily", "de forma constante"], ["keep up", "manter (o ritmo)"], ["endure", "aguentar, suportar"], ["persist", "persistir, insistir"], ["encouraging", "que dá ânimo, incentivando"], ["in shape", "em forma"], ["out of shape", "fora de forma"]]};
englishB1Content[0]=[[["Since March, Lena has been running regularly to train for a half marathon.", "Desde março, a Lena vem correndo regularmente para treinar para uma meia-maratona."], ["She was out of shape at first, but now she feels strong and happy.", "No início ela estava fora de forma, mas agora se sente forte e feliz."], ["Her times have been getting better, and the improvement surprises her every month.", "Os tempos dela vêm melhorando, e a melhora a surpreende todo mês."], ["Running is a physical challenge, and her friend Jo has been encouraging her.", "Correr é um desafio físico, e a amiga Jo vem incentivando ela."], ["On rainy days it’s hard to keep up the plan, but she doesn’t stop.", "Em dias de chuva é difícil manter o plano, mas ela não para."], ["She has been training for four months, and now she’s in shape to finish the race.", "Ela vem treinando há quatro meses e agora está em forma para terminar a prova."]], [["You look great, Lena! What have you been doing lately?", "Você está ótima, Lena! O que você anda fazendo ultimamente?"], ["I’ve been training for a half marathon. I run three times a week now.", "Venho treinando para uma meia-maratona. Agora corro três vezes por semana."], ["Wow, really? Since when have you been running?", "Uau, sério? Desde quando você corre?"], ["Since March. At first I was completely out of shape and could barely finish two miles.", "Desde março. No começo eu estava totalmente fora de forma e mal terminava três quilômetros."], ["That’s a big change. Do you think you can keep up that routine in winter?", "É uma grande mudança. Você acha que consegue manter essa rotina no inverno?"], ["I hope so. I persist even when it rains, and Jo always comes with me.", "Espero que sim. Eu insisto mesmo quando chove, e a Jo sempre vem comigo."], ["Great. Do you really believe you can endure thirteen miles?", "Ótimo. Você acredita mesmo que aguenta vinte e um quilômetros?"], ["Yes, I’m sure. I’ve been improving steadily, so I’ll be ready by May.", "Sim, tenho certeza. Venho melhorando de forma constante, então estarei pronta em maio."]], ["/r/ americano em regularly e running", "O r americano não é o rr do português: puxe a língua para trás sem tocar o céu da boca, e arredonde os lábios no início de running.", ["regularly", "running"]], ["Lena ___ running regularly since March.", "has been", "is", "Lena vem correndo regularmente desde março.", "Ação que começou no passado e continua até agora, com since: has/have been + -ing (e não o presente simples)."], [["Since March, Lena has been running regularly to train for a half marathon.", "Desde março, a Lena vem correndo regularmente para treinar para uma meia-maratona."], ["I’ve been training for a half marathon. I run three times a week now.", "Venho treinando para uma meia-maratona. Agora corro três vezes por semana."]], [{"t": "c", "q": "I ___ training for three months.", "o": ["have been", "am", "was"], "pt": "Venho treinando há três meses.", "why": "Com for e uma ação que continua até hoje, use have been + -ing."}, {"t": "l", "say": "I’ve been running regularly since March.", "o": ["I’ve been running regularly since March.", "I’ve been run regularly since March.", "I’ve been running regularly for March."], "why": "Depois de been vem o verbo com -ing, e since aponta o início (March)."}, {"t": "b", "pt": "Eu venho treinando há quatro meses.", "w": ["I’ve", "been", "training", "for", "four", "months"]}, {"t": "b", "pt": "Jo vem me incentivando toda semana.", "w": ["Jo", "has", "been", "encouraging", "me", "every", "week"]}]];
