englishB1Plans[1]={"title": "Dois meses procurando emprego", "file": "", "grammar": "How long com present perfect contínuo e for / since", "goal": "Pergunte e responda há quanto tempo algo acontece com How long have you been…?", "words": [["unemployed", "desempregado"], ["professional", "profissional"], ["reject", "rejeitar, recusar"], ["apply for", "se candidatar a"], ["recruit", "recrutar"], ["strategy", "estratégia"], ["permanent", "efetivo, permanente"], ["acquire", "adquirir"], ["give it a try", "dar uma chance, tentar"]]};
englishB1Content[1]=[[["Omar has been unemployed for two months, and he’s been looking for a job.", "O Omar está desempregado há dois meses e vem procurando emprego."], ["Last week he decided to apply for a permanent position at a design company.", "Na semana passada ele decidiu se candidatar a uma vaga efetiva numa empresa de design."], ["A professional recruiter has been helping him improve his résumé for three weeks.", "Uma recrutadora profissional vem ajudando ele a melhorar o currículo há três semanas."], ["Some companies have rejected him, but he’s trying a new strategy every week.", "Algumas empresas o recusaram, mas ele tenta uma estratégia nova toda semana."], ["He has been learning online design tools to acquire skills that employers want.", "Ele vem aprendendo ferramentas de design online para adquirir habilidades que os empregadores querem."], ["After two months of waiting, he decided to give it a try and call them.", "Depois de dois meses de espera, ele decidiu tentar e ligar para eles."]], [["Omar, how long have you been looking for a job?", "Omar, há quanto tempo você procura emprego?"], ["For two months now. I’ve been sending my résumé every single day.", "Há dois meses. Venho enviando meu currículo todos os dias."], ["That’s a long time. Has any company answered you yet?", "Faz tempo. Alguma empresa já respondeu?"], ["Two companies rejected me, but one recruiter has been calling me since Monday.", "Duas empresas me recusaram, mas uma recrutadora vem me ligando desde segunda."], ["Really? What’s your strategy for the interview on Friday?", "Sério? Qual é sua estratégia para a entrevista de sexta?"], ["I’ve been practicing with a friend, and I’ll try to stay calm and honest.", "Venho praticando com um amigo e vou tentar ficar calmo e sincero."], ["Good plan. A professional photo on your profile could help too.", "Bom plano. Uma foto profissional no seu perfil também poderia ajudar."], ["You’re right. I’ll apply for the permanent job and give it a try.", "Você tem razão. Vou me candidatar à vaga efetiva e tentar."]], ["/ʃ/ em professional e position", "O sh é um chiado suave, com os lábios um pouco projetados; não diga “tch”. Em position, o -tion também soa /ʃən/.", ["professional", "position"]], ["How long ___ you been looking for a job?", "have", "did", "Há quanto tempo você está procurando emprego?", "How long + have you been + -ing pergunta sobre uma ação que ainda continua."], [["Omar has been unemployed for two months, and he’s been looking for a job.", "O Omar está desempregado há dois meses e vem procurando emprego."], ["Omar, how long have you been looking for a job?", "Omar, há quanto tempo você procura emprego?"]], [{"t": "c", "q": "Omar has been unemployed ___ two months.", "o": ["for", "since", "ago"], "pt": "Omar está desempregado há dois meses.", "why": "For vem com um período (two months); since vem com um ponto no tempo."}, {"t": "l", "say": "I’ve been sending my résumé every day.", "o": ["I’ve been sending my résumé every day.", "I’ve been sent my résumé every day.", "I’ve been sending my résumé since every day."], "why": "Ação em andamento: have been + sending. Since pede um ponto de início, não every day."}, {"t": "b", "pt": "Há quanto tempo você está esperando?", "w": ["How", "long", "have", "you", "been", "waiting"]}, {"t": "b", "pt": "Ele vem aprendendo novas habilidades desde janeiro.", "w": ["He", "has", "been", "learning", "new", "skills", "since", "January"]}]];
