englishB1Plans[2]={"title": "O romance de verão da Mia", "file": "", "grammar": "Present perfect simples vs contínuo: resultado vs processo", "goal": "Diferencie o que já está pronto (I’ve written…) do que ainda está em andamento (I’ve been writing…).", "words": [["blogger", "blogueiro(a)"], ["narrative", "narrativa"], ["rewrite", "reescrever"], ["summary", "resumo"], ["creative", "criativo"], ["revision", "revisão"], ["publicly", "publicamente"], ["catch up on", "pôr em dia"], ["work on", "trabalhar em"], ["inspiration", "inspiração"]]};
englishB1Content[2]=[[["Mia is a blogger, and she has been writing a travel story all summer.", "A Mia é blogueira e vem escrevendo uma história de viagem o verão inteiro."], ["She has written twelve chapters, and now she wants to rewrite the narrative.", "Ela escreveu doze capítulos e agora quer reescrever a narrativa."], ["The revision is going well because she has been writing every morning.", "A revisão está indo bem porque ela vem escrevendo toda manhã."], ["Her sister has read the summary and says the idea is very creative.", "A irmã dela leu o resumo e diz que a ideia é muito criativa."], ["She wants to catch up on her blog posts before she shares it publicly.", "Ela quer pôr os posts do blog em dia antes de compartilhar publicamente."], ["Inspiration comes slowly, so she must work on the ending every day.", "A inspiração vem devagar, então ela precisa trabalhar no final todo dia."]], [["Mia, you look tired. Have you been writing all night again?", "Mia, você parece cansada. Passou a noite escrevendo de novo?"], ["Yes, I have. I’ve written two chapters, but I’ve been working on the ending since midnight.", "Sim. Escrevi dois capítulos, mas venho trabalhando no final desde a meia-noite."], ["Two chapters in one night? That’s a lot of work. Is it finished?", "Dois capítulos numa noite? É muito trabalho. Está pronto?"], ["Not yet. I’ve finished the summary, but I still need to rewrite the first page.", "Ainda não. Terminei o resumo, mas ainda preciso reescrever a primeira página."], ["Have you been showing it to anyone, or is it still a secret?", "Você tem mostrado para alguém ou ainda é segredo?"], ["Only my sister. She’s been reading it, and she says it’s very creative.", "Só para minha irmã. Ela vem lendo e diz que é muito criativo."], ["You should post a short part on your blog. Readers love that.", "Você devia postar um trecho curto no blog. Os leitores adoram isso."], ["Good idea. I’ll publish one chapter this Saturday.", "Boa ideia. Vou publicar um capítulo neste sábado."]], ["/ʌ/ em summary e publicly", "A letra u nessas palavras soa como um “â” curto e relaxado, bem diferente do u do português. Boca quase parada.", ["summary", "publicly"]], ["She has ___ twelve chapters.", "written", "been writing", "Ela escreveu doze capítulos.", "Um número definido de capítulos mostra resultado: present perfect simples, não contínuo."], [["She has written twelve chapters, and now she wants to rewrite the narrative.", "Ela escreveu doze capítulos e agora quer reescrever a narrativa."], ["Yes, I have. I’ve written two chapters, but I’ve been working on the ending since midnight.", "Sim. Escrevi dois capítulos, mas venho trabalhando no final desde a meia-noite."]], [{"t": "c", "q": "I have been ___ all morning.", "o": ["writing", "written", "write"], "pt": "Venho escrevendo a manhã toda.", "why": "Have been pede o verbo com -ing para mostrar o processo."}, {"t": "l", "say": "I’ve written two chapters tonight.", "o": ["I’ve written two chapters tonight.", "I’ve writing two chapters tonight.", "I’ve wrote two chapters tonight."], "why": "Present perfect simples usa o particípio: written."}, {"t": "b", "pt": "Ela vem escrevendo toda manhã.", "w": ["She", "has", "been", "writing", "every", "morning"]}, {"t": "b", "pt": "Eu já terminei cinco capítulos.", "w": ["I", "have", "finished", "five", "chapters"]}]];
