englishB1Plans[3]={"title": "O bairro que está mudando", "file": "", "grammar": "Lately, recently e nowadays com present perfect", "goal": "Fale de mudanças recentes com lately, recently e nowadays.", "words": [["development", "empreendimento, desenvolvimento"], ["rebuild", "reconstruir"], ["noticeable", "perceptível"], ["facility", "instalação, espaço"], ["increasingly", "cada vez mais"], ["trend", "tendência"], ["transformation", "transformação"], ["gradually", "aos poucos"], ["nowadays", "hoje em dia"], ["recently", "recentemente"]]};
englishB1Content[3]=[[["Our neighborhood has changed a lot recently, and the changes are very noticeable.", "Nosso bairro mudou muito recentemente, e as mudanças são bem perceptíveis."], ["A new housing development has been going up near the river since spring.", "Um novo empreendimento residencial vem sendo construído perto do rio desde a primavera."], ["Lately the city has been working to rebuild the old market square.", "Ultimamente a prefeitura vem trabalhando para reconstruir a antiga praça do mercado."], ["Nowadays, a sports facility and a small park attract families from other areas.", "Hoje em dia, um espaço esportivo e um parquinho atraem famílias de outras regiões."], ["Rents have been rising, so living downtown is increasingly expensive for young people.", "Os aluguéis vêm subindo, então morar no centro é cada vez mais caro para os jovens."], ["The transformation happens gradually, but it’s now a clear trend across the city.", "A transformação acontece aos poucos, mas agora é uma tendência clara na cidade toda."]], [["Sam, have you seen the old market square lately?", "Sam, você viu a antiga praça do mercado ultimamente?"], ["Yes! They’ve been rebuilding it for months, and it already looks amazing.", "Vi! Eles vêm reconstruindo há meses, e já está incrível."], ["The whole street has been changing so fast recently.", "A rua inteira vem mudando tão rápido recentemente."], ["True. I used to walk there every day, and now I don’t recognize half the shops.", "É verdade. Eu andava ali todo dia, e agora não reconheço metade das lojas."], ["Prices have been going up too. My rent has increased by two hundred dollars.", "Os preços também vêm subindo. Meu aluguel aumentou duzentos dólares."], ["That’s the problem. Young people can’t afford to live near the center.", "Esse é o problema. Os jovens não conseguem pagar para morar perto do centro."], ["Maybe the new facility will bring more jobs. Have you heard anything about it?", "Talvez o novo espaço traga mais empregos. Você ouviu algo sobre isso?"], ["Yes, I’ve heard that it opens next month. I’ll come and see it with you.", "Ouvi dizer que abre no mês que vem. Vou ver com você."]], ["/ŋ/ em changing e rebuilding", "No final de -ing o som é nasal /ŋ/, sem “g” forte depois. Diga changin(g) sem soltar um “guê”.", ["changing", "rebuilding"]], ["The neighborhood ___ changing a lot lately.", "has been", "is", "O bairro vem mudando muito ultimamente.", "Lately indica um período que chega até agora: present perfect contínuo, não o presente."], [["A new housing development has been going up near the river since spring.", "Um novo empreendimento residencial vem sendo construído perto do rio desde a primavera."], ["Yes! They’ve been rebuilding it for months, and it already looks amazing.", "Vi! Eles vêm reconstruindo há meses, e já está incrível."]], [{"t": "c", "q": "Rents have been going up ___.", "o": ["recently", "yesterday", "two days ago"], "pt": "Os aluguéis vêm subindo recentemente.", "why": "Recently combina com o present perfect; yesterday e ago pedem o passado simples."}, {"t": "l", "say": "Lately, the city has been changing fast.", "o": ["Lately, the city has been changing fast.", "Lately, the city has been change fast.", "Lately, the city have been changing fast."], "why": "A cidade é singular: has been + verbo com -ing."}, {"t": "b", "pt": "Os preços vêm subindo ultimamente.", "w": ["Prices", "have", "been", "going", "up", "lately"]}, {"t": "b", "pt": "A cidade vem construindo um novo parque.", "w": ["The", "city", "has", "been", "building", "a", "new", "park"]}]];
