englishB1Plans[4]={"title": "Visita ao avô aposentado", "file": "", "grammar": "Perguntas: What have you been doing? / Have you been…?", "goal": "Pergunte o que alguém anda fazendo com What have you been doing? e Have you been…?", "words": [["retired", "aposentado"], ["explore", "explorar"], ["discover", "descobrir"], ["organise", "organizar"], ["entire", "inteiro"], ["emotion", "emoção"], ["familiar", "familiar, conhecido"], ["check up", "consulta de rotina"], ["personally", "pessoalmente"]]};
englishB1Content[4]=[[["Priya hasn’t seen her grandfather for months, so she visits him on Sunday.", "A Priya não vê o avô há meses, então o visita no domingo."], ["Grandpa Frank retired last year, and his house still feels warm and familiar.", "O vovô Frank se aposentou no ano passado, e a casa dele ainda é acolhedora e familiar."], ["She asks what he has been doing, and he smiles with emotion.", "Ela pergunta o que ele anda fazendo, e ele sorri emocionado."], ["He wants to organise the entire garage, so he has been sorting old boxes.", "Ele quer organizar a garagem inteira, então vem separando caixas velhas."], ["Yesterday he went to the doctor for a check up and heard good news.", "Ontem ele foi ao médico para uma consulta de rotina e ouviu boas notícias."], ["Every morning he walks to explore the park, and yesterday he discovered a lake.", "Toda manhã ele caminha para explorar o parque, e ontem descobriu um lago."]], [["Grandpa, I’ve missed you! What have you been doing since I last visited?", "Vovô, que saudade! O que o senhor anda fazendo desde minha última visita?"], ["Oh, lots of things. I’ve been cleaning the garage and reading my old books.", "Ah, muitas coisas. Estou limpando a garagem e lendo meus livros antigos."], ["Mom wanted to call you, but I wanted to see you personally.", "A mamãe queria ligar, mas eu queria ver o senhor pessoalmente."], ["That makes me very happy. Have you been eating well in the city?", "Isso me deixa muito feliz. Você tem comido bem na cidade?"], ["Yes, Grandpa. I’ve been cooking at home, and I’ve saved a lot of money.", "Sim, vovô. Tenho cozinhado em casa e economizei bastante dinheiro."], ["Good girl. Come on, I’ll show you the photos I’ve been sorting.", "Boa menina. Venha, vou mostrar as fotos que venho separando."], ["Wow, I haven’t seen these in years. Are all of them from the old house?", "Uau, não vejo isso há anos. Todas são da casa antiga?"], ["Yes, every single one. Sit down and I’ll tell you the stories.", "Sim, todas. Sente-se que eu conto as histórias."]], ["/h/ em have e happy", "O h inglês é um sopro leve de ar, não o “rr” do português. Não pule o h: diga happy, não “appy”.", ["have", "happy"]], ["What ___ you been doing lately?", "have", "did", "O que você anda fazendo ultimamente?", "Para perguntar o que alguém vem fazendo: What + have + sujeito + been + -ing?"], [["Grandpa, I’ve missed you! What have you been doing since I last visited?", "Vovô, que saudade! O que o senhor anda fazendo desde minha última visita?"], ["That makes me very happy. Have you been eating well in the city?", "Isso me deixa muito feliz. Você tem comido bem na cidade?"]], [{"t": "c", "q": "___ you been sleeping well?", "o": ["Have", "Are", "Do"], "pt": "Você tem dormido bem?", "why": "Have you been + -ing? é a pergunta com present perfect contínuo."}, {"t": "l", "say": "What have you been doing since Monday?", "o": ["What have you been doing since Monday?", "What are you doing since Monday?", "What have you doing since Monday?"], "why": "Since Monday pede have you been doing, com been."}, {"t": "b", "pt": "O que você anda fazendo ultimamente?", "w": ["What", "have", "you", "been", "doing", "lately"]}, {"t": "b", "pt": "Você tem comido bem?", "w": ["Have", "you", "been", "eating", "well"]}]];
