englishB1Plans[5]={"title": "Cansado por causa do relatório", "file": "", "grammar": "Causa e efeito com been + -ing (I’m tired because I’ve been…)", "goal": "Explique o cansaço ou o humor com I’m tired because I’ve been working…", "words": [["pressure", "pressão"], ["concentration", "concentração"], ["unwell", "indisposto, mal"], ["unusually", "de modo incomum"], ["tense", "tenso"], ["worthwhile", "que vale a pena"], ["fatigue", "fadiga, cansaço"], ["run down", "esgotado, sem energia"], ["pass out", "desmaiar"]]};
englishB1Content[5]=[[["Noah looks tired because he has been working under a lot of pressure.", "O Noah parece cansado porque vem trabalhando sob muita pressão."], ["He has been staying late all week, and he feels unusually tense.", "Ele vem ficando até tarde a semana toda e se sente incomumente tenso."], ["His concentration is poor because he has been skipping lunch every day.", "A concentração dele está fraca porque ele vem pulando o almoço todos os dias."], ["Yesterday he felt so unwell that he thought he would pass out.", "Ontem ele se sentiu tão mal que achou que ia desmaiar."], ["His doctor says he is run down, and the fatigue is a warning.", "O médico diz que ele está esgotado e que o cansaço é um alerta."], ["He will finish the report tomorrow, and he thinks the effort was worthwhile.", "Ele termina o relatório amanhã e acha que o esforço valeu a pena."]], [["Noah, you look terrible. Why are you so tired today?", "Noah, você está péssimo. Por que está tão cansado hoje?"], ["I’m tired because I’ve been working on the budget report since six this morning.", "Estou cansado porque trabalho no relatório do orçamento desde as seis da manhã."], ["Since six? No wonder your concentration is gone. Have you eaten anything?", "Desde as seis? Não admira que sua concentração acabou. Você comeu alguma coisa?"], ["Only a cookie. I’ve been skipping lunch because the deadline is tomorrow.", "Só um biscoito. Venho pulando o almoço porque o prazo é amanhã."], ["That’s not healthy. You’ve been drinking coffee all day, and you look tense.", "Isso não é saudável. Você vem tomando café o dia todo e parece tenso."], ["I know. My hands are shaking, and I feel nervous.", "Eu sei. Minhas mãos estão tremendo e me sinto nervoso."], ["Take a break now. Let’s walk outside for ten minutes, and I’ll buy you lunch.", "Faça uma pausa agora. Vamos andar lá fora dez minutos e eu pago seu almoço."], ["Okay, you’re right. The report can wait ten minutes. Thanks, Elena.", "Certo, você tem razão. O relatório pode esperar dez minutos. Obrigado, Elena."]], ["acento em concentration e fatigue", "Em -tion o acento cai na sílaba anterior (concenTRAtion). Em fatigue, a força está no meio: fa-TEEG, com g suave no final.", ["concentration", "fatigue"]], ["I’m tired because I ___ working all night.", "have been", "am", "Estou cansado porque venho trabalhando a noite toda.", "Para explicar um efeito de agora por uma atividade que vem de antes, use have been + -ing."], [["Noah looks tired because he has been working under a lot of pressure.", "O Noah parece cansado porque vem trabalhando sob muita pressão."], ["I’m tired because I’ve been working on the budget report since six this morning.", "Estou cansado porque trabalho no relatório do orçamento desde as seis da manhã."]], [{"t": "c", "q": "He feels unwell ___ he has been skipping meals.", "o": ["because", "so", "but"], "pt": "Ele se sente mal porque vem pulando refeições.", "why": "Because introduz a causa; so introduziria o resultado."}, {"t": "l", "say": "She’s tired because she’s been studying all night.", "o": ["She’s tired because she’s been studying all night.", "She’s tired because she’s been study all night.", "She’s tired so because she’s been studying all night."], "why": "Because + she’s been + verbo com -ing."}, {"t": "b", "pt": "Estou cansada porque venho estudando a noite toda.", "w": ["I’m", "tired", "because", "I’ve", "been", "studying", "all", "night"]}, {"t": "b", "pt": "Ele está tenso porque trabalha demais.", "w": ["He’s", "tense", "because", "he", "has", "been", "working", "too", "much"]}]];
