englishB1Plans[6]={"title": "A novidade de Ana e Kenji", "file": "", "grammar": "Present perfect contínuo em notícias pessoais e planos", "goal": "Conte novidades e planos usando have been + -ing junto com going to e will.", "words": [["pregnant", "grávida"], ["delighted", "encantado, radiante"], ["pleased", "contente"], ["preparation", "preparação"], ["marriage", "casamento (união)"], ["romantic", "romântico"], ["finances", "finanças"], ["considerable", "considerável"], ["advance", "antecedência"]]};
englishB1Content[6]=[[["Ana and Kenji have been planning a big surprise for their friends.", "Ana e Kenji vêm planejando uma grande surpresa para os amigos."], ["They are going to announce that Ana is pregnant, and everyone will be delighted.", "Eles vão anunciar que a Ana está grávida, e todos vão ficar encantados."], ["They have been checking their finances because a baby is a considerable expense.", "Eles vêm conferindo as finanças porque um bebê é uma despesa considerável."], ["Their marriage is still romantic, and Kenji has been cooking dinner every Friday.", "O casamento deles continua romântico, e o Kenji vem cozinhando todas as sextas."], ["Kenji has been busy with the preparation, and Ana has decided everything in advance.", "O Kenji está ocupado com a preparação, e a Ana decidiu tudo com antecedência."], ["Their friends were very pleased with the news, and everybody hugged them.", "Os amigos ficaram muito contentes com a notícia, e todos os abraçaram."]], [["Ana, there are rumors going around. Is it true you have big news?", "Ana, estão circulando boatos. É verdade que você tem uma grande novidade?"], ["Yes! Kenji and I have been waiting to tell you. I’m pregnant.", "Sim! Kenji e eu estávamos esperando para contar. Estou grávida."], ["Oh my goodness, congratulations! I’m so pleased for you both. When is the baby due?", "Nossa, parabéns! Fico muito feliz por vocês dois. Quando o bebê nasce?"], ["In March. We’ve been looking at apartments, because our place is too small.", "Em março. Vimos apartamentos, porque nossa casa é pequena demais."], ["Smart. Are you worried about the finances? A baby is expensive.", "Esperto. Vocês estão preocupados com as finanças? Um bebê é caro."], ["A little. Kenji has been making a budget since we heard the news.", "Um pouco. O Kenji vem fazendo um orçamento desde que soubemos."], ["I’m delighted for you. If you need help with the preparation, call me.", "Estou radiante por vocês. Se precisarem de ajuda na preparação, me liguem."], ["Thank you, Mia. I will, and we’d love you to come to dinner on Saturday.", "Obrigada, Mia. Vou ligar, e adoraríamos que você viesse jantar no sábado."]], ["/z/ final em pleased e news", "No final de pleased e news, o s soa como /z/, com vibração na garganta. Não diga “niús” com s seco.", ["pleased", "news"]], ["Kenji ___ been making a budget since January.", "has", "have", "Kenji vem fazendo um orçamento desde janeiro.", "Kenji é “he”: usamos has been + -ing, não have."], [["Their marriage is still romantic, and Kenji has been cooking dinner every Friday.", "O casamento deles continua romântico, e o Kenji vem cozinhando todas as sextas."], ["A little. Kenji has been making a budget since we heard the news.", "Um pouco. O Kenji vem fazendo um orçamento desde que soubemos."]], [{"t": "c", "q": "Ana ___ been looking at apartments lately.", "o": ["has", "have", "is"], "pt": "A Ana vem olhando apartamentos ultimamente.", "why": "Ana é singular, então has been + -ing."}, {"t": "l", "say": "We’ve been waiting to tell you.", "o": ["We’ve been waiting to tell you.", "We’ve been wait to tell you.", "We been waiting to tell you."], "why": "Have been + verbo com -ing; a contração We’ve é obrigatória no falado."}, {"t": "b", "pt": "Estamos esperando para te contar.", "w": ["We’ve", "been", "waiting", "to", "tell", "you"]}, {"t": "b", "pt": "Kenji vem fazendo um orçamento.", "w": ["Kenji", "has", "been", "making", "a", "budget"]}]];
