englishB1Plans[7]={"title": "Noites sem dormir no consultório", "file": "", "grammar": "Present perfect negativo contínuo: I haven’t been sleeping well", "goal": "Diga o que você não vem fazendo com haven’t / hasn’t been + -ing.", "words": [["sleepless", "sem sono, em claro"], ["uncomfortable", "desconfortável"], ["anxiety", "ansiedade"], ["treatment", "tratamento"], ["suffer", "sofrer"], ["medication", "remédio, medicação"], ["wide awake", "completamente acordado"], ["cautious", "cauteloso"], ["realistic", "realista"]]};
englishB1Content[7]=[[["Sam hasn’t been sleeping well, and he has had sleepless nights for two weeks.", "O Sam não vem dormindo bem e tem passado noites em claro há duas semanas."], ["He lies in bed, wide awake, and thinks about work until three a.m.", "Ele fica deitado, bem acordado, pensando no trabalho até as três da manhã."], ["His bed isn’t uncomfortable, but his anxiety about the new job keeps him awake.", "A cama dele não é desconfortável, mas a ansiedade pelo novo emprego o mantém acordado."], ["He doesn’t want to suffer for months, so he goes to see a doctor.", "Ele não quer sofrer por meses, então vai consultar um médico."], ["The doctor is cautious about giving medication and suggests a simple treatment first.", "A médica é cautelosa em dar remédio e sugere primeiro um tratamento simples."], ["She says it’s realistic to sleep better in two weeks with some changes.", "Ela diz que é realista dormir melhor em duas semanas com algumas mudanças."]], [["Good morning, Sam. What seems to be the problem?", "Bom dia, Sam. Qual parece ser o problema?"], ["I haven’t been sleeping well for two weeks, and I feel exhausted all day.", "Não tenho dormido bem há duas semanas e me sinto exausto o dia todo."], ["Have you been drinking a lot of coffee, or looking at your phone in bed?", "Você tem tomado muito café ou olhado o celular na cama?"], ["Yes, both. I haven’t been taking any breaks from my phone since the new project.", "Sim, os dois. Não tenho feito pausas do celular desde o novo projeto."], ["I’d like to try a simple treatment first. No medication yet.", "Prefiro tentar primeiro um tratamento simples. Sem remédio por enquanto."], ["That sounds good. I really don’t want to suffer through another week like this.", "Parece bom. Não quero sofrer mais uma semana assim."], ["Stop coffee after noon, turn off your phone at ten, and come back in two weeks.", "Pare o café depois do meio-dia, desligue o celular às dez e volte em duas semanas."], ["Okay, I’ll do exactly that. Thank you, doctor.", "Certo, vou fazer exatamente isso. Obrigado, doutora."]], ["/sl/ sem vogal extra em sleeping e sleepless", "Não coloque um “i” antes do s: diga sleep, não “isleep”. Comece o s já com a língua pronta para o l.", ["sleeping", "sleepless"]], ["I ___ been sleeping well lately.", "haven’t", "don’t", "Não tenho dormido bem ultimamente.", "Negativa do present perfect contínuo: haven’t / hasn’t + been + -ing."], [["Sam hasn’t been sleeping well, and he has had sleepless nights for two weeks.", "O Sam não vem dormindo bem e tem passado noites em claro há duas semanas."], ["I haven’t been sleeping well for two weeks, and I feel exhausted all day.", "Não tenho dormido bem há duas semanas e me sinto exausto o dia todo."]], [{"t": "c", "q": "She ___ been eating well this month.", "o": ["hasn’t", "haven’t", "isn’t"], "pt": "Ela não tem comido bem este mês.", "why": "Com she usamos hasn’t been + -ing."}, {"t": "l", "say": "I haven’t been sleeping well.", "o": ["I haven’t been sleeping well.", "I haven’t been sleep well.", "I don’t been sleeping well."], "why": "A negativa é haven’t been + verbo com -ing; don’t não combina com been."}, {"t": "b", "pt": "Não tenho dormido bem.", "w": ["I", "haven’t", "been", "sleeping", "well"]}, {"t": "b", "pt": "Ele não tem feito exercício ultimamente.", "w": ["He", "hasn’t", "been", "exercising", "lately"]}]];
englishB1PhotoThemes[7]="health";
englishB1Plans[8]={"title": "A reforma do banheiro da Rosa", "file": "", "grammar": "Just, already, yet e still com present perfect e contínuo", "goal": "Fale do andamento de uma obra com just, already, yet e still.", "words": [["surface", "superfície"], ["layer", "camada"], ["moisture", "umidade"], ["tiles", "azulejos"], ["plaster", "reboco, gesso"], ["handy", "habilidoso com reparos"], ["bare", "nu, sem revestimento"], ["edge", "borda, beirada"], ["firm", "firme"]]};
englishB1Content[8]=[[["Rosa has been renovating her bathroom for three weeks, and it isn’t finished yet.", "A Rosa vem reformando o banheiro há três semanas, e ainda não está pronto."], ["The workers have already removed the old tiles from the walls.", "Os operários já removeram os azulejos velhos das paredes."], ["Now the wall is bare, and they’ve just covered the surface with plaster.", "Agora a parede está nua, e eles acabaram de cobrir a superfície com reboco."], ["They’re still waiting for the moisture to dry before they add a second layer.", "Eles ainda esperam a umidade secar antes de passar uma segunda camada."], ["Tom is handy, and he has already fixed the edge of the old sink.", "O Tom é habilidoso e já consertou a beirada da pia velha."], ["The new tiles haven’t arrived yet, but the floor is firm and ready.", "Os azulejos novos ainda não chegaram, mas o piso está firme e pronto."]], [["Good morning, Rosa. Have you been waiting long for me?", "Bom dia, Rosa. Você está esperando há muito tempo?"], ["Not really, I’ve just made coffee. Is the plaster dry yet?", "Não muito, acabei de fazer café. O reboco já secou?"], ["Almost. It’s still a little damp, so we’ve been keeping the window open.", "Quase. Ainda está um pouco úmido, então vimos deixando a janela aberta."], ["Okay. Have you already checked the moisture behind the wall?", "Certo. Vocês já verificaram a umidade atrás da parede?"], ["Yes, I’ve already checked it. The wall is safe, but I’m still testing the corner.", "Sim, já verifiquei. A parede está segura, mas ainda estou testando o canto."], ["Good. Tom has been helping on weekends, and he’s still painting the door.", "Ótimo. O Tom vem ajudando nos fins de semana e ainda está pintando a porta."], ["Tell him he can start the tiles tomorrow. They’ve just arrived at the store.", "Diga que ele pode começar os azulejos amanhã. Acabaram de chegar à loja."], ["Wonderful! Then we haven’t lost any time. I’ll call him right now.", "Maravilha! Então não perdemos tempo. Vou ligar para ele agora."]], ["/dʒ/ em edge e just", "O som /dʒ/ é um “dj” de “djalma” bem curto. Em edge o g também soa assim, e o e final não é pronunciado.", ["edge", "just"]], ["The tiles haven’t arrived ___.", "yet", "already", "Os azulejos ainda não chegaram.", "Em frases negativas, yet significa “ainda”; already é usado em frases afirmativas."], [["The workers have already removed the old tiles from the walls.", "Os operários já removeram os azulejos velhos das paredes."], ["The new tiles haven’t arrived yet, but the floor is firm and ready.", "Os azulejos novos ainda não chegaram, mas o piso está firme e pronto."]], [{"t": "c", "q": "I’ve ___ finished the walls, and they look great.", "o": ["already", "yet", "since"], "pt": "Eu já terminei as paredes, e elas ficaram ótimas.", "why": "Already (“já”) vai em frases afirmativas; yet é para negativas e perguntas."}, {"t": "l", "say": "The tiles haven’t arrived yet.", "o": ["The tiles haven’t arrived yet.", "The tiles haven’t arrived already.", "The tiles didn’t arrived yet."], "why": "Negativa com present perfect: haven’t + particípio, com yet no final."}, {"t": "b", "pt": "Eu acabei de pintar a porta.", "w": ["I’ve", "just", "painted", "the", "door"]}, {"t": "b", "pt": "Ele ainda está esperando o reboco secar.", "w": ["He’s", "still", "waiting", "for", "the", "plaster", "to", "dry"]}]];
