englishB1Plans[9]={"title": "Um mês de mudanças", "file": "", "grammar": "Revisão: present perfect contínuo, simples, lately, yet, still (mini-história)", "goal": "Conte um mês de mudanças misturando have been + -ing, just, already, yet e still.", "words": [["commit", "comprometer-se"], ["maintain", "manter"], ["gain", "ganhar, adquirir"], ["willingness", "disposição"], ["positive", "positivo"], ["put on weight", "engordar"], ["stick with", "persistir em, manter-se fiel a"], ["on track", "no caminho certo"], ["make an effort", "fazer um esforço"], ["nutrition", "nutrição"]]};
englishB1Content[9]=[[["A month ago, Lia decided to commit to a few healthy changes.", "Um mês atrás, a Lia decidiu se comprometer com algumas mudanças saudáveis."], ["She has been cooking at home, and she’s learning more about nutrition.", "Ela vem cozinhando em casa e está aprendendo mais sobre nutrição."], ["She put on weight last winter, so she wants to feel stronger now.", "Ela engordou no inverno passado, então quer se sentir mais forte agora."], ["It hasn’t been easy, but her willingness to learn has been growing every week.", "Não tem sido fácil, mas a disposição dela para aprender cresce toda semana."], ["She tries to make an effort every day, even when she feels tired.", "Ela tenta fazer um esforço todo dia, mesmo quando está cansada."], ["She has gained energy, and she’s on track with her goals.", "Ela ganhou energia e está no caminho certo com suas metas."]], [["Lia, you look great! What have you been doing this month?", "Lia, você está ótima! O que você anda fazendo este mês?"], ["I’ve been cooking at home and walking every morning. It’s my new routine.", "Venho cozinhando em casa e caminhando toda manhã. É minha nova rotina."], ["That’s impressive. How do you stick with it when you’re busy?", "Impressionante. Como você mantém isso quando está ocupada?"], ["I keep a positive attitude, and I’ve been writing my goals in a notebook.", "Mantenho uma atitude positiva e venho escrevendo minhas metas num caderno."], ["Have you lost weight already, or is it too early to say?", "Você já perdeu peso ou é cedo demais para dizer?"], ["It’s too early, but I feel stronger, and I haven’t been getting sick.", "É cedo, mas me sinto mais forte e não tenho ficado doente."], ["Do you think you can maintain this routine after the summer?", "Você acha que consegue manter essa rotina depois do verão?"], ["Yes, I’m sure. I’ve just signed up for a yoga class, so I’ll stay motivated.", "Sim, tenho certeza. Acabei de me inscrever numa aula de ioga, então vou continuar motivada."]], ["/eɪ/ em gain e maintain", "O ai de gain e maintain é o ditongo /eɪ/, como “êi” em “lei”. Deslize da boca semiaberta para o i.", ["gain", "maintain"]], ["She ___ cooking at home for a month.", "has been", "has", "Ela vem cozinhando em casa há um mês.", "Com for e uma ação que continua, usamos has been + -ing; has sozinho não forma essa frase."], [["She has gained energy, and she’s on track with her goals.", "Ela ganhou energia e está no caminho certo com suas metas."], ["I’ve been cooking at home and walking every morning. It’s my new routine.", "Venho cozinhando em casa e caminhando toda manhã. É minha nova rotina."]], [{"t": "c", "q": "How long ___ you been walking every morning?", "o": ["have", "did", "are"], "pt": "Há quanto tempo você caminha toda manhã?", "why": "How long + have you been + -ing."}, {"t": "l", "say": "I’ve just signed up for a yoga class.", "o": ["I’ve just signed up for a yoga class.", "I’ve just sign up for a yoga class.", "I’ve been just signed up for a yoga class."], "why": "Just fica entre have e o particípio: have just signed up."}, {"t": "b", "pt": "Ela vem mantendo uma rotina positiva.", "w": ["She", "has", "been", "keeping", "a", "positive", "routine"]}, {"t": "b", "pt": "Eu ainda não recebi uma resposta.", "w": ["I", "haven’t", "received", "an", "answer", "yet"]}]];
englishB1PhotoThemes[9]="city";
englishB1MiniStories[9]=["Um mês de mudanças", "A month ago, Omar was unemployed, tired, and worried about money.~Um mês atrás, o Omar estava desempregado, cansado e preocupado com dinheiro.|He has been applying for jobs every day, and he has been practicing interviews.~Ele vem se candidatando a vagas todos os dias e praticando entrevistas.|He hasn’t been sleeping well, so he started to walk every morning.~Ele não vinha dormindo bem, então começou a caminhar toda manhã.|Lately he has been eating better, and he has already lost two pounds.~Ultimamente ele vem comendo melhor e já perdeu um quilo.|Last week a company called him, and he has just finished a second interview.~Na semana passada uma empresa ligou, e ele acabou de fazer a segunda entrevista.|He hasn’t received an answer yet, but he’s still feeling positive.~Ele ainda não recebeu resposta, mas continua se sentindo positivo.|His neighbor Rosa has been renovating her bathroom, and Omar has been helping her.~A vizinha Rosa vem reformando o banheiro, e o Omar vem ajudando.|They’ve been painting the walls together, and it has been fun.~Eles vêm pintando as paredes juntos, e tem sido divertido.|Today the phone rang, and the company offered him the job.~Hoje o telefone tocou, e a empresa ofereceu a vaga a ele.|Omar has been smiling all day, because a month of effort was worthwhile.~O Omar está sorrindo o dia todo, porque um mês de esforço valeu a pena."];
englishB1Plans[10]={"title": "Arrombamento na loja da Rosa", "file": "", "grammar": "Past perfect afirmativo: had + particípio para o que já tinha acontecido", "goal": "Conte o que já tinha acontecido antes de você chegar usando had + particípio.", "words": [["patrol", "patrulha"], ["ransack", "revirar, vasculhar"], ["crime", "crime"], ["criminal", "criminoso"], ["threatening", "ameaçador"], ["terrified", "aterrorizado"], ["horrified", "horrorizado"], ["nasty", "desagradável, maldoso"]]};
englishB1Content[10]=[[["When Rosa opened her shop on Monday morning, someone had already ransacked it.", "Quando Rosa abriu a loja na segunda de manhã, alguém já tinha revirado tudo."], ["Boxes lay on the floor, and the cash register had disappeared.", "Havia caixas no chão, e a caixa registradora tinha sumido."], ["The officer on patrol said the criminal had broken the back window.", "O policial da patrulha disse que o criminoso tinha quebrado a janela dos fundos."], ["Rosa was terrified because the crime had happened only a few hours earlier.", "Rosa estava aterrorizada porque o crime tinha acontecido poucas horas antes."], ["Her neighbor had seen a man with a threatening look and had called the police.", "A vizinha tinha visto um homem com um olhar ameaçador e tinha chamado a polícia."], ["Rosa was horrified, but the police had found her cash register.", "Rosa ficou horrorizada, mas a polícia tinha encontrado a caixa registradora dela."]], [["Ms. Silva, what did you find when you arrived this morning?", "Sra. Silva, o que a senhora encontrou ao chegar hoje de manhã?"], ["The back window was broken, and someone had ransacked every shelf.", "A janela dos fundos estava quebrada, e alguém tinha revirado todas as prateleiras."], ["Did you receive any threatening messages before the crime?", "A senhora recebeu mensagens ameaçadoras antes do crime?"], ["No, never. But last week an angry customer shouted at me about a price.", "Não, nunca. Mas na semana passada um cliente bravo gritou comigo por causa de um preço."], ["I see. Mr. Lopez says a man with a nasty smile had waited near your door since six.", "Entendi. O Sr. Lopez diz que um homem com um sorriso maldoso tinha esperado perto da sua porta desde as seis."], ["Really? I’m terrified. I didn’t know anyone was watching my shop.", "Sério? Estou aterrorizada. Eu não sabia que alguém estava vigiando minha loja."], ["Don’t worry. We’ll increase our patrol on this street every night.", "Não se preocupe. Vamos aumentar nossa patrulha nesta rua todas as noites."], ["Thank you. Did the criminal take anything besides the cash register?", "Obrigada. O criminoso levou algo além da caixa registradora?"], ["Only the money. The cameras show that the man had worn a mask.", "Só o dinheiro. As câmeras mostram que o homem tinha usado uma máscara."], ["Perfect. Please come back at five, and I’ll have the list ready.", "Perfeito. Por favor, volte às cinco, e eu terei a lista pronta."]], ["/æ/ em patrol e ransack", "O a de patrol e ransack é um /æ/ aberto: abra bem a boca, como um “é” esticado, e não diga o “a” de “casa”.", ["patrol", "ransack"]], ["When Rosa opened the shop, someone ___ already ransacked it.", "had", "has", "Quando Rosa abriu a loja, alguém já tinha revirado tudo.", "Had + particípio mostra algo que aconteceu antes de outro momento do passado."], [["When Rosa opened her shop on Monday morning, someone had already ransacked it.", "Quando Rosa abriu a loja na segunda de manhã, alguém já tinha revirado tudo."], ["The back window was broken, and someone had ransacked every shelf.", "A janela dos fundos estava quebrada, e alguém tinha revirado todas as prateleiras."]], [{"t": "c", "q": "The officer said the criminal ___ broken the back window.", "o": ["had", "is", "will"], "pt": "O policial disse que o criminoso tinha quebrado a janela dos fundos.", "why": "Had + broken mostra uma ação anterior ao momento em que o policial falou."}, {"t": "l", "say": "Her neighbor had seen a man with a threatening look.", "o": ["Her neighbor had seen a man with a threatening look.", "Her neighbor has seen a man with a threatening look.", "Her neighbor had see a man with a threatening look."], "why": "Had seen (had + particípio) é a forma do past perfect."}, {"t": "b", "pt": "Alguém já tinha vasculhado a loja.", "w": ["Someone", "had", "already", "ransacked", "the", "shop"]}, {"t": "b", "pt": "A polícia tinha encontrado a caixa registradora.", "w": ["The", "police", "had", "found", "the", "cash", "register"]}]];
