englishB1Plans[11]={"title": "Chegando atrasada ao teatro", "file": "", "grammar": "Past perfect com already, just, never e before", "goal": "Diga o que já tinha começado ou o que você nunca tinha feito antes usando already, just, never e before.", "words": [["latecomer", "quem chega atrasado"], ["intermission", "intervalo (de peça ou filme)"], ["onstage", "no palco"], ["thunderous", "ensurdecedor, trovejante"], ["gorgeous", "lindíssimo"], ["amusing", "divertido"], ["glorious", "glorioso, magnífico"], ["unbelievable", "inacreditável"], ["delightful", "encantador"]]};
englishB1Content[11]=[[["Mia ran into the theater at eight fifteen, but the play had already started.", "Mia entrou correndo no teatro às oito e quinze, mas a peça já tinha começado."], ["The woman at the door told the latecomer to wait quietly until the intermission.", "A mulher na porta pediu à retardatária que esperasse em silêncio até o intervalo."], ["Through a small window, she saw the actors onstage in gorgeous red costumes.", "Por uma janela pequena, ela viu os atores no palco com figurinos vermelhos lindíssimos."], ["She had never seen a live play before, and the glorious music amazed her.", "Ela nunca tinha visto uma peça ao vivo antes, e a música magnífica a deixou maravilhada."], ["At the intermission, Tom had just come back with two cups of lemonade.", "No intervalo, Tom tinha acabado de voltar com dois copos de limonada."], ["After the thunderous applause at the end, Mia said the night had been unbelievable.", "Depois dos aplausos ensurdecedores no final, Mia disse que a noite tinha sido inacreditável."]], [["Mia, where were you? The play had already started when I sat down.", "Mia, onde você estava? A peça já tinha começado quando eu me sentei."], ["I know, I’m so sorry. The bus had just left when I arrived at the stop.", "Eu sei, sinto muito. O ônibus tinha acabado de sair quando cheguei ao ponto."], ["Don’t worry. The first act was amusing, and you didn’t miss the best part.", "Não se preocupe. O primeiro ato foi divertido, e você não perdeu a melhor parte."], ["Really? Honestly, I had never been to a real theater before tonight.", "Sério? Sinceramente, eu nunca tinha ido a um teatro de verdade antes de hoje."], ["Then you’re in for a delightful surprise. Have you read the story?", "Então você vai ter uma surpresa encantadora. Você já leu a história?"], ["Not yet. Does the hero finally meet the princess in the second act?", "Ainda não. O herói finalmente conhece a princesa no segundo ato?"], ["Yes, and the music is unbelievable. The actors rehearsed for six months.", "Sim, e a música é inacreditável. Os atores ensaiaram por seis meses."], ["Six months? That explains why everything looks so perfect up there.", "Seis meses? Isso explica por que tudo parece tão perfeito lá em cima."], ["Exactly. The bell is ringing, so we should go back to our seats now.", "Exato. O sino está tocando, então devemos voltar aos nossos lugares agora."], ["Okay. Thanks for waiting for me, Tom. I’ll never be late again.", "Certo. Obrigada por me esperar, Tom. Nunca mais vou me atrasar."]], ["/θ/ em theater e thunderous", "Em theater e thunderous, ponha a ponta da língua entre os dentes e solte o ar sem voz; não troque por /t/ nem por /f/.", ["theater", "thunderous"]], ["The play ___ already started when Mia arrived.", "had", "has", "A peça já tinha começado quando Mia chegou.", "Com when + passado simples, use had + particípio para o que aconteceu antes."], [["Mia ran into the theater at eight fifteen, but the play had already started.", "Mia entrou correndo no teatro às oito e quinze, mas a peça já tinha começado."], ["Really? Honestly, I had never been to a real theater before tonight.", "Sério? Sinceramente, eu nunca tinha ido a um teatro de verdade antes de hoje."]], [{"t": "c", "q": "At the intermission, Tom ___ just come back with two cups of lemonade.", "o": ["had", "has", "did"], "pt": "No intervalo, Tom tinha acabado de voltar com dois copos de limonada.", "why": "Had just + particípio mostra algo que tinha acabado de acontecer."}, {"t": "l", "say": "The bus had just left when I arrived at the stop.", "o": ["The bus had just left when I arrived at the stop.", "The bus has just left when I arrived at the stop.", "The bus had just leave when I arrived at the stop."], "why": "Had just left: past perfect com just para algo recém-acontecido."}, {"t": "b", "pt": "O espetáculo já tinha começado.", "w": ["The", "play", "had", "already", "started"]}, {"t": "b", "pt": "Eu nunca tinha ido a um teatro de verdade.", "w": ["I", "had", "never", "been", "to", "a", "real", "theater"]}]];
