englishB1Plans[12]={"title": "Pane na estrada a caminho do aeroporto", "file": "", "grammar": "By the time + passado simples e past perfect", "goal": "Explique o que já tinha acontecido quando você chegou, com By the time + passado simples.", "words": [["roadside", "beira da estrada"], ["hurriedly", "às pressas"], ["desperate", "desesperado"], ["unfortunate", "infeliz, lamentável"], ["mishap", "contratempo, percalço"], ["setback", "revés, atraso"], ["ignoring", "ignorando"], ["embarrassment", "vergonha, constrangimento"], ["relief", "alívio"]]};
englishB1Content[12]=[[["Ben and Priya left home at five, but their car stopped at the roadside.", "Ben e Priya saíram de casa às cinco, mas o carro deles parou no acostamento."], ["By the time they got a taxi, the check-in desk had closed.", "Quando conseguiram um táxi, o balcão de check-in já tinha fechado."], ["Ben hurriedly called the airline, ignoring the stares of people passing by.", "Ben ligou às pressas para a companhia aérea, ignorando os olhares de quem passava."], ["Priya was desperate, because this trip was a gift for her mother’s birthday.", "Priya estava desesperada, porque essa viagem era um presente para o aniversário da mãe dela."], ["By the time the next flight left, they had waited for four long hours.", "Quando o voo seguinte partiu, eles tinham esperado quatro longas horas."], ["In the end, the setback was small, and they felt relief when they landed.", "No fim, o atraso foi pequeno, e eles sentiram alívio quando pousaram."]], [["I’m sorry, sir. By the time you got here, the plane had already left.", "Sinto muito, senhor. Quando o senhor chegou, o avião já tinha partido."], ["I know. It was an unfortunate mishap. Our car broke down on the highway.", "Eu sei. Foi um contratempo lamentável. Nosso carro quebrou na estrada."], ["That happens. Do you have your ticket receipt and your passports?", "Isso acontece. Vocês têm o comprovante da passagem e os passaportes?"], ["Yes, here they are. Is there a later flight to Denver today?", "Sim, aqui estão. Existe um voo mais tarde para Denver hoje?"], ["There’s one at nine tonight, and I can change your tickets for a small fee.", "Tem um às nove da noite, e posso trocar as passagens por uma taxa pequena."], ["How much is the fee? We’ve already spent a lot on the tow truck.", "Quanto é a taxa? Já gastamos muito com o guincho."], ["Forty dollars each. Normally it’s eighty, but I’ll make an exception.", "Quarenta dólares cada um. Normalmente são oitenta, mas vou abrir uma exceção."], ["That’s kind of you. I felt such embarrassment when we missed the first flight.", "Que gentileza. Senti tanta vergonha quando perdemos o primeiro voo."], ["Don’t worry. By the time I arrived this morning, four families had already missed it.", "Não se preocupe. Quando cheguei hoje de manhã, quatro famílias já tinham perdido esse voo."], ["Good to know. So we’ll take the nine o’clock flight, and we’ll wait here.", "Bom saber. Então pegaremos o voo das nove e esperaremos aqui."]], ["/h/ em hurriedly e had", "O h inglês é um sopro suave de ar, quase um “rr” fraco: hurriedly, had. Não deixe o h mudo como em português.", ["hurriedly", "had"]], ["By the time they got a taxi, the check-in desk ___ closed.", "had", "has", "Quando conseguiram um táxi, o balcão de check-in já tinha fechado.", "Depois de By the time + passado simples, a ação que veio antes usa had + particípio."], [["By the time they got a taxi, the check-in desk had closed.", "Quando conseguiram um táxi, o balcão de check-in já tinha fechado."], ["By the time the next flight left, they had waited for four long hours.", "Quando o voo seguinte partiu, eles tinham esperado quatro longas horas."]], [{"t": "c", "q": "By the time Ben ___ the airline, the desk had already closed.", "o": ["called", "had called", "calls"], "pt": "Quando Ben ligou para a companhia aérea, o balcão já tinha fechado.", "why": "Depois de By the time, a ação mais recente fica no passado simples (called) e a anterior no past perfect."}, {"t": "l", "say": "By the time they got a taxi, the check-in desk had closed.", "o": ["By the time they got a taxi, the check-in desk had closed.", "By the time they get a taxi, the check-in desk had closed.", "By the time they got a taxi, the check-in desk has closed."], "why": "By the time + got (passado simples) combina com had closed (past perfect)."}, {"t": "b", "pt": "Quando chegamos, o voo já tinha saído.", "w": ["By", "the", "time", "we", "arrived", "the", "flight", "had", "left"]}, {"t": "b", "pt": "Ben ligou para a companhia aérea às pressas.", "w": ["Ben", "hurriedly", "called", "the", "airline"]}]];
