englishB1Plans[13]={"title": "Depois da enchente no bairro", "file": "", "grammar": "When e after com past perfect e passado simples", "goal": "Conte o que aconteceu depois de outra coisa usando when e after com past perfect e passado simples.", "words": [["rainfall", "chuva, volume de chuva"], ["restored", "restabelecido, restaurado"], ["homeless", "desabrigado"], ["devastated", "devastado, arrasado"], ["regain", "recuperar"], ["tragic", "trágico"], ["survivor", "sobrevivente"], ["survival", "sobrevivência"]]};
englishB1Content[13]=[[["After the heavy rainfall stopped, many families in Green Hill had lost their homes.", "Depois que a chuva forte parou, muitas famílias de Green Hill tinham perdido suas casas."], ["When the river went down, the mayor said the damage had been tragic.", "Quando o rio baixou, o prefeito disse que o estrago tinha sido trágico."], ["Some were homeless, and a few survivors told stories about a night of survival.", "Alguns estavam desabrigados, e alguns sobreviventes contaram histórias sobre uma noite de sobrevivência."], ["After the volunteers cleaned the streets, the electricity was restored in two days.", "Depois que os voluntários limparam as ruas, a eletricidade foi restabelecida em dois dias."], ["Lia, who had been devastated, found her old photo album under the mud.", "Lia, que tinha ficado devastada, encontrou seu velho álbum de fotos debaixo da lama."], ["When the sun came out, Lia smiled and began to regain her hope.", "Quando o sol apareceu, Lia sorriu e começou a recuperar a esperança."]], [["Lia, when did the water reach your street last night?", "Lia, quando a água chegou à sua rua ontem à noite?"], ["It came at two a.m., after the rainfall had continued for six hours.", "Chegou às duas da manhã, depois que a chuva tinha continuado por seis horas."], ["Six hours! Did you move your furniture before it started?", "Seis horas! Você tirou os móveis do lugar antes de começar?"], ["Only the sofa. When I woke up, the water had already covered the floor.", "Só o sofá. Quando acordei, a água já tinha coberto o chão."], ["That’s tragic. Where did you stay after the firefighters came?", "Que trágico. Onde você ficou depois que os bombeiros vieram?"], ["At my aunt’s house. I was devastated, but she gave me a warm blanket.", "Na casa da minha tia. Fiquei arrasada, mas ela me deu um cobertor quente."], ["I’m glad you’re safe. The electricity was restored at noon, so I called everyone.", "Que bom que você está bem. A eletricidade voltou ao meio-dia, então liguei para todo mundo."], ["Mine came back too, but the neighbors’ shop had lost all its food.", "A minha voltou também, mas a loja dos vizinhos tinha perdido toda a comida."], ["I can help on Saturday. Some homeless neighbors are staying at the school.", "Posso ajudar no sábado. Alguns vizinhos desabrigados estão ficando na escola."], ["Great, it’s a plan. I’ll bring soup after we finish here.", "Ótimo, combinado. Levo sopa depois que terminarmos aqui."]], ["/r/ em rainfall e restored", "O r inglês não vibra: levante a ponta da língua sem encostar no céu da boca e arredonde os lábios, em rainfall e restored.", ["rainfall", "restored"]], ["When Lia woke up, the water ___ already covered the floor.", "had", "has", "Quando Lia acordou, a água já tinha coberto o chão.", "A água subiu antes de Lia acordar, então a ação anterior usa had + particípio."], [["After the heavy rainfall stopped, many families in Green Hill had lost their homes.", "Depois que a chuva forte parou, muitas famílias de Green Hill tinham perdido suas casas."], ["Only the sofa. When I woke up, the water had already covered the floor.", "Só o sofá. Quando acordei, a água já tinha coberto o chão."]], [{"t": "c", "q": "___ the rainfall had stopped, many families went back home.", "o": ["After", "Before", "During"], "pt": "Depois que a chuva tinha parado, muitas famílias voltaram para casa.", "why": "After liga a ação que veio antes (had stopped) à que veio depois (went)."}, {"t": "l", "say": "When I woke up, the water had already covered the floor.", "o": ["When I woke up, the water had already covered the floor.", "When I wake up, the water had already covered the floor.", "When I woke up, the water has already covered the floor."], "why": "Woke up (passado simples) + had covered (past perfect) mostra a ordem."}, {"t": "b", "pt": "Depois que a chuva parou, a energia voltou.", "w": ["After", "the", "rain", "stopped", "the", "electricity", "came", "back"]}, {"t": "b", "pt": "Quando acordei, a água já tinha subido.", "w": ["When", "I", "woke", "up", "the", "water", "had", "risen"]}]];
