englishB1Plans[14]={"title": "Entrevista com o alpinista no topo", "file": "", "grammar": "Past perfect em perguntas e respostas curtas", "goal": "Pergunte e responda sobre o que já tinha acontecido: Had you…? Yes, I had. / No, I hadn’t.", "words": [["mountaintop", "topo da montanha"], ["breathless", "sem fôlego"], ["stumble", "tropeçar"], ["struggling", "lutando, com dificuldade"], ["tremendous", "enorme, tremendo"], ["trembling", "tremendo (de frio ou medo)"], ["altitude", "altitude"], ["extreme", "extremo"]]};
englishB1Content[14]=[[["Noah had trained for two years before he reached the mountaintop in Peru.", "Noah tinha treinado por dois anos antes de chegar ao topo da montanha no Peru."], ["The reporter asked Noah questions about the extreme cold and the thin air.", "A repórter fez perguntas a Noah sobre o frio extremo e o ar rarefeito."], ["Noah said he had been breathless at that altitude, and his legs were trembling.", "Noah disse que tinha ficado sem fôlego naquela altitude, e as pernas dele estavam tremendo."], ["Twice he had stumbled on the ice, but Mia had held the rope.", "Duas vezes ele tinha tropeçado no gelo, mas Mia tinha segurado a corda."], ["Many people had told him it was impossible, yet he kept struggling upward.", "Muita gente tinha dito que era impossível, mas ele continuou lutando para subir."], ["When he finally stood on the top, he felt a tremendous joy.", "Quando finalmente chegou ao topo, ele sentiu uma alegria enorme."]], [["Noah, congratulations! Had you ever climbed this high before?", "Noah, parabéns! Você já tinha escalado tão alto antes?"], ["No, I hadn’t. My highest climb had been a small hill near home.", "Não, não tinha. Minha maior escalada tinha sido um morro perto de casa."], ["Had you trained for the altitude, or did the thin air surprise you?", "Você tinha treinado para a altitude, ou o ar rarefeito te surpreendeu?"], ["Yes, I had. I slept in a special tent for months, but it was still hard.", "Sim, tinha. Dormi numa barraca especial por meses, mas mesmo assim foi difícil."], ["Had Mia climbed other mountains before you two met?", "A Mia já tinha escalado outras montanhas antes de vocês se conhecerem?"], ["Yes, she had. She had reached five mountaintops, so she led most of the way.", "Sim, tinha. Ela já tinha chegado a cinco topos, então guiou a maior parte do caminho."], ["What about the weather? Was it extreme near the top?", "E o clima? Estava extremo perto do topo?"], ["Extreme! The wind was cold, and I was struggling to breathe for an hour.", "Extremo! O vento estava gelado, e eu lutei para respirar por uma hora."], ["Wow. And how did you feel when you stood there? Was it worth it?", "Uau. E como você se sentiu quando ficou lá em cima? Valeu a pena?"], ["Yes, it was. It was the best day of my life, and I’d do it again.", "Sim, valeu. Foi o melhor dia da minha vida, e eu faria de novo."]], ["/tr/ em trembling e tremendous", "Em tr-, a língua já vai para o r e o som fica perto de “chr”: trembling, tremendous. Não separe t e r.", ["trembling", "tremendous"]], ["___ Noah ever climbed a mountain before this trip?", "Had", "Has", "Noah já tinha escalado uma montanha antes dessa viagem?", "Para perguntar sobre algo anterior a um ponto do passado, coloque Had antes do sujeito."], [["Noah, congratulations! Had you ever climbed this high before?", "Noah, parabéns! Você já tinha escalado tão alto antes?"], ["Yes, she had. She had reached five mountaintops, so she led most of the way.", "Sim, tinha. Ela já tinha chegado a cinco topos, então guiou a maior parte do caminho."]], [{"t": "c", "q": "Had Mia climbed other mountains before? Yes, she ___.", "o": ["had", "did", "has"], "pt": "A Mia já tinha escalado outras montanhas antes? Sim, tinha.", "why": "A resposta curta repete o auxiliar da pergunta: Had… ? Yes, she had."}, {"t": "l", "say": "Had you trained for the altitude?", "o": ["Had you trained for the altitude?", "Did you trained for the altitude?", "Had you train for the altitude?"], "why": "A pergunta usa Had + sujeito + particípio (trained)."}, {"t": "b", "pt": "Você já tinha escalado uma montanha tão alta?", "w": ["Had", "you", "ever", "climbed", "a", "mountain", "this", "high"]}, {"t": "b", "pt": "Sim, ela tinha treinado por dois anos.", "w": ["Yes", "she", "had", "trained", "for", "two", "years"]}]];
