englishB1Plans[15]={"title": "Reunião sobre o projeto atrasado", "file": "", "grammar": "Causa no passado: because / so com past perfect", "goal": "Explique a causa e o resultado de um atraso usando because e so com past perfect.", "words": [["negotiation", "negociação"], ["approval", "aprovação"], ["assistance", "ajuda, assistência"], ["committed", "comprometido"], ["discouraged", "desanimado"], ["representative", "representante"], ["productive", "produtivo"], ["supportive", "que apoia"], ["resolved", "resolvido"], ["strategic", "estratégico"]]};
englishB1Content[15]=[[["The design project was late because the client had changed the plan twice.", "O projeto de design estava atrasado porque o cliente tinha mudado o plano duas vezes."], ["The client’s representative sent the approval late, so the team lost three days.", "A representante do cliente mandou a aprovação tarde, então a equipe perdeu três dias."], ["Kenji was discouraged because the negotiation had lasted more than a month.", "Kenji estava desanimado porque a negociação tinha durado mais de um mês."], ["He had asked his manager for assistance, so she joined the next meeting.", "Ele tinha pedido ajuda à gerente, então ela entrou na reunião seguinte."], ["She was supportive and strategic, and she resolved the problem in one afternoon.", "Ela foi solidária e estratégica, e resolveu o problema em uma tarde."], ["Because everyone felt committed again, the team had a very productive week.", "Como todos voltaram a se sentir comprometidos, a equipe teve uma semana muito produtiva."]], [["Kenji, why is the report still late? Did something happen?", "Kenji, por que o relatório ainda está atrasado? Aconteceu alguma coisa?"], ["Yes. We lost three days because the client had changed the plan again.", "Sim. Perdemos três dias porque o cliente tinha mudado o plano de novo."], ["Again? That’s frustrating. Was the representative aware of the deadline?", "De novo? Que frustrante. A representante sabia do prazo?"], ["I think so, but she was busy, so the approval came very late.", "Acho que sim, mas ela estava ocupada, então a aprovação veio muito tarde."], ["I see. And you felt discouraged, so you stayed quiet instead of asking me?", "Entendi. E você ficou desanimado, então ficou quieto em vez de me perguntar?"], ["A little. I had worked on the negotiation alone, so I thought I should solve it.", "Um pouco. Eu tinha trabalhado sozinho na negociação, então achei que devia resolver."], ["Next time, ask for assistance. I’m supportive, and my door is always open.", "Da próxima vez, peça ajuda. Eu apoio vocês, e minha porta está sempre aberta."], ["Thanks. I was so tired because I had worked every night this week.", "Obrigado. Eu estava muito cansado porque tinha trabalhado todas as noites desta semana."], ["Let’s plan a strategic meeting tomorrow, so we can finish the report by Friday.", "Vamos marcar uma reunião estratégica amanhã, para terminar o relatório até sexta."], ["Perfect. I’m committed to finishing it, so we’ll get it resolved.", "Perfeito. Estou comprometido em terminar, então vamos resolver isso."]], ["/ə/ fraco em approval e assistance", "A primeira vogal de approval e assistance é fraca (/ə/), quase não se ouve; a força cai na sílaba seguinte: a-PROV-al, a-SIS-tance.", ["approval", "assistance"]], ["The project was late ___ the client had changed the plan twice.", "because", "so", "O projeto estava atrasado porque o cliente tinha mudado o plano duas vezes.", "Because introduz a causa; so introduz o resultado."], [["The design project was late because the client had changed the plan twice.", "O projeto de design estava atrasado porque o cliente tinha mudado o plano duas vezes."], ["Thanks. I was so tired because I had worked every night this week.", "Obrigado. Eu estava muito cansado porque tinha trabalhado todas as noites desta semana."]], [{"t": "c", "q": "Kenji felt discouraged, ___ he asked his manager for help.", "o": ["so", "because", "although"], "pt": "Kenji se sentiu desanimado, então pediu ajuda à gerente.", "why": "So liga o resultado: o desânimo levou ao pedido de ajuda."}, {"t": "l", "say": "He lost three days because the client had changed the plan.", "o": ["He lost three days because the client had changed the plan.", "He lost three days so the client had changed the plan.", "He lost three days because the client had change the plan."], "why": "Because + had changed explica a causa da perda de tempo."}, {"t": "b", "pt": "Ele estava cansado porque tinha trabalhado a noite toda.", "w": ["He", "was", "tired", "because", "he", "had", "worked", "all", "night"]}, {"t": "b", "pt": "Ele pediu ajuda, então ela veio à reunião.", "w": ["He", "asked", "for", "help", "so", "she", "came"]}]];
