englishB1Plans[16]={"title": "Festa-surpresa para a vovó", "file": "", "grammar": "Contar uma história em ordem: first, then, by then, afterwards", "goal": "Conte uma história em ordem usando first, then, by then e afterwards.", "words": [["giggle", "dar risadinhas"], ["sparkle", "brilhar, cintilar"], ["overjoyed", "muito feliz, radiante"], ["laughter", "risada, gargalhada"], ["startled", "assustado, surpreso"], ["unfold", "se desenrolar"], ["festive", "festivo"], ["hearty", "caloroso, forte"], ["thrilled", "empolgado"], ["ecstatic", "em êxtase"]]};
englishB1Content[16]=[[["First, the cousins decorated the living room with festive paper stars.", "Primeiro, os primos decoraram a sala com estrelas de papel festivas."], ["Then they hid behind the sofa, trying not to giggle.", "Depois eles se esconderam atrás do sofá, tentando não dar risadinhas."], ["By then, the cake was ready, and the candles began to sparkle.", "Nessa hora, o bolo estava pronto, e as velas começaram a brilhar."], ["When Grandma Rosa opened the door, she looked startled for one second.", "Quando a vovó Rosa abriu a porta, ela pareceu assustada por um segundo."], ["Then she saw everyone, and she felt overjoyed because all her family was there.", "Então ela viu todos e ficou radiante porque toda a família dela estava lá."], ["Afterwards, laughter filled the house, and the party continued until midnight.", "Depois, risadas encheram a casa, e a festa continuou até a meia-noite."]], [["Omar, I couldn’t come. Please tell me everything about the party.", "Omar, eu não pude ir. Por favor, me conte tudo sobre a festa."], ["Well, first we picked up the cake, and then we decorated the house.", "Bem, primeiro buscamos o bolo, e depois decoramos a casa."], ["Did Grandma suspect anything before she arrived?", "A vovó desconfiou de alguma coisa antes de chegar?"], ["Not at all. By then she was in the car, and Lia was keeping her busy.", "Nada. Nessa hora ela estava no carro, e a Lia a mantinha ocupada."], ["Ha! And how did she react when she walked in?", "Ha! E como ela reagiu quando entrou?"], ["She screamed, and then she gave everyone a hearty hug. She was thrilled!", "Ela gritou, e depois deu um abraço bem forte em todo mundo. Estava empolgada!"], ["Aww, that sounds wonderful. Did she like the gift from the cousins?", "Aww, que lindo. Ela gostou do presente dos primos?"], ["Yes! She opened the box slowly, and the surprise began to unfold.", "Sim! Ela abriu a caixa devagar, e a surpresa começou a se revelar."], ["I’m sorry I missed it. Afterwards, did you take any photos?", "Sinto muito ter perdido. Depois, vocês tiraram fotos?"], ["Of course. I’ll send them tonight, and you’ll see her ecstatic face.", "Claro. Vou mandar hoje à noite, e você vai ver o rosto em êxtase dela."]], ["/ɪ/ curto em giggle e festive", "O i de giggle e festive é curto e relaxado (/ɪ/), quase um “i” engolido; não alongue como o “ii” de “see”.", ["giggle", "festive"]], ["___ then, the cake was ready, and the candles began to sparkle.", "By", "At", "Nessa hora, o bolo já estava pronto, e as velas começaram a brilhar.", "By then é a expressão fixa para “nessa altura, já”."], [["By then, the cake was ready, and the candles began to sparkle.", "Nessa hora, o bolo estava pronto, e as velas começaram a brilhar."], ["Not at all. By then she was in the car, and Lia was keeping her busy.", "Nada. Nessa hora ela estava no carro, e a Lia a mantinha ocupada."]], [{"t": "c", "q": "Lia kept Grandma busy, and ___ then the cake was ready.", "o": ["by", "in", "at"], "pt": "A Lia manteve a vovó ocupada, e nessa hora o bolo já estava pronto.", "why": "By then = nessa altura, já; marca o que estava pronto a esse ponto da história."}, {"t": "l", "say": "Afterwards, laughter filled the house.", "o": ["Afterwards, laughter filled the house.", "Afterward, laughter fills the house.", "After, laughter filled the house."], "why": "Afterwards fecha a história em ordem e pede o passado (filled)."}, {"t": "b", "pt": "Primeiro, nós decoramos a sala.", "w": ["First", "we", "decorated", "the", "living", "room"]}, {"t": "b", "pt": "Então ela viu todos e ficou muito feliz.", "w": ["Then", "she", "saw", "everyone", "and", "felt", "overjoyed"]}]];
