englishB1Plans[17]={"title": "Reencontro de ex-colegas no café", "file": "", "grammar": "Past perfect vs passado simples vs present perfect", "goal": "Escolha entre passado simples, present perfect e past perfect ao contar o que mudou na vida de um amigo.", "words": [["schoolmate", "colega de escola"], ["lifelong", "de toda a vida"], ["former", "antigo, ex-"], ["divorced", "divorciado"], ["settled", "estabelecido, instalado"], ["reunite", "reunir de novo"], ["admiration", "admiração"], ["coincidence", "coincidência"]]};
englishB1Content[17]=[[["Sam met his former schoolmate Elena at a cafe he had never visited before.", "Sam encontrou sua antiga colega de escola Elena num café que ele nunca tinha visitado antes."], ["It was a coincidence, because they had both moved to Seattle this year.", "Foi uma coincidência, porque os dois tinham se mudado para Seattle neste ano."], ["Elena has lived there for two years and feels settled in her small apartment.", "Elena mora lá há dois anos e se sente instalada no seu apartamento pequeno."], ["Sam was divorced, but he felt glad to reunite with a lifelong friend.", "Sam era divorciado, mas ficou contente em reencontrar uma amiga de toda a vida."], ["Sam had always felt admiration for Elena because she had won every science contest.", "Sam sempre tinha sentido admiração por Elena porque ela tinha ganhado todos os concursos de ciências."], ["They laughed for an hour, and now they have promised to meet every month.", "Eles riram por uma hora, e agora prometeram se encontrar todo mês."]], [["Elena? I can’t believe it! I last saw you at graduation, ten years ago.", "Elena? Não acredito! Vi você pela última vez na formatura, dez anos atrás."], ["Sam! What a coincidence. I’ve lived in this city for two years now.", "Sam! Que coincidência. Moro nesta cidade há dois anos."], ["Really? I moved here last month, after I had finished my contract in Boston.", "Sério? Me mudei para cá no mês passado, depois de terminar meu contrato em Boston."], ["That’s great. So where have you been working since then?", "Que ótimo. E onde você tem trabalhado desde então?"], ["I’ve worked at a bank since June. Before that, I had managed a bakery.", "Trabalho num banco desde junho. Antes disso, eu tinha administrado uma padaria."], ["A bakery! In school you always brought cookies, so I’m not surprised.", "Uma padaria! Na escola você sempre levava biscoitos, então não me surpreende."], ["True. And you? Are you settled here, or do you miss your old town?", "Verdade. E você? Está instalada aqui, ou sente falta da sua cidade antiga?"], ["I’m settled now. I’ve made new friends, though I miss my family.", "Estou instalada agora. Fiz novos amigos, embora sinta falta da família."], ["Well, you have one more friend now. Why don’t we reunite the old group next month?", "Bem, agora você tem mais um amigo. Por que não reunimos a turma antiga no mês que vem?"], ["Perfect idea. I’ll call everyone tonight, and we’ll choose a date.", "Ótima ideia. Vou ligar para todos hoje à noite, e escolhemos uma data."]], ["/k/ em schoolmate e coincidence", "Em school o ch soa /k/ (SKUL), não /tʃ/ como em chair; o c inicial de coincidence também é /k/.", ["schoolmate", "coincidence"]], ["I’ve worked at a bank since June. Before that, I ___ managed a bakery.", "had", "have", "Trabalho num banco desde junho. Antes disso, eu tinha administrado uma padaria.", "Before that aponta para um passado anterior a outro passado, então usamos had + particípio."], [["It was a coincidence, because they had both moved to Seattle this year.", "Foi uma coincidência, porque os dois tinham se mudado para Seattle neste ano."], ["I’ve worked at a bank since June. Before that, I had managed a bakery.", "Trabalho num banco desde junho. Antes disso, eu tinha administrado uma padaria."]], [{"t": "c", "q": "Elena ___ in this city for two years, so she knows the best cafes.", "o": ["has lived", "lived", "had lived"], "pt": "Elena mora nesta cidade há dois anos, então conhece os melhores cafés.", "why": "Has lived: present perfect com for liga o passado ao presente, e ela ainda mora lá."}, {"t": "l", "say": "They laughed for an hour, and now they have promised to meet every month.", "o": ["They laughed for an hour, and now they have promised to meet every month.", "They laughed for an hour, and now they had promised to meet every month.", "They have laughed for an hour, and now they promised to meet every month."], "why": "Laughed é um fato passado; have promised é um resultado que vale agora."}, {"t": "b", "pt": "Eu me mudei para cá no mês passado.", "w": ["I", "moved", "here", "last", "month"]}, {"t": "b", "pt": "Antes disso, eu tinha administrado uma padaria.", "w": ["Before", "that", "I", "had", "managed", "a", "bakery"]}]];
