englishB1Plans[18]={"title": "Acampamento sem preparação", "file": "", "grammar": "Past perfect negativo: hadn’t + particípio (surpresas e arrependimentos)", "goal": "Explique o que não tinha acontecido ou o que você não tinha feito antes de um problema, com hadn’t + particípio.", "words": [["rotten", "estragado, podre"], ["shaky", "trêmulo, instável"], ["unprepared", "despreparado"], ["drenched", "encharcado"], ["swamp", "pântano"], ["starving", "morrendo de fome"], ["slipped", "escorregou"], ["stung", "picado (por inseto)"], ["bitten", "mordido, picado"]]};
englishB1Content[18]=[[["Tom and Sam went camping, but they were completely unprepared for the weather.", "Tom e Sam foram acampar, mas estavam totalmente despreparados para o clima."], ["They hadn’t checked the forecast, so the rain left them drenched by noon.", "Eles não tinham checado a previsão, então a chuva os deixou encharcados ao meio-dia."], ["Their tent was near a swamp, and they hadn’t brought bug spray.", "A barraca deles ficava perto de um pântano, e eles não tinham levado repelente."], ["Tom slipped on a wet rock because he hadn’t worn his hiking boots.", "Tom escorregou numa pedra molhada porque não tinha calçado as botas de trilha."], ["At night they were starving, but the sandwiches they had packed were rotten.", "À noite eles estavam morrendo de fome, mas os sanduíches que tinham levado estavam estragados."], ["Sam felt shaky and cold, so they drove home before sunrise.", "Sam se sentia trêmulo e com frio, então eles voltaram para casa antes do nascer do sol."]], [["Look at my arms, Sam! I’ve been bitten twenty times, and a bee stung my hand.", "Olhe meus braços, Sam! Fui picado vinte vezes, e uma abelha ferroou minha mão."], ["I’m not surprised. We hadn’t brought bug spray, and we camped next to a swamp.", "Não me surpreende. Não tínhamos levado repelente, e acampamos ao lado de um pântano."], ["True. And I hadn’t thought about the rain either. My jacket is still drenched.", "Verdade. E eu também não tinha pensado na chuva. Minha jaqueta ainda está encharcada."], ["Neither had I. I just assumed it would be sunny all weekend.", "Nem eu. Eu só supus que faria sol o fim de semana todo."], ["And the food! The sandwiches were rotten, so I was starving all night.", "E a comida! Os sanduíches estavam estragados, então passei a noite morrendo de fome."], ["You looked shaky after you slipped near the river, and I was worried.", "Você parecia trêmulo depois de escorregar perto do rio, e eu fiquei preocupado."], ["Yes, I was unprepared for everything on this trip.", "Sim, eu estava despreparado para tudo nessa viagem."], ["Next time we’ll check the weather, and we’ll bring good boots and bug spray.", "Da próxima vez vamos checar o tempo e levar botas boas e repelente."], ["Deal. And we’ll pack fresh food and a bigger tent.", "Combinado. E vamos levar comida fresca e uma barraca maior."], ["Absolutely. And first, I’ll buy you a huge hot breakfast.", "Com certeza. E primeiro, vou te pagar um café da manhã bem grande e quente."]], ["/ʌ/ em stung e unprepared", "O /ʌ/ é um som curto e relaxado, perto de um “â” rápido: stung, unprepared, sun. Não abra a boca como no “a” de “casa”.", ["stung", "unprepared"]], ["Tom slipped because he ___ worn his hiking boots.", "hadn’t", "didn’t", "Tom escorregou porque não tinha calçado as botas de trilha.", "Antes de um particípio (worn), o negativo do past perfect é hadn’t."], [["Their tent was near a swamp, and they hadn’t brought bug spray.", "A barraca deles ficava perto de um pântano, e eles não tinham levado repelente."], ["I’m not surprised. We hadn’t brought bug spray, and we camped next to a swamp.", "Não me surpreende. Não tínhamos levado repelente, e acampamos ao lado de um pântano."]], [{"t": "c", "q": "We camped next to a swamp, and we ___ brought bug spray.", "o": ["hadn’t", "haven’t", "don’t"], "pt": "Acampamos ao lado de um pântano, e não tínhamos levado repelente.", "why": "Hadn’t + brought mostra o que não tinha sido feito antes do problema."}, {"t": "l", "say": "I hadn’t thought about the rain either.", "o": ["I hadn’t thought about the rain either.", "I haven’t thought about the rain either.", "I hadn’t think about the rain either."], "why": "Hadn’t thought: hadn’t + particípio (thought)."}, {"t": "b", "pt": "Nós não tínhamos trazido repelente.", "w": ["We", "hadn’t", "brought", "bug", "spray"]}, {"t": "b", "pt": "Tom escorregou porque não tinha calçado as botas.", "w": ["Tom", "slipped", "because", "he", "hadn’t", "worn", "his", "boots"]}]];
