englishB1Plans[19]={"title": "Uma viagem em que quase tudo deu errado", "file": "", "grammar": "Revisão: past perfect, by the time, because/so, first/then/afterwards", "goal": "Conte uma viagem cheia de problemas na ordem certa, revisando past perfect e as palavras do bloco.", "words": [["turbulence", "turbulência"], ["nightmare", "pesadelo"], ["misfortune", "azar, infortúnio"], ["misplaced", "extraviado, perdido"], ["hardship", "dificuldade, adversidade"], ["incredibly", "incrivelmente"], ["helpless", "sem saída, impotente"], ["hopeless", "sem esperança"]]};
englishB1Content[19]=[[["Priya’s trip to Chicago started badly, because the flight had hit terrible turbulence.", "A viagem de Priya a Chicago começou mal, porque o voo tinha enfrentado uma turbulência terrível."], ["When she landed, the airline told her they had misplaced her suitcase.", "Quando ela pousou, a companhia aérea disse que tinha extraviado a mala dela."], ["She felt helpless, but a kind worker had already started to search for it.", "Ela se sentiu impotente, mas uma funcionária gentil já tinha começado a procurá-la."], ["By the time she reached the hotel, the manager had given her room away.", "Quando ela chegou ao hotel, o gerente já tinha dado o quarto dela a outra pessoa."], ["It was a nightmare, and she felt hopeless for a few minutes.", "Foi um pesadelo, e ela se sentiu sem esperança por alguns minutos."], ["Incredibly, the suitcase arrived at midnight, and the manager found her a better room.", "Incrivelmente, a mala chegou à meia-noite, e o gerente achou um quarto melhor para ela."]], [["Priya, how was your trip? Did you land safely in Chicago?", "Priya, como foi a viagem? Você pousou bem em Chicago?"], ["Yes, but it was a nightmare. We hit terrible turbulence for almost an hour.", "Sim, mas foi um pesadelo. Pegamos turbulência terrível por quase uma hora."], ["Oh no! After that, did you get your suitcase quickly?", "Ai, não! Depois disso, você pegou a mala rápido?"], ["No. The airline had misplaced it, so I stood there feeling helpless.", "Não. A companhia tinha extraviado a mala, então fiquei lá me sentindo impotente."], ["What a misfortune. Did they find it at least?", "Que azar. Pelo menos eles encontraram?"], ["Eventually. It arrived at midnight, after the hotel had given away my room.", "No fim, sim. Chegou à meia-noite, depois que o hotel tinha dado meu quarto a outra pessoa."], ["Seriously? That’s a lot of hardship for one day. What did you do?", "Sério? É muita adversidade para um dia só. O que você fez?"], ["I felt hopeless, but the manager apologized and found me a bigger room.", "Me senti sem esperança, mas o gerente pediu desculpas e arrumou um quarto maior."], ["That’s incredibly kind of him. I’m glad the day ended well.", "Que gentileza incrível dele. Que bom que o dia terminou bem."], ["Yes, it did. Tomorrow I’ll call you before my meeting at nine.", "Terminou, sim. Amanhã ligo para você antes da minha reunião às nove."]], ["/aɪ/ em nightmare e flight", "O ditongo /aɪ/ começa aberto e termina num i curto: nightmare, flight. O gh de flight é mudo.", ["nightmare", "flight"]], ["When she landed, the airline told her they ___ misplaced her suitcase.", "had", "have", "Quando ela pousou, a companhia aérea disse que tinha extraviado a mala dela.", "O extravio veio antes do aviso, então usamos had + particípio."], [["By the time she reached the hotel, the manager had given her room away.", "Quando ela chegou ao hotel, o gerente já tinha dado o quarto dela a outra pessoa."], ["No. The airline had misplaced it, so I stood there feeling helpless.", "Não. A companhia tinha extraviado a mala, então fiquei lá me sentindo impotente."]], [{"t": "c", "q": "She felt hopeless ___ the hotel had given her room away.", "o": ["because", "so", "while"], "pt": "Ela se sentiu sem esperança porque o hotel tinha dado o quarto dela a outra pessoa.", "why": "Because introduz a causa do sentimento."}, {"t": "l", "say": "By the time she reached the hotel, the manager had given her room away.", "o": ["By the time she reached the hotel, the manager had given her room away.", "By the time she reached the hotel, the manager has given her room away.", "By the time she reaches the hotel, the manager had given her room away."], "why": "By the time + passado simples pede o past perfect (had given) para a ação anterior."}, {"t": "b", "pt": "Ela se sentiu impotente, mas a funcionária ajudou.", "w": ["She", "felt", "helpless", "but", "the", "worker", "helped"]}, {"t": "b", "pt": "O voo teve uma turbulência terrível.", "w": ["The", "flight", "hit", "terrible", "turbulence"]}]];
