englishB1MiniStories[19]=["A viagem da Ana", "First, Ana’s taxi stopped at the roadside, and she hurriedly called the airline.~Primeiro, o táxi da Ana parou no acostamento, e ela ligou às pressas para a companhia aérea.|By the time she reached the airport, her flight had already left.~Quando ela chegou ao aeroporto, o voo dela já tinha partido.|She felt desperate, because she had never missed a flight before.~Ela se sentiu desesperada, porque nunca tinha perdido um voo antes.|Then she found a seat on a later plane, so she calmed down.~Então ela achou um lugar num voo mais tarde, e se acalmou.|At the hotel, the staff had misplaced her reservation, and she felt helpless.~No hotel, a equipe tinha perdido a reserva dela, e ela se sentiu impotente.|Her friend Omar had planned a dinner, so he waited for two hours.~O amigo dela, Omar, tinha planejado um jantar, então esperou por duas horas.|She hadn’t eaten since morning, so she was starving when the pizza arrived.~Ela não tinha comido desde a manhã, então estava morrendo de fome quando a pizza chegou.|After she finished the pizza, the manager gave her a gorgeous room.~Depois que ela terminou a pizza, o gerente lhe deu um quarto lindíssimo.|Afterwards, she called Omar, and they laughed about the whole nightmare.~Depois, ela ligou para o Omar, e eles riram de todo aquele pesadelo.|Now she says that this trip has taught her to leave early.~Agora ela diz que essa viagem a ensinou a sair cedo."];
englishB1Plans[20]={"title": "Sonhando com um sítio no interior", "file": "", "grammar": "Segunda condicional: If I had…, I would… (situações irreais)", "goal": "Fale de situações irreais usando If + passado simples, would + verbo.", "words": [["income", "renda"], ["invest", "investir"], ["mortgage", "financiamento da casa"], ["luxury", "luxo"], ["financial", "financeiro"], ["fund", "fundo (reserva)"], ["quit my job", "largar meu emprego"], ["take a risk", "correr um risco"], ["make a living", "ganhar a vida"], ["wealthy", "rico"]]};
englishB1Content[20]=[[["Ana and Ben are sitting at the kitchen table, checking their monthly income.", "Ana e Ben estão sentados à mesa da cozinha, conferindo a renda mensal deles."], ["If they had a bigger income, they would pay the mortgage much faster.", "Se tivessem uma renda maior, pagariam o financiamento bem mais rápido."], ["Ben says that if he were wealthy, he would invest in a small farm.", "Ben diz que, se fosse rico, investiria num pequeno sítio."], ["Ana laughs, because a farm isn't exactly a luxury for a family like theirs.", "Ana ri, porque um sítio não é exatamente um luxo para uma família como a deles."], ["If Ben had a farm, he would still need a way to make a living.", "Se Ben tivesse um sítio, ainda precisaria de um jeito de ganhar a vida."], ["They close the laptop and promise to start a small fund for their dream.", "Eles fecham o notebook e prometem começar um pequeno fundo para o sonho deles."]], [["If we had more money, what would you do first, Ben?", "Se tivéssemos mais dinheiro, o que você faria primeiro, Ben?"], ["Honestly, I would quit my job and take a risk for once.", "Sinceramente, eu largaria meu emprego e correria um risco pelo menos uma vez."], ["Seriously? And how would we pay the bills while you look for land?", "Sério? E como pagaríamos as contas enquanto você procura um terreno?"], ["We could sell eggs and vegetables at the weekend market.", "Poderíamos vender ovos e verduras na feira de fim de semana."], ["That sounds nice, but the financial side worries me a lot.", "Parece bom, mas o lado financeiro me preocupa muito."], ["I know. If we saved two hundred dollars a month, we would have a good fund in two years.", "Eu sei. Se economizássemos duzentos dólares por mês, teríamos uma boa reserva em dois anos."], ["That's a start. And if we sold the old car, we would have more.", "Já é um começo. E se vendêssemos o carro velho, teríamos mais."], ["Good idea. Let's open a separate account for the farm tonight.", "Boa ideia. Vamos abrir uma conta separada para o sítio hoje à noite."], ["Okay, I'll look for a bank with good interest rates tomorrow morning.", "Certo, vou procurar um banco com boas taxas de juros amanhã de manhã."], ["Deal. Then tonight we only dream, and tomorrow we start.", "Fechado. Então hoje à noite só sonhamos, e amanhã começamos."]], ["/ʌ/ em fund e income", "O u de fund e o o de income soam como /ʌ/, um a curto e relaxado, quase um é aberto da boca. Não pronuncie “fúnd” com u de português.", ["fund", "income"]], ["If we ___ a bigger income, we would pay the mortgage faster.", "had", "have", "Se tivéssemos uma renda maior, pagaríamos o financiamento mais rápido.", "Para situação irreal no presente, use If + passado simples (had) e would + verbo no resultado."], [["If they had a bigger income, they would pay the mortgage much faster.", "Se tivessem uma renda maior, pagariam o financiamento bem mais rápido."], ["Ben says that if he were wealthy, he would invest in a small farm.", "Ben diz que, se fosse rico, investiria num pequeno sítio."]], [{"t": "c", "q": "If I ___ a lot of money, I would buy a farm.", "o": ["had", "have", "would have"], "pt": "Se eu tivesse muito dinheiro, eu compraria um sítio.", "why": "Com If irreal, o verbo da condição vai no passado simples: had."}, {"t": "l", "say": "If we had more money, we would invest in a farm.", "o": ["If we had more money, we would invest in a farm.", "If we have more money, we will invest in a farm.", "If we had more money, we invest in a farm."], "why": "A frase certa usa had na condição e would no resultado."}, {"t": "b", "pt": "Se eu fosse rico, eu investiria.", "w": ["If", "I", "were", "wealthy", "I", "would", "invest"]}, {"t": "b", "pt": "Se nós tivéssemos mais renda, ficaríamos tranquilos.", "w": ["If", "we", "had", "more", "income", "we", "would", "relax"]}]];
