englishB1Plans[21]={"title": "Aconselhando Lia depois de um mês exaustivo", "file": "", "grammar": "If I were you, I would… para dar conselhos", "goal": "Dê um conselho amigável usando If I were you, I would….", "words": [["negotiate", "negociar"], ["benefits", "benefícios"], ["overworked", "sobrecarregado de trabalho"], ["resign", "pedir demissão"], ["motivation", "motivação"], ["burden", "peso, fardo"], ["attend", "comparecer a"], ["agreement", "acordo"], ["think twice", "pensar duas vezes"], ["make up my mind", "decidir-me"]]};
englishB1Content[21]=[[["Lia is overworked, and her motivation gets lower every week.", "Lia está sobrecarregada, e a motivação dela fica menor a cada semana."], ["Her manager gave her another burden last Friday: a report for the whole team.", "O gerente deu a ela mais um peso na sexta passada: um relatório para a equipe toda."], ["Lia wants to resign, but she also needs the benefits of her current job.", "Lia quer pedir demissão, mas também precisa dos benefícios do emprego atual."], ["Her friend Tom says, 'If I were you, I would try to negotiate first.'", "O amigo Tom diz: 'Se eu fosse você, tentaria negociar primeiro.'"], ["He thinks the company would accept a better agreement if Lia asked politely.", "Ele acha que a empresa aceitaria um acordo melhor se Lia pedisse com educação."], ["Lia thanks him and decides to attend a meeting with her manager on Monday.", "Lia agradece e decide comparecer a uma reunião com o gerente na segunda."]], [["I can't take it anymore, Tom. I think I'm going to resign.", "Não aguento mais, Tom. Acho que vou pedir demissão."], ["Wait. If I were you, I would think twice before doing that.", "Espere. Se eu fosse você, pensaria duas vezes antes de fazer isso."], ["But I'm so tired. I work until eight every day, even on Fridays.", "Mas estou tão cansada. Trabalho até as oito todo dia, até às sextas."], ["I understand. If I were you, I would ask for a shorter schedule first.", "Entendo. Se eu fosse você, pediria um horário mais curto primeiro."], ["My manager never listens to me, though. I'm not sure it would work.", "O meu gerente nunca me ouve, porém. Não tenho certeza de que funcionaria."], ["It might not, but you would still keep your health benefits.", "Pode ser que não, mas você ainda manteria o seu plano de saúde."], ["You're right. I still can't make up my mind, but I'll talk to her tomorrow.", "Você tem razão. Ainda não consigo me decidir, mas vou falar com ela amanhã."], ["Great. Write down three goals tonight, and I'll help you practice.", "Ótimo. Anote três metas hoje à noite, e eu ajudo você a ensaiar."]], ["/ʃ/ em negotiate e motivation", "O -ti- de negotiate e de motivation vira /ʃ/, como o “x” de “xícara”: ne-GO-shi-ate, mo-ti-VEI-shun. Não diga “tiêiti”.", ["negotiate", "motivation"]], ["If I ___ you, I would talk to your manager.", "were", "was", "Se eu fosse você, eu falaria com o seu gerente.", "Em If I were you, usa-se were para todas as pessoas, mesmo com I."], [["Her friend Tom says, 'If I were you, I would try to negotiate first.'", "O amigo Tom diz: 'Se eu fosse você, tentaria negociar primeiro.'"], ["Wait. If I were you, I would think twice before doing that.", "Espere. Se eu fosse você, pensaria duas vezes antes de fazer isso."]], [{"t": "c", "q": "If I ___ you, I wouldn't resign yet.", "o": ["were", "am", "was"], "pt": "Se eu fosse você, não pediria demissão ainda.", "why": "Para dar conselho, use If I were you + would."}, {"t": "l", "say": "If I were you, I would negotiate first.", "o": ["If I were you, I would negotiate first.", "If I was you, I will negotiate first.", "If I am you, I would negotiate first."], "why": "Conselho correto: If I were you, I would + verbo."}, {"t": "b", "pt": "Se eu fosse você, pensaria duas vezes.", "w": ["If", "I", "were", "you", "I", "would", "think", "twice"]}, {"t": "b", "pt": "Se eu fosse você, negociaria.", "w": ["If", "I", "were", "you", "I", "would", "negotiate"]}]];
