englishB1Plans[22]={"title": "Comparando duas cidades para recomeçar", "file": "", "grammar": "Would, could e might nos resultados das hipóteses", "goal": "Use would, could e might para falar de resultados possíveis de uma hipótese.", "words": [["location", "localização"], ["economy", "economia"], ["nightlife", "vida noturna"], ["adapt", "adaptar-se"], ["industry", "indústria, setor"], ["cultural", "cultural"], ["employment", "emprego"], ["opportunity", "oportunidade"], ["head start", "vantagem inicial"], ["get along with", "dar-se bem com"]]};
englishB1Content[22]=[[["Omar is thinking about moving to Chicago, and the location of the office matters.", "Omar está pensando em se mudar para Chicago, e a localização do escritório importa."], ["The economy there is strong, and the tech industry offers a great employment opportunity.", "A economia de lá é forte, e o setor de tecnologia oferece uma ótima oportunidade de emprego."], ["He might miss his quiet life, but the nightlife and cultural events would be exciting.", "Ele talvez sinta falta da vida tranquila, mas a vida noturna e os eventos culturais seriam empolgantes."], ["If he moved, he could get a head start on his career.", "Se ele se mudasse, poderia ter uma vantagem inicial na carreira."], ["He would need time to adapt, and he might not get along with every neighbor.", "Ele precisaria de tempo para se adaptar, e talvez não se desse bem com todos os vizinhos."], ["Still, Omar feels that he would learn more if he took the offer.", "Mesmo assim, Omar sente que aprenderia mais se aceitasse a proposta."]], [["Would you really move to Chicago for this job, Omar?", "Você realmente se mudaria para Chicago por esse emprego, Omar?"], ["I might. The salary would be better, and I could save more.", "Talvez. O salário seria melhor, e eu poderia economizar mais."], ["But it could be hard. You would miss your family and your friends.", "Mas poderia ser difícil. Você sentiria falta da família e dos amigos."], ["True, but I could visit them every month. It's only a short flight.", "Verdade, mas eu poderia visitá-los todo mês. É só um voo curto."], ["What if you didn't like the city? You might feel lonely there.", "E se você não gostasse da cidade? Poderia se sentir sozinho lá."], ["I would adapt in a few weeks, I think. I always do.", "Eu me adaptaria em poucas semanas, acho. Sempre me adapto."], ["Well, if you asked me, I would say go for it.", "Bem, se você me perguntasse, eu diria para ir em frente."], ["Thanks, Mia. I would call my boss tomorrow and accept the offer.", "Obrigado, Mia. Eu ligaria para o meu chefe amanhã e aceitaria a proposta."]], ["/aɪ/ em nightlife e might", "Em nightlife e might, o i soa como /aɪ/, igual ao “ai” de “pai”. O gh em might é mudo: diga “máit”, sem o “gue”.", ["nightlife", "might"]], ["If she moved to Chicago, she ___ have more opportunities.", "would", "will", "Se ela se mudasse para Chicago, teria mais oportunidades.", "Com If + passado simples (hipótese), o resultado usa would, e não will."], [["If he moved, he could get a head start on his career.", "Se ele se mudasse, poderia ter uma vantagem inicial na carreira."], ["I might. The salary would be better, and I could save more.", "Talvez. O salário seria melhor, e eu poderia economizar mais."]], [{"t": "c", "q": "If we lived downtown, we ___ walk to work.", "o": ["could", "can", "will"], "pt": "Se morássemos no centro, poderíamos ir a pé ao trabalho.", "why": "Resultado possível de hipótese: could + verbo."}, {"t": "l", "say": "If he moved, he might feel lonely.", "o": ["If he moved, he might feel lonely.", "If he moved, he will feel lonely.", "If he moves, he might felt lonely."], "why": "Hipótese: If + passado, might + verbo simples."}, {"t": "b", "pt": "Eu poderia me adaptar em poucas semanas.", "w": ["I", "could", "adapt", "in", "a", "few", "weeks"]}, {"t": "b", "pt": "Se eu me mudasse, eu poderia economizar mais.", "w": ["If", "I", "moved", "I", "could", "save", "more"]}]];
