englishB1Plans[23]={"title": "Os vizinhos barulhentos do terceiro andar", "file": "", "grammar": "Wish + passado: desejos sobre o presente", "goal": "Expresse um desejo sobre o presente com I wish + passado simples.", "words": [["noisily", "de forma barulhenta"], ["loudspeaker", "alto-falante"], ["tolerate", "tolerar"], ["privacy", "privacidade"], ["disturbance", "perturbação"], ["miserable", "infeliz"], ["irritate", "irritar"], ["annoyance", "incômodo"], ["put up with", "aguentar"], ["at least", "pelo menos"]]};
englishB1Content[23]=[[["Kenji lives on the third floor, and his neighbors party noisily every Friday night.", "Kenji mora no terceiro andar, e os vizinhos fazem festa barulhenta toda sexta à noite."], ["Last night, a loudspeaker played music until two in the morning.", "Ontem à noite, um alto-falante tocou música até as duas da manhã."], ["The disturbance is a big annoyance, and he wishes he lived somewhere quiet.", "A perturbação é um grande incômodo, e ele gostaria de morar num lugar silencioso."], ["He wishes his neighbors respected his privacy, but they just laugh at him.", "Ele gostaria que os vizinhos respeitassem sua privacidade, mas eles só riem dele."], ["He can't tolerate it much longer, and he feels miserable at work.", "Ele não consegue tolerar isso por muito mais tempo e se sente infeliz no trabalho."], ["At least his landlord says he will talk to them on Monday.", "Pelo menos o senhorio diz que vai falar com eles na segunda."]], [["I wish my neighbors weren't so loud. It really irritates me.", "Eu queria que meus vizinhos não fossem tão barulhentos. Isso me irrita muito."], ["I'm sorry, Kenji. Have you talked to them about the noise?", "Sinto muito, Kenji. Você já conversou com eles sobre o barulho?"], ["Twice. They said sorry, but then they did it again last Friday.", "Duas vezes. Pediram desculpas, mas fizeram de novo sexta passada."], ["That's terrible. You should write to your landlord and ask him to help.", "Que horror. Você devia escrever ao senhorio e pedir ajuda."], ["Good idea. I wish I had his email, but I only have his phone number.", "Boa ideia. Queria ter o e-mail dele, mas só tenho o telefone."], ["Then call him tomorrow. Nobody should have to put up with that every weekend.", "Então ligue amanhã. Ninguém devia ter que aguentar isso todo fim de semana."], ["You're right. I'll call at nine, before my first meeting.", "Você tem razão. Vou ligar às nove, antes da minha primeira reunião."], ["Perfect. And if it continues, you can sleep at my place on Fridays.", "Perfeito. E se continuar, você pode dormir na minha casa às sextas."]], ["/ɔɪ/ em noisily e annoyance", "Em noisily e annoyance, o oi soa /ɔɪ/, como em “boi”. Em annoyance, a sílaba forte é NOI: a-NOI-ans.", ["noisily", "annoyance"]], ["I wish my neighbors ___ so loud.", "weren't", "aren't", "Eu queria que meus vizinhos não fossem tão barulhentos.", "Wish sobre o presente pede passado simples (weren't), não presente."], [["The disturbance is a big annoyance, and he wishes he lived somewhere quiet.", "A perturbação é um grande incômodo, e ele gostaria de morar num lugar silencioso."], ["I wish my neighbors weren't so loud. It really irritates me.", "Eu queria que meus vizinhos não fossem tão barulhentos. Isso me irrita muito."]], [{"t": "c", "q": "I wish I ___ a quieter apartment.", "o": ["had", "have", "would have"], "pt": "Queria ter um apartamento mais silencioso.", "why": "Desejo sobre o presente: wish + passado simples (had)."}, {"t": "l", "say": "I wish he lived in a quiet building.", "o": ["I wish he lived in a quiet building.", "I wish he lives in a quiet building.", "I wish he would lived in a quiet building."], "why": "Após wish, o verbo vai no passado: lived."}, {"t": "b", "pt": "Eu queria que eles fossem mais silenciosos.", "w": ["I", "wish", "they", "were", "quieter"]}, {"t": "b", "pt": "Eu gostaria de ter mais privacidade.", "w": ["I", "wish", "I", "had", "more", "privacy"]}]];
