englishB1Plans[24]={"title": "Pedindo o carro do irmão para o fim de semana", "file": "", "grammar": "Unless, as long as e provided that", "goal": "Fixe condições com unless, as long as e provided that.", "words": [["guarantee", "garantia"], ["condition", "condição"], ["approve", "aprovar"], ["objection", "objeção"], ["caution", "cuidado"], ["decision", "decisão"], ["no matter what", "aconteça o que acontecer"], ["sooner or later", "mais cedo ou mais tarde"]]};
englishB1Content[24]=[[["Noah wants to borrow his brother's car for a weekend trip to the lake.", "Noah quer pegar o carro do irmão emprestado para uma viagem de fim de semana ao lago."], ["His brother Sam says yes, as long as Noah returns it with a full tank.", "O irmão Sam diz que sim, contanto que Noah devolva com o tanque cheio."], ["There is one condition: Noah can't drive at night unless it's really necessary.", "Há uma condição: Noah não pode dirigir à noite, a menos que seja realmente necessário."], ["Sam has no objection to the trip, but he asks Noah to drive with caution.", "Sam não tem objeção à viagem, mas pede que Noah dirija com cuidado."], ["Noah gives his word, and Sam wants a guarantee that the car will come back clean.", "Noah dá sua palavra, e Sam quer uma garantia de que o carro volte limpo."], ["In the end, they shake hands, and Sam approves the plan.", "No fim, eles apertam as mãos, e Sam aprova o plano."]], [["Can I borrow your car this weekend? Priya and I want to go to the lake.", "Posso pegar seu carro emprestado neste fim de semana? Priya e eu queremos ir ao lago."], ["Maybe, provided that you pay for the gas and wash it on Sunday.", "Talvez, desde que você pague a gasolina e lave o carro no domingo."], ["Of course. I'll fill the tank myself, no matter what happens.", "Claro. Eu mesmo encho o tanque, aconteça o que acontecer."], ["And don't drive if the weather is bad. Unless it clears up, stay home.", "E não dirija se o tempo estiver ruim. A menos que melhore, fique em casa."], ["Fair enough. It's your decision, and I respect it.", "Justo. A decisão é sua, e eu respeito."], ["Good. Sooner or later you'll need your own car, you know.", "Bom. Mais cedo ou mais tarde você vai precisar do seu próprio carro, sabe."], ["I know. I'm saving money, but cars are expensive these days.", "Eu sei. Estou juntando dinheiro, mas carros estão caros hoje em dia."], ["Okay, then. The keys are in the drawer. Have fun and drive carefully.", "Certo, então. As chaves estão na gaveta. Divirta-se e dirija com cuidado."]], ["/ʃən/ em condition e objection", "O -tion e o -ction terminam em /ʃən/: con-DI-shun, ob-JEK-shun. A sílaba forte é a penúltima, e a última é fraca.", ["condition", "objection"]], ["Stay home ___ the weather clears up.", "unless", "if", "Fique em casa, a menos que o tempo melhore.", "Unless = “a menos que” (if not): a ideia aqui já é de exceção, então não serve if."], [["His brother Sam says yes, as long as Noah returns it with a full tank.", "O irmão Sam diz que sim, contanto que Noah devolva com o tanque cheio."], ["There is one condition: Noah can't drive at night unless it's really necessary.", "Há uma condição: Noah não pode dirigir à noite, a menos que seja realmente necessário."]], [{"t": "c", "q": "You can use my car ___ you drive carefully.", "o": ["as long as", "unless", "in case"], "pt": "Você pode usar meu carro contanto que dirija com cuidado.", "why": "As long as = contanto que, uma condição positiva."}, {"t": "l", "say": "I'll lend you the car as long as you pay for the gas.", "o": ["I'll lend you the car as long as you pay for the gas.", "I'll lend you the car unless you pay for the gas.", "I'll lend you the car as long as you will pay for the gas."], "why": "As long as + presente simples, sem will."}, {"t": "b", "pt": "Eu vou, a menos que chova.", "w": ["I", "will", "go", "unless", "it", "rains"]}, {"t": "b", "pt": "Você pode ir contanto que ligue.", "w": ["You", "can", "go", "as", "long", "as", "you", "call"]}]];
