englishB1Plans[25]={"title": "Preparando o apartamento para a tempestade", "file": "", "grammar": "In case: precauções e prevenção", "goal": "Explique uma precaução com in case + presente.", "words": [["canned", "enlatado"], ["supplies", "suprimentos"], ["hazard", "perigo"], ["precaution", "precaução"], ["torch", "lanterna"], ["in case", "caso, por precaução"], ["bottled water", "água engarrafada"], ["first aid kit", "kit de primeiros socorros"], ["extension", "extensão (fio)"]]};
englishB1Content[25]=[[["A big storm is coming, so Elena goes to the store to buy supplies.", "Uma tempestade forte está chegando, então Elena vai à loja comprar suprimentos."], ["She buys canned soup and bottled water in case the power goes out.", "Ela compra sopa enlatada e água engarrafada, caso a luz acabe."], ["She puts a torch by her bed in case the lights go out at night.", "Ela coloca uma lanterna ao lado da cama, caso a luz acabe à noite."], ["Her brother Tom checks the first aid kit, just in case someone gets hurt.", "O irmão Tom confere o kit de primeiros socorros, só por precaução, caso alguém se machuque."], ["The wind is a hazard for the old tree outside, so they move the car away.", "O vento é um perigo para a árvore velha lá fora, então eles afastam o carro."], ["It's only a precaution, but now Elena feels calm and ready for the night.", "É só uma precaução, mas agora Elena se sente calma e pronta para a noite."]], [["Tom, did you charge your phone? The storm will hit around nine tonight.", "Tom, você carregou o celular? A tempestade chega por volta das nove hoje."], ["Yes, it's at ninety percent. I also took an extension cord to the living room.", "Sim, está com noventa por cento. Também levei uma extensão para a sala."], ["Good thinking. Take your jacket in case you go out to check the car.", "Boa. Leve a jaqueta, caso você saia para ver o carro."], ["I will. Do we have enough food for two days?", "Vou levar. Temos comida suficiente para dois dias?"], ["Yes, I bought crackers and fruit as well. We won't go hungry.", "Sim, comprei biscoitos e frutas também. Não vamos passar fome."], ["Great. And the water? Should I put it in the kitchen?", "Ótimo. E a água? Devo colocar na cozinha?"], ["Put it near the door, in case we have to leave quickly.", "Coloque perto da porta, caso a gente precise sair rápido."], ["Okay. I'll leave the kit there too.", "Certo. Vou deixar o kit lá também."], ["Perfect. Let's check the windows one more time, just in case.", "Perfeito. Vamos conferir as janelas mais uma vez, só por precaução."], ["Sure. I'll start upstairs, and you take the downstairs.", "Claro. Começo lá em cima, e você fica com o andar de baixo."]], ["/ɔːr/ em torch e storm", "Em torch e storm, o or soa /ɔːr/: boca arredondada e o r americano no final, sem vogal extra. Não diga “torchi”.", ["torch", "storm"]], ["I'll take a jacket ___ it gets cold tonight.", "in case", "when", "Vou levar uma jaqueta, caso esfrie hoje à noite.", "In case indica precaução para algo que talvez aconteça; when indicaria certeza."], [["She buys canned soup and bottled water in case the power goes out.", "Ela compra sopa enlatada e água engarrafada, caso a luz acabe."], ["Put it near the door, in case we have to leave quickly.", "Coloque perto da porta, caso a gente precise sair rápido."]], [{"t": "c", "q": "Let's buy water ___ the power goes out.", "o": ["in case", "if", "unless"], "pt": "Vamos comprar água, caso a luz acabe.", "why": "In case + presente simples expressa precaução."}, {"t": "l", "say": "Take a torch in case the lights go out.", "o": ["Take a torch in case the lights go out.", "Take a torch in case the lights will go out.", "Take a torch in case of the lights go out."], "why": "In case + presente, sem will."}, {"t": "b", "pt": "Leve um casaco, caso esfrie.", "w": ["Take", "a", "jacket", "in", "case", "it", "gets", "cold"]}, {"t": "b", "pt": "Vou deixar o kit de primeiros socorros aqui.", "w": ["I", "will", "leave", "the", "first", "aid", "kit", "here"]}]];
englishB1PhotoThemes[25]="city";
englishB1Plans[26]={"title": "Eleição do tesoureiro no saguão do prédio", "file": "", "grammar": "Primeira vs segunda condicional (real vs improvável)", "goal": "Diferencie If + presente + will (provável) de If + passado + would (improvável).", "words": [["election", "eleição"], ["majority", "maioria"], ["ballot", "cédula de votação"], ["treasurer", "tesoureiro"], ["show of hands", "votação por mão levantada"], ["elect", "eleger"], ["vote", "votar"], ["board member", "membro do conselho"], ["turnout", "comparecimento"]]};
englishB1Content[26]=[[["Tonight the building has an election for a new treasurer in the lobby.", "Hoje à noite o prédio faz uma eleição para um novo tesoureiro no saguão."], ["If more than fifty neighbors come, the turnout will be the best in years.", "Se mais de cinquenta vizinhos vierem, o comparecimento será o melhor em anos."], ["Mr. Lopes says that if he wins, he will fix the elevator first.", "O Sr. Lopes diz que, se ganhar, vai consertar o elevador primeiro."], ["Mia, a board member, would run too if she had more free time.", "Mia, membro do conselho, também se candidataria se tivesse mais tempo livre."], ["At eight, everyone writes a name on the ballot and drops it in a box.", "Às oito, todos escrevem um nome na cédula e a colocam numa caixa."], ["The majority votes for Mr. Lopes, and the room applauds.", "A maioria vota no Sr. Lopes, e a sala aplaude."]], [["Are you going to vote tonight, Rosa? The election starts at seven.", "Você vai votar hoje à noite, Rosa? A eleição começa às sete."], ["If I finish work on time, I will. Otherwise I'll send my vote by email.", "Se eu terminar o trabalho a tempo, vou. Senão mando meu voto por e-mail."], ["You should come. If more people voted, we would have a stronger board.", "Você devia vir. Se mais gente votasse, teríamos um conselho mais forte."], ["True. If everyone came, the meetings wouldn't be so boring.", "Verdade. Se todo mundo viesse, as reuniões não seriam tão chatas."], ["Last year they voted by show of hands, and it was a mess.", "Ano passado votaram por mão levantada, e foi uma bagunça."], ["If they elect Mr. Lopes, I hope he finally fixes the elevator.", "Se elegerem o Sr. Lopes, espero que ele finalmente conserte o elevador."], ["He will if somebody reminds him. I'll talk to him tonight.", "Ele vai, se alguém lembrar. Vou falar com ele hoje à noite."], ["Perfect. I'll be there at seven fifteen, I promise.", "Perfeito. Estarei lá às sete e quinze, prometo."]], ["Acento em elect e election", "Em elect e election, a sílaba forte é a segunda: e-LECT, e-LEC-tion. A primeira sílaba é fraca e soa como /ɪ/ curto.", ["election", "elect"]], ["If more neighbors came, we ___ a stronger board.", "would have", "will have", "Se mais vizinhos viessem, teríamos um conselho mais forte.", "Hipótese improvável: If + passado simples e would no resultado."], [["Mr. Lopes says that if he wins, he will fix the elevator first.", "O Sr. Lopes diz que, se ganhar, vai consertar o elevador primeiro."], ["Mia, a board member, would run too if she had more free time.", "Mia, membro do conselho, também se candidataria se tivesse mais tempo livre."]], [{"t": "c", "q": "If it ___ tomorrow, the vote will be outside.", "o": ["doesn't rain", "didn't rain", "wouldn't rain"], "pt": "Se não chover amanhã, a votação será do lado de fora.", "why": "Possibilidade real: If + presente simples, will no resultado."}, {"t": "l", "say": "If I won, I would fix the elevator.", "o": ["If I won, I would fix the elevator.", "If I win, I would fix the elevator.", "If I won, I will fix the elevator."], "why": "Hipótese improvável: If + passado, would + verbo."}, {"t": "b", "pt": "Se eu ganhasse, consertaria o elevador.", "w": ["If", "I", "won", "I", "would", "fix", "the", "elevator"]}, {"t": "b", "pt": "Se chover, a votação será dentro.", "w": ["If", "it", "rains", "the", "vote", "will", "be", "inside"]}]];
