englishB1Plans[27]={"title": "Jogo de perguntas hipotéticas no jantar", "file": "", "grammar": "What would you do if…? Perguntas e respostas hipotéticas", "goal": "Pergunte e responda What would you do if…? em jogos e conversas.", "words": [["courageous", "corajoso"], ["dare", "ousar"], ["moral", "moral, ético"], ["dilemma", "dilema"], ["curiosity", "curiosidade"], ["imaginary", "imaginário"], ["guilty", "culpado"], ["impression", "impressão"]]};
englishB1Content[27]=[[["At dinner, Priya suggests a game of hypothetical questions to break the silence.", "No jantar, Priya sugere um jogo de perguntas hipotéticas para quebrar o silêncio."], ["Her friends love it because the questions are full of strange, imaginary situations.", "Os amigos adoram, porque as perguntas são cheias de situações estranhas e imaginárias."], ["Kenji asks, 'What would you do if you found a wallet with a thousand dollars?'", "Kenji pergunta: 'O que você faria se encontrasse uma carteira com mil dólares?'"], ["It is a small moral dilemma, and nobody wants to look guilty.", "É um pequeno dilema moral, e ninguém quer parecer culpado."], ["Lia says she would call the owner, because her curiosity would keep her awake.", "Lia diz que ligaria para o dono, porque a curiosidade a deixaria acordada."], ["Everyone agrees, and Lia leaves a great impression on the group.", "Todos concordam, e Lia deixa uma ótima impressão no grupo."]], [["Okay, next question. What would you do if you could fly for one day?", "Certo, próxima pergunta. O que você faria se pudesse voar por um dia?"], ["I would fly over the city and visit my grandmother. She lives far away.", "Eu sobrevoaria a cidade e visitaria minha avó. Ela mora longe."], ["Aww, nice. And what would you do if you were the president?", "Que fofo. E o que você faria se fosse o presidente?"], ["Honestly, I wouldn't dare to say yes. That job looks terrible.", "Sinceramente, eu não ousaria dizer sim. Esse trabalho parece terrível."], ["Come on! Would you be courageous enough to change the whole system?", "Vamos lá! Você seria corajoso o bastante para mudar o sistema todo?"], ["If I had enough support, maybe. What about you? What would you do?", "Se eu tivesse apoio suficiente, talvez. E você? O que faria?"], ["I would build free libraries in every neighborhood. I really mean it.", "Eu construiria bibliotecas gratuitas em cada bairro. Falo sério."], ["Wow, that's a great answer. I'll vote for you, Priya!", "Uau, ótima resposta. Eu voto em você, Priya!"]], ["/dʒ/ em courageous e imaginary", "O g em courageous e imaginary soa /dʒ/, como o “dj” de “djembê”: kuh-REI-djus, i-MÆ-dji-neri.", ["courageous", "imaginary"]], ["What ___ you do if you found a wallet?", "would", "will", "O que você faria se encontrasse uma carteira?", "Pergunta hipotética: What would you do if + passado simples."], [["Kenji asks, 'What would you do if you found a wallet with a thousand dollars?'", "Kenji pergunta: 'O que você faria se encontrasse uma carteira com mil dólares?'"], ["Okay, next question. What would you do if you could fly for one day?", "Certo, próxima pergunta. O que você faria se pudesse voar por um dia?"]], [{"t": "c", "q": "What would you do if you ___ the boss?", "o": ["were", "are", "will be"], "pt": "O que você faria se fosse o chefe?", "why": "Depois de If irreal, use were (ou passado simples)."}, {"t": "l", "say": "What would you do if you found a wallet?", "o": ["What would you do if you found a wallet?", "What will you do if you found a wallet?", "What would you do if you find a wallet?"], "why": "Pergunta hipotética: would + If + passado."}, {"t": "b", "pt": "O que você faria se fosse rico?", "w": ["What", "would", "you", "do", "if", "you", "were", "rich"]}, {"t": "b", "pt": "Eu ligaria para o dono.", "w": ["I", "would", "call", "the", "owner"]}]];
