englishB1Plans[28]={"title": "Visitando a escola de arte no sábado", "file": "", "grammar": "Sonhos e escolhas: If only e wish com could", "goal": "Expresse sonhos e frustrações com If only + passado e I wish I could….", "words": [["passion", "paixão"], ["artistic", "artístico"], ["academy", "academia (escola)"], ["determination", "determinação"], ["art school", "escola de arte"], ["student loan", "empréstimo estudantil"], ["tuition", "mensalidade"], ["career change", "mudança de carreira"]]};
englishB1Content[28]=[[["Elena works in an office, but her real passion has always been painting.", "Elena trabalha num escritório, mas a verdadeira paixão dela sempre foi a pintura."], ["She wishes she could study at the art academy downtown, but tuition is very expensive.", "Ela gostaria de poder estudar na academia de arte do centro, mas a mensalidade é muito cara."], ["If only she had a student loan or a little more free time.", "Se ao menos ela tivesse um empréstimo estudantil ou um pouco mais de tempo livre."], ["Her sister says Elena is really artistic and has the determination to succeed.", "A irmã diz que Elena é muito artística e tem a determinação para ter sucesso."], ["Elena wishes she could make a career change without worrying about money.", "Elena gostaria de poder mudar de carreira sem se preocupar com dinheiro."], ["She decides to visit the art school on Saturday and ask about night classes.", "Ela decide visitar a escola de arte no sábado e perguntar sobre aulas à noite."]], [["Elena, you've been staring at that website for an hour. What's up?", "Elena, você está olhando esse site há uma hora. O que houve?"], ["It's the art school downtown. I wish I could start classes next month.", "É a escola de arte do centro. Queria poder começar as aulas no mês que vem."], ["Why can't you? Is it the tuition?", "Por que não pode? É a mensalidade?"], ["Partly. And my job. If only I had more free time in the evenings!", "Em parte. E o meu trabalho. Se ao menos eu tivesse mais tempo livre à noite!"], ["Maybe you can ask about a student loan. Many schools offer them.", "Talvez você possa perguntar sobre um empréstimo estudantil. Muitas escolas oferecem."], ["I didn't know that. I'll ask them on Saturday.", "Eu não sabia disso. Vou perguntar a eles no sábado."], ["Great. And I wish I could go with you, but I'm working that day.", "Ótimo. E eu queria poder ir com você, mas trabalho nesse dia."], ["No problem. I'll call you right after and tell you everything.", "Sem problema. Ligo para você logo depois e conto tudo."]], ["/æ/ em passion e academy", "Em passion e academy, o a soa /æ/, uma vogal aberta entre “a” e “é”: PÆ-shun, uh-KÆ-duh-mi. Abra bem a boca.", ["passion", "academy"]], ["If only I ___ more free time!", "had", "have", "Se ao menos eu tivesse mais tempo livre!", "If only + passado simples expressa desejo sobre o presente."], [["If only she had a student loan or a little more free time.", "Se ao menos ela tivesse um empréstimo estudantil ou um pouco mais de tempo livre."], ["It's the art school downtown. I wish I could start classes next month.", "É a escola de arte do centro. Queria poder começar as aulas no mês que vem."]], [{"t": "c", "q": "I wish I ___ paint every day.", "o": ["could", "can", "will"], "pt": "Queria poder pintar todos os dias.", "why": "Wish + could expressa desejo de ter uma habilidade ou liberdade."}, {"t": "l", "say": "I wish I could study at the art school.", "o": ["I wish I could study at the art school.", "I wish I can study at the art school.", "I wish I could to study at the art school."], "why": "Wish + could + verbo simples, sem to."}, {"t": "b", "pt": "Se ao menos eu tivesse mais tempo livre.", "w": ["If", "only", "I", "had", "more", "free", "time"]}, {"t": "b", "pt": "Eu gostaria de poder pintar todos os dias.", "w": ["I", "wish", "I", "could", "paint", "every", "day"]}]];
