englishB1Plans[29]={"title": "Se eu ganhasse na loteria", "file": "", "grammar": "Revisão: se eu ganhasse na loteria (mini-história)", "goal": "Revise as hipóteses (If + passado, would) sonhando com um prêmio.", "words": [["millionaire", "milionário"], ["fortune", "fortuna"], ["foundation", "fundação"], ["miracle", "milagre"], ["billion", "bilhão"], ["give away", "doar, dar de graça"], ["private jet", "jato particular"], ["trust fund", "fundo fiduciário"], ["inheritance", "herança"], ["scratch card", "raspadinha"]]};
englishB1Content[29]=[[["Sam buys a scratch card every Friday, and his friends always laugh at him.", "Sam compra uma raspadinha toda sexta, e os amigos sempre riem dele."], ["Today he dreams about it: if he won a fortune, his life would change.", "Hoje ele sonha com isso: se ganhasse uma fortuna, a vida dele mudaria."], ["If he became a millionaire tomorrow, he would not buy a private jet.", "Se ele virasse milionário amanhã, não compraria um jato particular."], ["He would give away half of the money and start a foundation for schools.", "Ele doaria metade do dinheiro e criaria uma fundação para escolas."], ["A billion dollars sounds like a miracle, but he would stay humble.", "Um bilhão de dólares parece um milagre, mas ele continuaria humilde."], ["His sister smiles and says a trust fund for kids is a better idea.", "A irmã sorri e diz que um fundo para as crianças é uma ideia melhor."]], [["Sam, did you buy your scratch card again? That's the third this month.", "Sam, você comprou a raspadinha de novo? É a terceira este mês."], ["Yes, but this time I'm serious. If I won, I would change everything.", "Sim, mas desta vez falo sério. Se eu ganhasse, mudaria tudo."], ["Everything? What would you do first, buy a mansion?", "Tudo? O que você faria primeiro, compraria uma mansão?"], ["No way. I would help my parents with the mortgage and give away money to friends.", "De jeito nenhum. Eu ajudaria meus pais com o financiamento e daria dinheiro aos amigos."], ["Wow. I would travel around the world if I had a billion.", "Uau. Eu viajaria o mundo todo se tivesse um bilhão."], ["My grandfather left me a small inheritance once, and I spent it all on a guitar.", "Meu avô me deixou uma pequena herança uma vez, e gastei tudo numa guitarra."], ["That sounds like you. And if you had enough money, would you still work?", "Tem a sua cara. E se você tivesse dinheiro suficiente, ainda trabalharia?"], ["Of course. I would work less, but I would still need a purpose.", "Claro. Eu trabalharia menos, mas ainda precisaria de um propósito."], ["Well, if you win, remember your best friend and his old car.", "Bem, se ganhar, lembre-se do melhor amigo e do carro velho dele."], ["Deal. You'll get a new car, and I'll get a miracle.", "Fechado. Você ganha um carro novo, e eu ganho um milagre."]], ["/ɪ/ em billion e millionaire", "Em billion e millionaire, o i antes de ll é /ɪ/ curto, como em “bili”: BIL-yun, mil-yuh-NER. Não alongue a vogal.", ["billion", "millionaire"]], ["If I ___ a billion dollars, I would start a foundation.", "had", "have", "Se eu tivesse um bilhão de dólares, criaria uma fundação.", "Hipótese irreal: If + passado simples (had), would + verbo."], [["If he became a millionaire tomorrow, he would not buy a private jet.", "Se ele virasse milionário amanhã, não compraria um jato particular."], ["Yes, but this time I'm serious. If I won, I would change everything.", "Sim, mas desta vez falo sério. Se eu ganhasse, mudaria tudo."]], [{"t": "c", "q": "If I won a fortune, I ___ give away half.", "o": ["would", "will", "am"], "pt": "Se eu ganhasse uma fortuna, doaria metade.", "why": "O resultado de uma hipótese irreal leva would."}, {"t": "l", "say": "If I became a millionaire, I would start a foundation.", "o": ["If I became a millionaire, I would start a foundation.", "If I become a millionaire, I would start a foundation.", "If I became a millionaire, I will start a foundation."], "why": "If + passado simples, would + verbo."}, {"t": "b", "pt": "Se eu ganhasse, doaria metade.", "w": ["If", "I", "won", "I", "would", "give", "away", "half"]}, {"t": "b", "pt": "Eu não compraria um jato particular.", "w": ["I", "would", "not", "buy", "a", "private", "jet"]}]];
