englishB1MiniStories[29]=["O cartão de Ben", "Last Friday, Ben bought a scratch card and imagined a very different life.~Na sexta passada, Ben comprou uma raspadinha e imaginou uma vida bem diferente.|He wished he had more free time to travel, and he dreamed of a private jet.~Ele queria ter mais tempo livre para viajar e sonhava com um jato particular.|If he won a fortune, he would pay the mortgage and quit his job, he thought.~Se ganhasse uma fortuna, pagaria o financiamento e largaria o emprego, pensou.|Ana told him, 'If I were you, I would think twice about that.'~Ana disse a ele: 'Se eu fosse você, pensaria duas vezes.'|'Unless you have a plan, money disappears,' she said, 'so keep some in case of trouble.'~'A menos que você tenha um plano, o dinheiro some', disse ela, 'então guarde um pouco para o caso de problemas.'|Ben scratched the card, and, to his surprise, it was a small miracle.~Ben raspou o cartão e, para sua surpresa, foi um pequeno milagre.|He won two hundred dollars, which is not a fortune, but it is something.~Ele ganhou duzentos dólares, que não é uma fortuna, mas é alguma coisa.|'What would you do with it?' Ana asked, smiling.~'O que você faria com isso?', perguntou Ana, sorrindo.|Ben said he would invite her to dinner, as long as she chose the restaurant.~Ben disse que a convidaria para jantar, contanto que ela escolhesse o restaurante.|They laughed, and Ben decided that a simple dinner was a better dream than a yacht.~Eles riram, e Ben decidiu que um jantar simples era um sonho melhor do que um iate."];
englishB1Plans[30]={"title": "Visita ao moinho de trigo", "file": "", "grammar": "Passiva no presente: is/are + particípio", "goal": "Descreva como um produto é feito com is/are + particípio, como em The flour is filtered twice.", "words": [["manufacture", "fabricar"], ["mixture", "mistura"], ["blend", "misturar, combinar"], ["batch", "lote, fornada"], ["filter", "filtrar"], ["seal", "selar, fechar"], ["export", "exportar"], ["wheat", "trigo"], ["mill", "moinho"]]};
englishB1Content[30]=[[["Our flour is manufactured from wheat that is grown on farms near the river.", "Nossa farinha é fabricada com trigo que é cultivado em fazendas perto do rio."], ["The wheat is taken to the mill and ground into fine flour.", "O trigo é levado ao moinho e moído até virar farinha fina."], ["Then the flour is blended with vitamins, and each batch is tested in the lab.", "Depois a farinha é misturada com vitaminas, e cada lote é testado no laboratório."], ["The mixture is filtered twice, so no small pieces are left in the bag.", "A mistura é filtrada duas vezes, então nenhum pedaço pequeno fica no saco."], ["Finally, every bag is sealed by a machine and checked by a worker.", "Por fim, cada saco é fechado por uma máquina e conferido por um funcionário."], ["Most of our flour is exported to Chile, but some is sold here.", "A maior parte da nossa farinha é exportada para o Chile, mas um pouco é vendida aqui."]], [["Excuse me, I'm doing a school project. How is this flour manufactured?", "Com licença, estou fazendo um trabalho da escola. Como esta farinha é fabricada?"], ["Well, first we collect the wheat from the farms and bring it to the mill.", "Bem, primeiro recolhemos o trigo das fazendas e levamos ao moinho."], ["I see. And what do you do with it after that?", "Entendi. E o que vocês fazem com ele depois disso?"], ["A machine grinds it, and then we blend it with vitamins in small batches.", "Uma máquina mói o trigo, e depois misturamos com vitaminas em pequenos lotes."], ["Wow. Do you filter the mixture by hand, or does a machine do it?", "Nossa. Vocês filtram a mistura à mão, ou uma máquina faz isso?"], ["A machine does it, but two workers check the bags before they're sealed.", "Uma máquina faz, mas dois funcionários conferem os sacos antes de eles serem fechados."], ["Is the flour sold only here, or is it exported too?", "A farinha é vendida só aqui, ou também é exportada?"], ["Yes, exactly. Two trucks take it to the port every Friday at six.", "Sim, exatamente. Dois caminhões levam a farinha ao porto toda sexta às seis."]], ["/fl/ em flour e filter", "Junte f e l sem vogal no meio (não diga 'fulor'): os dentes de cima tocam o lábio de baixo e a língua já sobe para o l.", ["flour", "filter"]], ["The boxes ___ by a machine at the end of the line.", "are sealed", "sealed", "As caixas são fechadas por uma máquina no fim da linha.", "Quando o sujeito recebe a ação, use am/is/are + particípio: are sealed."], [["Our flour is manufactured from wheat that is grown on farms near the river.", "Nossa farinha é fabricada com trigo que é cultivado em fazendas perto do rio."], ["Most of our flour is exported to Chile, but some is sold here.", "A maior parte da nossa farinha é exportada para o Chile, mas um pouco é vendida aqui."]], [{"t": "c", "q": "The flour ___ twice before it goes into the bag.", "o": ["is filtered", "filters", "filtering"], "pt": "A farinha é filtrada duas vezes antes de ir para o saco.", "why": "A farinha recebe a ação, então use is + particípio: is filtered."}, {"t": "l", "say": "Each batch is tested in the lab.", "o": ["Each batch is tested in the lab.", "Each batch is testing in the lab.", "Each batch tests in the lab."], "why": "O lote recebe a ação: is tested, e não is testing."}, {"t": "b", "pt": "A farinha é exportada para o Chile.", "w": ["The", "flour", "is", "exported", "to", "Chile"]}, {"t": "b", "pt": "Cada saco é fechado por uma máquina.", "w": ["Each", "bag", "is", "sealed", "by", "a", "machine"]}]];
