englishB1Plans[31]={"title": "A tumba do primeiro imperador no museu", "file": "", "grammar": "Passiva no passado: was/were + particípio", "goal": "Conte fatos históricos com was/were + particípio, como em The tomb was found in 1974.", "words": [["empire", "império"], ["tomb", "tumba"], ["invent", "inventar"], ["destroy", "destruir"], ["legend", "lenda"], ["capture", "capturar, conquistar"], ["civilization", "civilização"], ["dynasty", "dinastia"]]};
englishB1Content[31]=[[["This tomb was built for the first emperor of the Qin dynasty long ago.", "Esta tumba foi construída para o primeiro imperador da dinastia Qin há muito tempo."], ["It was found by farmers in 1974 while they were digging a well.", "Ela foi encontrada por agricultores em 1974 enquanto eles cavavam um poço."], ["Thousands of clay soldiers were buried inside, and each one was made by hand.", "Milhares de soldados de argila foram enterrados lá dentro, e cada um foi feito à mão."], ["Many were destroyed in a fire, but workers saved the rest.", "Muitos foram destruídos num incêndio, mas os trabalhadores salvaram o resto."], ["The legend says the emperor's empire was never captured by an enemy.", "A lenda diz que o império do imperador nunca foi conquistado por um inimigo."], ["Compasses and paper were invented by this civilization, so it's famous around the world.", "Bússolas e papel foram inventados por essa civilização, por isso ela é famosa no mundo todo."]], [["Look at this map. When was the tomb found, Tom?", "Olhe este mapa. Quando a tumba foi encontrada, Tom?"], ["In 1974. Some farmers were digging a well, and they hit a clay head.", "Em 1974. Uns agricultores estavam cavando um poço e bateram numa cabeça de argila."], ["Really? They probably called the police right away.", "Sério? Provavelmente chamaram a polícia na hora."], ["No, they called the museum, and three experts arrived the next morning.", "Não, eles ligaram para o museu, e três especialistas chegaram na manhã seguinte."], ["And who built it? Was it a famous dynasty?", "E quem construiu? Foi uma dinastia famosa?"], ["Yes, the Qin dynasty. The soldiers were made by thousands of workers.", "Sim, a dinastia Qin. Os soldados foram feitos por milhares de trabalhadores."], ["I read that the whole army was destroyed. Is that true?", "Li que o exército inteiro foi destruído. É verdade?"], ["Only part of it. Fire burned the roof, but about eight thousand soldiers survived.", "Só uma parte. O fogo queimou o teto, mas cerca de oito mil soldados sobreviveram."], ["Amazing. I want to buy a book about that legend before we leave.", "Incrível. Quero comprar um livro sobre essa lenda antes de irmos embora."], ["Good idea. The shop closes at five, so we have time. Let's go.", "Boa ideia. A loja fecha às cinco, então temos tempo. Vamos."]], ["/θ/ em thousands e three", "Ponha a ponta da língua entre os dentes e solte o ar, sem vibrar: não vire 'f' nem 't'. Treine em thousands e three.", ["thousands", "three"]], ["The tomb ___ in 1974 by two farmers.", "was found", "is found", "A tumba foi encontrada em 1974 por dois agricultores.", "Fato do passado: use was/were + particípio, como em was found."], [["This tomb was built for the first emperor of the Qin dynasty long ago.", "Esta tumba foi construída para o primeiro imperador da dinastia Qin há muito tempo."], ["It was found by farmers in 1974 while they were digging a well.", "Ela foi encontrada por agricultores em 1974 enquanto eles cavavam um poço."]], [{"t": "c", "q": "Paper ___ in China more than two thousand years ago.", "o": ["was invented", "is invented", "invented"], "pt": "O papel foi inventado na China há mais de dois mil anos.", "why": "Fato histórico com sujeito que recebe a ação: was + particípio."}, {"t": "l", "say": "The soldiers were made by hand.", "o": ["The soldiers were made by hand.", "The soldiers are made by hand.", "The soldier was made by hand."], "why": "Soldiers está no plural e a ação é passada: were made."}, {"t": "b", "pt": "A tumba foi construída para um imperador.", "w": ["The", "tomb", "was", "built", "for", "an", "emperor"]}, {"t": "b", "pt": "Muitos soldados foram destruídos no incêndio.", "w": ["Many", "soldiers", "were", "destroyed", "in", "the", "fire"]}]];
