englishB1Plans[32]={"title": "O programa do concerto no teatro", "file": "", "grammar": "Passiva com by e sem agente", "goal": "Diga quem fez algo com by, ou omita o agente, como em The poster was drawn by a designer.", "words": [["compose", "compor"], ["symphony", "sinfonia"], ["designer", "designer, projetista"], ["founder", "fundador"], ["publication", "publicação"], ["edit", "editar"], ["inspire", "inspirar"], ["inventor", "inventor"]]};
englishB1Content[32]=[[["The symphony you will hear tonight was composed by a young woman from Detroit.", "A sinfonia que você vai ouvir hoje à noite foi composta por uma jovem de Detroit."], ["She was inspired by the sounds of her grandmother's kitchen and the city streets.", "Ela foi inspirada pelos sons da cozinha da avó e das ruas da cidade."], ["The theater was founded by neighbors, and its founder still sits in row one.", "O teatro foi fundado por vizinhos, e seu fundador ainda se senta na fileira um."], ["The poster was drawn by a designer, and the program was edited by students.", "O cartaz foi desenhado por um designer, e o programa foi editado por estudantes."], ["The first stage lights were made by an inventor, but his name was forgotten.", "As primeiras luzes do palco foram feitas por um inventor, mas o nome dele foi esquecido."], ["This publication is free, and the tickets were all sold out by Friday.", "Esta publicação é gratuita, e os ingressos foram todos vendidos até sexta."]], [["Omar, did you read the program? Who composed the second piece?", "Omar, você leu o programa? Quem compôs a segunda peça?"], ["It was composed by a woman named Elena, and she's here tonight.", "Foi composta por uma mulher chamada Elena, e ela está aqui hoje à noite."], ["Really? I thought all famous symphonies were written by men a long time ago.", "Sério? Eu achava que todas as sinfonias famosas eram escritas por homens há muito tempo."], ["Not always. This one was inspired by her grandmother's kitchen, believe it or not.", "Nem sempre. Esta foi inspirada na cozinha da avó dela, acredite se quiser."], ["That's funny. Who designed the poster outside? I love the colors.", "Que engraçado. Quem desenhou o cartaz lá fora? Adoro as cores."], ["A friend of mine. She's a designer, and she edits the free publication too.", "Uma amiga minha. Ela é designer e também edita a publicação gratuita."], ["Wow. Do you think she'll sign my program after the concert tonight?", "Nossa. Você acha que ela vai autografar meu programa depois do concerto de hoje?"], ["Sure, she'll be by the exit at ten. Let's wait there together.", "Claro, ela vai estar perto da saída às dez. Vamos esperar lá juntos."]], ["/k/ em composed e concert", "O c soa como k nas duas palavras, com um sopro forte. Em composed, a primeira sílaba é fraca: kəm-POZD.", ["composed", "concert"]], ["This symphony ___ by a young woman.", "was composed", "composed", "Esta sinfonia foi composta por uma jovem.", "Se a sinfonia recebe a ação, use was + particípio; by diz quem fez."], [["The symphony you will hear tonight was composed by a young woman from Detroit.", "A sinfonia que você vai ouvir hoje à noite foi composta por uma jovem de Detroit."], ["The first stage lights were made by an inventor, but his name was forgotten.", "As primeiras luzes do palco foram feitas por um inventor, mas o nome dele foi esquecido."]], [{"t": "c", "q": "The first lights ___ by an inventor, but his name was forgotten.", "o": ["were made", "was made", "made"], "pt": "As primeiras luzes foram feitas por um inventor, mas o nome dele foi esquecido.", "why": "Lights é plural e a ação é passada: were made."}, {"t": "l", "say": "The program was edited by two students.", "o": ["The program was edited by two students.", "The program was edit by two students.", "The programs were edited by a student."], "why": "Passiva no passado usa o particípio: was edited."}, {"t": "b", "pt": "O teatro foi fundado por vizinhos.", "w": ["The", "theater", "was", "founded", "by", "neighbors"]}, {"t": "b", "pt": "A sinfonia foi inspirada pela cozinha dela.", "w": ["The", "symphony", "was", "inspired", "by", "her", "kitchen"]}]];
