englishB1Plans[33]={"title": "Anúncio da nova biblioteca da cidade", "file": "", "grammar": "Passiva no futuro: will be + particípio", "goal": "Fale de planos com will be + particípio, como em The market will be demolished next month.", "words": [["construct", "construir"], ["demolish", "demolir"], ["completion", "conclusão"], ["finance", "financiar"], ["authority", "autoridade, órgão público"], ["government", "governo"], ["network", "rede"], ["grant", "verba, subsídio"]]};
englishB1Content[33]=[[["The old market on Pine Street will be demolished next month.", "O mercado velho da Pine Street será demolido no mês que vem."], ["A new library will be constructed there and financed by the government.", "Uma nova biblioteca será construída ali e financiada pelo governo."], ["A grant from the state will cover half of the cost.", "Uma verba do estado vai cobrir metade do custo."], ["The local authority says the work will be finished in about fourteen months.", "A prefeitura diz que a obra será concluída em cerca de catorze meses."], ["A bike path and a free wifi network will be added around the building.", "Uma ciclovia e uma rede de wifi gratuita serão acrescentadas ao redor do prédio."], ["After completion, the library will be opened by the mayor with a big party.", "Depois da conclusão, a biblioteca será inaugurada pela prefeita com uma grande festa."]], [["Sam, did you hear the news about the market on Pine Street?", "Sam, você soube da notícia sobre o mercado da Pine Street?"], ["Yes. It will be demolished next month, and I'm a little sad.", "Sim. Ele será demolido no mês que vem, e estou um pouco triste."], ["Me too, but the authority says a new library will go there.", "Eu também, mas a prefeitura diz que uma biblioteca nova vai ficar lá."], ["I know. Who is going to finance it? It sounds expensive.", "Eu sei. Quem vai financiar? Parece caro."], ["The government will pay part of it, and a grant will cover the rest.", "O governo vai pagar uma parte, e uma verba vai cobrir o resto."], ["Good. When will the construction be complete? I hope it's before winter.", "Bom. Quando a construção estará pronta? Espero que seja antes do inverno."], ["The sign says completion is planned for next October, so we'll wait a year.", "A placa diz que a conclusão está planejada para outubro do ano que vem, então vamos esperar um ano."], ["A year is fine. Let's go to the public meeting on Thursday and ask about the bike paths.", "Um ano está bom. Vamos à reunião pública na quinta e perguntar sobre as ciclovias."]], ["/g/ em government e grant", "O g inglês é duro, como em 'gato': government, grant. Não transforme em 'j' nem em 'dj'.", ["government", "grant"]], ["The old school ___ next year.", "will be demolished", "will demolished", "A escola velha será demolida no ano que vem.", "Futuro passivo: will + be + particípio. Não esqueça o be."], [["The old market on Pine Street will be demolished next month.", "O mercado velho da Pine Street será demolido no mês que vem."], ["After completion, the library will be opened by the mayor with a big party.", "Depois da conclusão, a biblioteca será inaugurada pela prefeita com uma grande festa."]], [{"t": "c", "q": "The new bridge ___ by the city government.", "o": ["will be financed", "will finance", "will financed"], "pt": "A nova ponte será financiada pelo governo da cidade.", "why": "A ponte recebe a ação no futuro: will be + particípio."}, {"t": "l", "say": "The library will be opened by the mayor.", "o": ["The library will be opened by the mayor.", "The library will open by the mayor.", "The library was opened by the mayor."], "why": "Ação futura e passiva: will be opened."}, {"t": "b", "pt": "O trabalho será terminado em catorze meses.", "w": ["The", "work", "will", "be", "finished", "in", "fourteen", "months"]}, {"t": "b", "pt": "Uma ciclovia será acrescentada aqui.", "w": ["A", "bike", "path", "will", "be", "added", "here"]}]];
