englishB1Plans[34]={"title": "Guardando produtos químicos na garagem", "file": "", "grammar": "Passiva com modais: can be, must be, should be", "goal": "Fale de segurança com can be, must be e should be, como em Toxic products must be kept away from children.", "words": [["contaminate", "contaminar"], ["preserve", "conservar"], ["disposal", "descarte"], ["substance", "substância"], ["toxic", "tóxico"], ["poison", "envenenar; veneno"], ["harmful", "prejudicial"], ["contain", "conter"], ["measure", "medida"]]};
englishB1Content[34]=[[["Cleaning products contain substances that can be harmful and must be stored carefully.", "Produtos de limpeza contêm substâncias que podem ser prejudiciais e devem ser guardados com cuidado."], ["Some of them are toxic and should be kept far from children and pets.", "Alguns são tóxicos e devem ser mantidos longe de crianças e animais."], ["Old paint can't be thrown in the trash because it can contaminate the water.", "Tinta velha não pode ser jogada no lixo porque pode contaminar a água."], ["Disposal of old batteries must be done at a special collection point.", "O descarte de pilhas velhas deve ser feito num ponto de coleta especial."], ["Never mix two products, because the mixture can poison you or make you sick.", "Nunca misture dois produtos, porque a mistura pode envenenar você ou deixá-lo doente."], ["Food should be preserved in glass jars, never in empty chemical bottles.", "Comida deve ser conservada em potes de vidro, nunca em garrafas de produtos químicos vazias."]], [["Rosa, what should we do with these old paint cans in the garage?", "Rosa, o que devemos fazer com estas latas de tinta velhas na garagem?"], ["They can't be put in the trash. The disposal center takes them on Saturdays.", "Elas não podem ser postas no lixo. O centro de descarte as recebe aos sábados."], ["Okay. And what about this blue bottle? It says toxic on the label.", "Certo. E esta garrafa azul? No rótulo está escrito tóxico."], ["Let me see. Hmm, it should be kept in a cool place, away from the kids.", "Deixe-me ver. Hum, ela deve ser mantida num lugar fresco, longe das crianças."], ["I'll move it to the high shelf. Could it be harmful if the dog touches it?", "Vou colocá-la na prateleira alta. Poderia fazer mal se o cachorro tocar nela?"], ["Yes, it could poison him. Everything toxic must be locked up today.", "Sim, poderia envenená-lo. Tudo que é tóxico deve ser trancado hoje."], ["Good idea. I'll buy a lock tonight and take some safety measures.", "Boa ideia. Vou comprar um cadeado hoje à noite e tomar algumas medidas de segurança."], ["Perfect. Then tomorrow morning we'll take the paint cans to the disposal center.", "Perfeito. Então amanhã de manhã levaremos as latas de tinta ao centro de descarte."]], ["/z/ em poison e disposal", "O s entre vogais soa como z, como em 'casa': POI-zən e dis-PO-zəl.", ["poison", "disposal"]], ["Old batteries ___ in the trash.", "can't be thrown", "can't be throw", "Pilhas velhas não podem ser jogadas no lixo.", "Depois de can't be use o particípio do verbo: thrown."], [["Some of them are toxic and should be kept far from children and pets.", "Alguns são tóxicos e devem ser mantidos longe de crianças e animais."], ["Disposal of old batteries must be done at a special collection point.", "O descarte de pilhas velhas deve ser feito num ponto de coleta especial."]], [{"t": "c", "q": "Toxic products ___ away from children.", "o": ["must be kept", "must keep", "must be keeping"], "pt": "Produtos tóxicos devem ser mantidos longe das crianças.", "why": "Os produtos recebem a ação: modal + be + particípio, must be kept."}, {"t": "l", "say": "The paint can't be put in the trash.", "o": ["The paint can't be put in the trash.", "The paint can't put in the trash.", "The paint can't be putting in the trash."], "why": "Modal passivo: can't be + particípio (put)."}, {"t": "b", "pt": "Esses produtos devem ser guardados com cuidado.", "w": ["These", "products", "must", "be", "stored", "carefully"]}, {"t": "b", "pt": "A água pode ser contaminada.", "w": ["The", "water", "can", "be", "contaminated"]}]];
