englishB1Plans[35]={"title": "A máquina parada na linha da fábrica", "file": "", "grammar": "Passiva no present perfect: has/have been + particípio", "goal": "Conte o que já foi feito com has/have been + particípio, como em A flaw has been detected.", "words": [["circuit", "circuito"], ["flaw", "defeito, falha"], ["function", "funcionar; função"], ["detect", "detectar"], ["fitted", "instalado, encaixado"], ["clog", "entupimento; entupir"], ["output", "produção, rendimento"], ["product", "produto"]]};
englishB1Content[35]=[[["Line three stopped at six, and the factory's output fell by half.", "A linha três parou às seis, e a produção da fábrica caiu pela metade."], ["A flaw has been detected in the main circuit, and a technician has been called.", "Um defeito foi detectado no circuito principal, e um técnico foi chamado."], ["The old filter has been removed, and a new one has been fitted.", "O filtro velho foi removido, e um novo foi instalado."], ["A clog has been found in the pipe, and it has just been cleaned.", "Um entupimento foi encontrado no cano, e ele acabou de ser limpo."], ["The machine hasn't been tested yet, but it should function again by noon.", "A máquina ainda não foi testada, mas deve funcionar de novo até o meio-dia."], ["All the products from this morning have been checked, and nothing was lost.", "Todos os produtos desta manhã foram conferidos, e nada se perdeu."]], [["Kenji, what's going on with line three? The screen is still red.", "Kenji, o que está acontecendo com a linha três? A tela ainda está vermelha."], ["A flaw has been detected in the circuit, but the technician is already here.", "Um defeito foi detectado no circuito, mas o técnico já está aqui."], ["How long will it take? We have a big order to ship by five.", "Quanto tempo vai levar? Temos um pedido grande para enviar até as cinco."], ["About two hours. The old filter has been removed, and the new one is arriving now.", "Cerca de duas horas. O filtro velho foi removido, e o novo está chegando agora."], ["Good. Is there a clog in the pipe too, like last week?", "Bom. Tem um entupimento no cano também, como na semana passada?"], ["No, we fixed that problem last week, so the pipe is clean now.", "Não, resolvemos aquele problema semana passada, então o cano está limpo agora."], ["Great. Have you told the manager that our output is down today?", "Ótimo. Você avisou a gerente que nossa produção caiu hoje?"], ["Yes, I have. She says the delayed products have been moved to line two.", "Sim, avisei. Ela diz que os produtos atrasados foram movidos para a linha dois."], ["Perfect. Then we can still finish the order by five o'clock.", "Perfeito. Então ainda podemos terminar o pedido até as cinco horas."], ["Yes, exactly. I'll text you as soon as line three is running again.", "Sim, exatamente. Mando uma mensagem assim que a linha três voltar a funcionar."]], ["/f/ em flaw e function", "Encoste os dentes de cima no lábio de baixo e solte o ar. Em function, a sílaba final é 'chən', sem som de 'ção'.", ["flaw", "function"]], ["A flaw ___ in the circuit.", "has been detected", "has detected", "Um defeito foi detectado no circuito.", "Passiva com resultado agora: has/have been + particípio."], [["A flaw has been detected in the main circuit, and a technician has been called.", "Um defeito foi detectado no circuito principal, e um técnico foi chamado."], ["The old filter has been removed, and a new one has been fitted.", "O filtro velho foi removido, e um novo foi instalado."]], [{"t": "c", "q": "The old filter ___ already.", "o": ["has been removed", "has removed", "have been removed"], "pt": "O filtro velho já foi removido.", "why": "Filter é singular e recebe a ação: has been + particípio."}, {"t": "l", "say": "The machine has been fitted with a new filter.", "o": ["The machine has been fitted with a new filter.", "The machine has fitted with a new filter.", "The machine have been fitted with a new filter."], "why": "Machine é singular e recebe a ação: has been fitted."}, {"t": "b", "pt": "O problema já foi resolvido.", "w": ["The", "problem", "has", "already", "been", "solved"]}, {"t": "b", "pt": "Todos os produtos foram verificados.", "w": ["All", "the", "products", "have", "been", "checked"]}]];
