englishB1Plans[36]={"title": "O quadro roubado no museu de Boston", "file": "", "grammar": "Passiva em perguntas: Was it…? Has anyone been…?", "goal": "Faça perguntas com a passiva, como em Was the alarm turned off?", "words": [["steal", "roubar, furtar"], ["investigate", "investigar"], ["inspector", "inspetor"], ["robbery", "roubo, assalto"], ["arrest", "prender"], ["theft", "furto"], ["victim", "vítima"], ["trace", "rastrear"]]};
englishB1Content[36]=[[["A painting was stolen from a small museum in Boston on Sunday night.", "Um quadro foi roubado de um pequeno museu em Boston no domingo à noite."], ["Inspector Cole came to investigate the robbery and asked many questions.", "O inspetor Cole veio investigar o roubo e fez muitas perguntas."], ["Was the alarm turned off, and was anyone seen near the door?", "O alarme foi desligado, e alguém foi visto perto da porta?"], ["Nobody has been arrested yet, but the thief's car was traced to Maine.", "Ninguém foi preso ainda, mas o carro do ladrão foi rastreado até Maine."], ["The victim of the theft is the museum, and it lost a very old painting.", "A vítima do furto é o museu, que perdeu um quadro muito antigo."], ["Someone tried to steal it once before, but the guard stopped him.", "Alguém tentou roubá-lo uma vez antes, mas o guarda o impediu."]], [["Ben, did you see the news? A painting was stolen from the city museum.", "Ben, você viu a notícia? Um quadro foi roubado do museu da cidade."], ["Yes! Was it stolen at night, or during the day?", "Sim! Foi roubado de noite ou durante o dia?"], ["At night, around two. The guard heard nothing, and the cameras were off.", "À noite, por volta das duas. O guarda não ouviu nada, e as câmeras estavam desligadas."], ["Wow. Has anyone been arrested yet? Do the police have any clue?", "Nossa. Alguém já foi preso? A polícia tem alguma pista?"], ["Not yet. The inspector followed the thief's car to a town in Maine.", "Ainda não. O inspetor seguiu o carro do ladrão até uma cidade no Maine."], ["Good. Is the theft a big loss for the museum? It's a small place.", "Bom. O furto é uma grande perda para o museu? É um lugar pequeno."], ["Yes, it is. It was a gift from a family, and they're very upset.", "Sim, é. Foi um presente de uma família, e eles estão muito chateados."], ["Me too. I'll text you if the police announce anything tonight.", "Eu também. Mando mensagem se a polícia anunciar alguma coisa hoje à noite."]], ["/θ/ em theft e thief", "Ponha a língua entre os dentes e solte o ar: theft e thief começam com th, não com f nem com t.", ["theft", "thief"]], ["___ the painting stolen last night?", "Was", "Did", "O quadro foi roubado ontem à noite?", "Pergunta passiva: Was/Were + sujeito + particípio, sem did."], [["Was the alarm turned off, and was anyone seen near the door?", "O alarme foi desligado, e alguém foi visto perto da porta?"], ["Nobody has been arrested yet, but the thief's car was traced to Maine.", "Ninguém foi preso ainda, mas o carro do ladrão foi rastreado até Maine."]], [{"t": "c", "q": "___ anyone arrested after the robbery?", "o": ["Was", "Did", "Were"], "pt": "Alguém foi preso depois do roubo?", "why": "Anyone é singular e a pergunta é passiva: Was + particípio."}, {"t": "l", "say": "Was the alarm turned off?", "o": ["Was the alarm turned off?", "Did the alarm turned off?", "Is the alarm turned off?"], "why": "No passado, a pergunta passiva usa Was + particípio, sem did."}, {"t": "b", "pt": "O ladrão foi preso ontem?", "w": ["Was", "the", "thief", "arrested", "yesterday"]}, {"t": "b", "pt": "Onde o quadro foi encontrado?", "w": ["Where", "was", "the", "painting", "found"]}]];
