englishB1Plans[37]={"title": "As regras da piscina do clube", "file": "", "grammar": "Passiva em avisos, regras e instruções", "goal": "Entenda e escreva regras com a passiva, como em Running is forbidden.", "words": [["prohibit", "proibir"], ["forbid", "proibir, vetar"], ["enforce", "fazer cumprir"], ["supervise", "supervisionar"], ["obey", "obedecer"], ["violate", "violar, infringir"], ["illegal", "ilegal"], ["obligation", "obrigação"], ["licence", "licença, habilitação"]]};
englishB1Content[37]=[[["Running near the pool is forbidden, and children must be supervised by an adult.", "Correr perto da piscina é proibido, e crianças devem ser supervisionadas por um adulto."], ["Glass bottles are not allowed, and loud music is prohibited after nine p.m.", "Garrafas de vidro não são permitidas, e música alta é proibida depois das nove da noite."], ["Guests who violate these rules will be asked to leave the club.", "Convidados que infringirem estas regras serão convidados a deixar o clube."], ["Lifeguards are paid to enforce the rules, so please obey them.", "Salva-vidas são pagos para fazer cumprir as regras, então por favor obedeça a elas."], ["Swimming alone at night is illegal here, and the club's rules must be respected.", "Nadar sozinho à noite é ilegal aqui, e as regras do clube devem ser respeitadas."], ["A licence is required for diving, and it must be shown at the desk.", "Uma habilitação é exigida para mergulho, e ela deve ser mostrada na recepção."]], [["Tom, look at that sign. Is it forbidden to eat near the pool?", "Tom, olhe aquela placa. É proibido comer perto da piscina?"], ["Yes, snacks are prohibited, but you can eat at the café across the street.", "Sim, lanches são proibidos, mas você pode comer no café do outro lado da rua."], ["Okay. And what's the rule about the kids? Mine love to run everywhere.", "Certo. E qual é a regra para as crianças? As minhas adoram correr por tudo."], ["It's your obligation to supervise them, and the lifeguards will enforce the rules.", "É sua obrigação supervisioná-las, e os salva-vidas vão fazer cumprir as regras."], ["Fair enough. Do they really send people home if they don't obey?", "Justo. Eles mandam mesmo as pessoas para casa se não obedecerem?"], ["Sometimes. Last week a teenager was asked to leave because he kept diving.", "Às vezes. Semana passada um adolescente foi convidado a sair porque ficou mergulhando."], ["Ouch. Do I need a licence just to swim in the deep area?", "Ai. Preciso de habilitação só para nadar na parte funda?"], ["Only to dive, so you don't need one. I'll show you the desk anyway.", "Só para mergulhar, então você não precisa. Mesmo assim, vou mostrar a recepção."]], ["/eɪ/ em violate e obligation", "Em -ate e -ation o som é /eɪ/, como em 'day'. Diga vai-o-LEIT e o-bli-GUEI-shən.", ["violate", "obligation"]], ["Smoking ___ in this building.", "is prohibited", "is prohibit", "Fumar é proibido neste prédio.", "Regras usam is/are + particípio: is prohibited."], [["Running near the pool is forbidden, and children must be supervised by an adult.", "Correr perto da piscina é proibido, e crianças devem ser supervisionadas por um adulto."], ["Glass bottles are not allowed, and loud music is prohibited after nine p.m.", "Garrafas de vidro não são permitidas, e música alta é proibida depois das nove da noite."]], [{"t": "c", "q": "Children ___ by an adult at all times.", "o": ["must be supervised", "must supervised", "must supervise"], "pt": "Crianças devem ser supervisionadas por um adulto o tempo todo.", "why": "As crianças recebem a ação: must be + particípio."}, {"t": "l", "say": "Glass bottles are not allowed here.", "o": ["Glass bottles are not allowed here.", "Glass bottles are not allow here.", "Glass bottle is not allowed here."], "why": "Plural e passiva: are not allowed."}, {"t": "b", "pt": "Mergulhar é proibido nesta piscina.", "w": ["Diving", "is", "prohibited", "in", "this", "pool"]}, {"t": "b", "pt": "As regras devem ser respeitadas.", "w": ["The", "rules", "must", "be", "obeyed"]}]];
