englishB1Plans[38]={"title": "O comunicado do novo celular à imprensa", "file": "", "grammar": "Ativa vs passiva: quando escolher cada uma", "goal": "Escolha ativa ou passiva conforme o que importa: quem fez (Mia wrote it) ou a ação (It was written).", "words": [["media", "mídia, imprensa"], ["official", "oficial; funcionário"], ["release", "lançar; divulgar"], ["spokesperson", "porta-voz"], ["bulletin", "comunicado, boletim"], ["declare", "declarar"], ["issue", "emitir, publicar"], ["inform", "informar"]]};
englishB1Content[38]=[[["The spokesperson told the media that a new phone will be released in May.", "A porta-voz disse à imprensa que um celular novo será lançado em maio."], ["A short bulletin was issued by the company, and an official confirmed the date.", "Um breve comunicado foi emitido pela empresa, e um responsável confirmou a data."], ["Reporters declared the news exciting, but the company gave very few details.", "Os repórteres declararam a notícia empolgante, mas a empresa deu pouquíssimos detalhes."], ["Nobody knows who made the phone, because the design is kept secret.", "Ninguém sabe quem fez o celular, porque o design é mantido em segredo."], ["The prices will be announced next week, so customers should not worry yet.", "Os preços serão anunciados na semana que vem, então os clientes não devem se preocupar ainda."], ["I was informed by email, and my boss called a meeting that afternoon.", "Fui informado por e-mail, e meu chefe marcou uma reunião naquela tarde."]], [["Sam, did you read the bulletin? The company will release a new phone in May.", "Sam, você leu o comunicado? A empresa vai lançar um celular novo em maio."], ["I did. I was informed by email at six, before the media knew.", "Li. Fui informado por e-mail às seis, antes de a imprensa saber."], ["Who made the announcement, an official or the spokesperson?", "Quem fez o anúncio, um responsável ou a porta-voz?"], ["The spokesperson did. She declared that the phone is faster than ever.", "A porta-voz. Ela declarou que o celular está mais rápido do que nunca."], ["Interesting. Some reports say the phone was released without saying who did it.", "Interessante. Algumas reportagens dizem que o celular foi lançado sem dizer quem o fez."], ["That's because the company is the obvious doer, so the report focuses on the phone.", "Isso é porque a empresa é o autor óbvio, então a reportagem foca no celular."], ["I see. And when the doer matters, we say Apple released the phone, right?", "Entendi. E quando o autor importa, dizemos que a Apple lançou o celular, certo?"], ["Exactly. Use the active when the doer is important, and the passive when the action is.", "Exatamente. Use a ativa quando o autor é importante, e a passiva quando a ação é."], ["Clear. So the phone was designed by Mia sounds good if Mia is famous.", "Claro. Então o celular foi projetado por Mia soa bem se Mia for famosa."], ["Exactly! Let's practice with tonight's news. It's a good exercise.", "Exato! Vamos praticar com as notícias de hoje à noite. É um bom exercício."]], ["/ʃ/ em official e issue", "Arredonde os lábios e solte o ar como em 'chuva' suave: of-FI-shəl e I-shu. O som é /ʃ/, não 'ss'.", ["official", "issue"]], ["Mia ___ the report last night, so she's tired.", "wrote", "was written", "Mia escreveu o relatório ontem à noite, por isso está cansada.", "Mia é quem fez a ação e é o sujeito, então use a ativa: wrote."], [["The spokesperson told the media that a new phone will be released in May.", "A porta-voz disse à imprensa que um celular novo será lançado em maio."], ["I was informed by email, and my boss called a meeting that afternoon.", "Fui informado por e-mail, e meu chefe marcou uma reunião naquela tarde."]], [{"t": "c", "q": "The spokesperson ___ the news to the media on Monday.", "o": ["told", "was told", "is told"], "pt": "A porta-voz contou a notícia à imprensa na segunda.", "why": "A porta-voz fez a ação e é o sujeito: ativa, told."}, {"t": "l", "say": "A bulletin was issued on Monday.", "o": ["A bulletin was issued on Monday.", "A bulletin issued on Monday.", "A bulletin was issue on Monday."], "why": "O comunicado recebe a ação: was issued."}, {"t": "b", "pt": "O telefone será lançado em maio.", "w": ["The", "phone", "will", "be", "released", "in", "May"]}, {"t": "b", "pt": "A porta-voz contou a notícia à mídia.", "w": ["The", "spokesperson", "told", "the", "media", "the", "news"]}]];
