englishB1Plans[39]={"title": "A fábrica de chocolate da Rosa", "file": "", "grammar": "Revisão: a fábrica de chocolate (passiva)", "goal": "Revise a voz passiva em todos os tempos numa visita a uma fábrica de chocolate.", "words": [["grind", "moer"], ["crisp", "crocante"], ["nutrient", "nutriente"], ["crush", "esmagar, triturar"], ["cube", "cubo"], ["fluid", "líquido, fluido"], ["production", "produção"], ["produce", "produzir"]]};
englishB1Content[39]=[[["At Rosa's factory, the beans are roasted, and then a machine grinds them.", "Na fábrica da Rosa, as sementes são torradas, e depois uma máquina as moi."], ["The warm paste is pressed, and the fluid chocolate is poured into big tanks.", "A pasta morna é prensada, e o chocolate líquido é despejado em grandes tanques."], ["Crisp nuts are crushed and added, and they give the chocolate extra nutrients.", "Nozes crocantes são trituradas e adicionadas, e dão ao chocolate nutrientes extras."], ["Then the chocolate is cut into small cubes and wrapped by workers in gold paper.", "Depois o chocolate é cortado em pequenos cubos e embrulhado pelos funcionários em papel dourado."], ["Production is stopped each evening, and the machines are cleaned by a night team.", "A produção é parada toda noite, e as máquinas são limpas por uma equipe noturna."], ["The factory produces two tons of chocolate every day, and all of it is sold.", "A fábrica produz duas toneladas de chocolate por dia, e tudo é vendido."]], [["Rosa, thanks for the tour. How is all this chocolate made every day?", "Rosa, obrigada pela visita. Como todo esse chocolate é feito todo dia?"], ["First we roast the beans. Then a big machine grinds them into a thick paste.", "Primeiro torramos as sementes. Depois uma máquina grande as moi até virar uma pasta grossa."], ["And the fluid chocolate? Does it go straight to the production line?", "E o chocolate líquido? Vai direto para a linha de produção?"], ["Yes, it does. We crush some nuts and add them for crunch and nutrients.", "Vai, sim. Trituramos algumas nozes e as adicionamos para dar crocância e nutrientes."], ["Do you produce the cubes here, or are they bought from another factory?", "Vocês produzem os cubos aqui, ou eles são comprados de outra fábrica?"], ["We produce them here. They're cut by a machine and checked by hand.", "Produzimos aqui. Eles são cortados por uma máquina e conferidos à mão."], ["Impressive. Did your grandfather start the business with the same recipe?", "Impressionante. Seu avô começou o negócio com a mesma receita?"], ["Almost. He used sugar and milk, but we've added crisp nuts and a little salt.", "Quase. Ele usava açúcar e leite, mas nós acrescentamos nozes crocantes e um pouco de sal."], ["I love it. Can I take a photo of the line before I leave?", "Adorei. Posso tirar uma foto da linha antes de ir embora?"], ["Of course. Stay behind the yellow line, and I'll bring you a box to take home.", "Claro. Fique atrás da linha amarela, e eu trago uma caixa para você levar para casa."]], ["/ʌ/ em crush e production", "É uma vogal curta e relaxada, entre 'a' e 'é', sem abrir a boca: krʌsh e pro-DʌK-shən.", ["crush", "production"]], ["Chocolate ___ here every day.", "is produced", "is produce", "O chocolate é produzido aqui todos os dias.", "Passiva no presente: is + particípio (produced), nunca o verbo base."], [["Then the chocolate is cut into small cubes and wrapped by workers in gold paper.", "Depois o chocolate é cortado em pequenos cubos e embrulhado pelos funcionários em papel dourado."], ["The factory produces two tons of chocolate every day, and all of it is sold.", "A fábrica produz duas toneladas de chocolate por dia, e tudo é vendido."]], [{"t": "c", "q": "The nuts ___ and added to the chocolate.", "o": ["are crushed", "are crushing", "crush"], "pt": "As nozes são trituradas e adicionadas ao chocolate.", "why": "As nozes recebem a ação: are + particípio."}, {"t": "l", "say": "The chocolate is cut into small cubes.", "o": ["The chocolate is cut into small cubes.", "The chocolate is cutting into small cubes.", "The chocolate cuts into small cubes."], "why": "O chocolate recebe a ação: is cut."}, {"t": "b", "pt": "Os cubos são embrulhados por trabalhadores.", "w": ["The", "cubes", "are", "wrapped", "by", "workers"]}, {"t": "b", "pt": "A fábrica produz duas toneladas por dia.", "w": ["The", "factory", "produces", "two", "tons", "every", "day"]}]];
