englishB1MiniStories[39]=["Um dia na fábrica de chocolate", "Mia visited a chocolate factory, and a guide showed her around.~Mia visitou uma fábrica de chocolate, e uma guia a levou para conhecer tudo.|Chocolate is made here from beans that are grown in Bahia, the guide said.~O chocolate é feito aqui com sementes que são cultivadas na Bahia, disse a guia.|The factory was founded by a family fifty years ago.~A fábrica foi fundada por uma família há cinquenta anos.|A new building will be constructed next year, and the old one will be demolished.~Um prédio novo será construído no ano que vem, e o velho será demolido.|Suddenly a machine stopped, and the guide said, A flaw has been detected.~De repente uma máquina parou, e a guia disse: um defeito foi detectado.|Was anyone hurt? Nobody was, and the problem was fixed in ten minutes.~Alguém se machucou? Ninguém, e o problema foi resolvido em dez minutos.|Visitors must be kept behind the yellow line, so Mia obeyed the sign.~Os visitantes devem ficar atrás da linha amarela, então Mia obedeceu à placa.|The line started again, and fresh chocolate was poured into small trays.~A linha voltou a funcionar, e chocolate fresquinho foi despejado em pequenas formas.|Mia tasted a piece, and she told the guide, This is perfect.~Mia provou um pedaço e disse à guia: está perfeito.|Her article will be published on Friday, and the whole city will read about it.~O artigo dela será publicado na sexta, e a cidade inteira vai ler sobre isso."];
englishB1Plans[40]={"title": "A reunião sobre o novo fornecedor", "file": "", "grammar": "Discurso indireto afirmativo: said that… com recuo de tempo", "goal": "Conte o que a gerente disse usando said that… e passe o verbo para o passado.", "words": [["supplier", "fornecedor"], ["defect", "defeito"], ["launch", "lançamento"], ["supply", "fornecimento, estoque"], ["demand", "demanda, procura"], ["remark", "comentário"], ["in charge", "responsável"], ["relatively", "relativamente"]]};
englishB1Content[40]=[[["On Monday, our manager Ms. Rivera called a quick meeting about the new product.", "Na segunda, nossa gerente, a Sra. Rivera, chamou uma reunião rápida sobre o novo produto."], ["She said that our main supplier had a defect in the last batch.", "Ela disse que nosso principal fornecedor teve um defeito no último lote."], ["She told us that the launch would be later than we planned.", "Ela nos disse que o lançamento seria mais tarde do que planejamos."], ["She said that the supply of parts was relatively small this month.", "Ela disse que o estoque de peças estava relativamente pequeno neste mês."], ["Tom said that customer demand was growing and that he was in charge of orders.", "Tom disse que a demanda dos clientes estava crescendo e que ele era responsável pelos pedidos."], ["In the end, Ms. Rivera said that we would find a new supplier by Friday.", "No fim, a Sra. Rivera disse que acharíamos um novo fornecedor até sexta."]], [["You missed the meeting, Ben. Ms. Rivera said that the launch was in danger.", "Você perdeu a reunião, Ben. A Sra. Rivera disse que o lançamento estava em perigo."], ["Really? What else did she say? Was it a problem with the supplier?", "Sério? O que mais ela disse? Foi um problema com o fornecedor?"], ["Yes. She said that the last batch had a defect, so we couldn't ship it.", "Sim. Ela disse que o último lote tinha um defeito, então não pudemos enviá-lo."], ["That's bad. Who is in charge of fixing it now?", "Que ruim. Quem é o responsável por resolver isso agora?"], ["Tom is. He said that he would call the supplier at nine and demand a refund.", "O Tom. Ele disse que ligaria para o fornecedor às nove e exigiria reembolso."], ["Good idea. Is there enough supply for next month, though?", "Boa ideia. Mas há estoque suficiente para o mês que vem?"], ["Relatively okay, but she made one remark that worried me. She said that we might lose two weeks.", "Relativamente bem, mas ela fez um comentário que me preocupou. Disse que podíamos perder duas semanas."], ["So the launch is still on, but it could be late. Got it, thanks, Ana.", "Então o lançamento continua, mas pode atrasar. Entendi, obrigado, Ana."]], ["/s/ inicial em supply e supplier", "Em supply e supplier, o s no começo é um /s/ limpo, sem vogal antes (não diga 'esupply'). Fale: sup-LAI e sup-LAI-er.", ["supply", "supplier"]], ["Ms. Rivera said that the launch ___ in danger.", "was", "is", "A Sra. Rivera disse que o lançamento estava em perigo.", "Depois de said no passado, o verbo recua: is vira was."], [["She said that our main supplier had a defect in the last batch.", "Ela disse que nosso principal fornecedor teve um defeito no último lote."], ["Tom is. He said that he would call the supplier at nine and demand a refund.", "O Tom. Ele disse que ligaria para o fornecedor às nove e exigiria reembolso."]], [{"t": "c", "q": "Tom said that he ___ call the supplier.", "o": ["would", "will", "is"], "pt": "Tom disse que ligaria para o fornecedor.", "why": "Em relato no passado, will vira would."}, {"t": "l", "say": "She said that the launch was in danger.", "o": ["She said that the launch was in danger.", "She says that the launch were in danger.", "She said that the launch will be in danger."], "why": "No relato, said pede o verbo no passado: was."}, {"t": "b", "pt": "Ela disse que o fornecedor tinha um defeito.", "w": ["She", "said", "that", "the", "supplier", "had", "a", "defect"]}, {"t": "b", "pt": "Tom disse que ligaria para o fornecedor.", "w": ["Tom", "said", "that", "he", "would", "call", "the", "supplier"]}]];
