englishB1Plans[41]={"title": "Um apelido que machucou no time de futebol", "file": "", "grammar": "Say vs tell e mudanças de pronome e lugar", "goal": "Use said that… e told someone that… sem confundir, trocando I por he/she no relato.", "words": [["teammate", "colega de time"], ["tease", "provocar, zoar"], ["nonsense", "bobagem"], ["embarrass", "constranger"], ["shame", "pena, vergonha"], ["stand up for", "defender"], ["praise", "elogiar"], ["fault", "culpa"]]};
englishB1Content[41]=[[["After Saturday's game, Leo told his teammates that he was tired of the jokes.", "Depois do jogo de sábado, Leo disse a seus colegas que estava cansado das piadas."], ["Some players teased him because he missed an easy goal in the second half.", "Alguns jogadores o zoaram porque ele errou um gol fácil no segundo tempo."], ["Leo said that it was nonsense, and it embarrassed him in front of his friends.", "Leo disse que era bobagem, e isso o constrangeu na frente dos amigos."], ["Coach Dana told them that the loss was not one player's fault.", "A técnica Dana disse a eles que a derrota não era culpa de um só jogador."], ["She said it was a shame to tease a teammate after a hard game.", "Ela disse que era uma pena zoar um colega depois de um jogo difícil."], ["Then Sam said he would stand up for Leo and praise his effort.", "Então o Sam disse que defenderia o Leo e elogiaria o esforço dele."]], [["Leo told me that the team teased him after the game. Is that true, Sam?", "O Leo me disse que o time o zoou depois do jogo. É verdade, Sam?"], ["Yes. Some guys said that he was too slow, and it was nonsense.", "Sim. Uns caras disseram que ele era lento demais, e foi bobagem."], ["That's a shame. Did you say anything to them at the field?", "Que pena. Você disse alguma coisa a eles no campo?"], ["I told them that it wasn't his fault. The whole team lost the ball.", "Eu disse a eles que não era culpa dele. O time inteiro perdeu a bola."], ["Good. Leo said that he felt embarrassed in front of the coach.", "Bom. O Leo disse que se sentiu constrangido na frente da técnica."], ["I know. I'll stand up for him at practice tomorrow, I promise.", "Eu sei. Vou defendê-lo no treino amanhã, eu prometo."], ["That's great. I'll praise his two assists, too. He played really well.", "Ótimo. Vou elogiar as duas assistências dele também. Ele jogou muito bem."], ["Deal. I'll tell him that we're all his teammates, not his enemies.", "Combinado. Vou dizer a ele que somos todos colegas de time, não inimigos."]], ["/iː/ longo em teammate e tease", "Em teammate e tease, o ea soa como um /iː/ longo, 'ii'. Estique o som: TIIM-meit e TIIZ, sem encurtar como em 'tim'.", ["teammate", "tease"]], ["Coach Dana ___ them that it was not Leo's fault.", "told", "said", "A técnica Dana disse a eles que não era culpa do Leo.", "Tell leva a pessoa logo depois (told them); say não leva."], [["Coach Dana told them that the loss was not one player's fault.", "A técnica Dana disse a eles que a derrota não era culpa de um só jogador."], ["I told them that it wasn't his fault. The whole team lost the ball.", "Eu disse a eles que não era culpa dele. O time inteiro perdeu a bola."]], [{"t": "c", "q": "Leo ___ that he was tired of the jokes.", "o": ["said", "told", "tell"], "pt": "Leo disse que estava cansado das piadas.", "why": "Sem pessoa depois, usamos said that."}, {"t": "l", "say": "Sam told me that he would help.", "o": ["Sam told me that he would help.", "Sam said me that he would help.", "Sam told that he would help."], "why": "Told pede a pessoa (me); said não."}, {"t": "b", "pt": "Ela me disse que era uma pena.", "w": ["She", "told", "me", "that", "it", "was", "a", "shame"]}, {"t": "b", "pt": "Sam disse que o time zoou o Leo.", "w": ["Sam", "said", "that", "the", "team", "teased", "Leo"]}]];
englishB1PhotoThemes[41]="map";
englishB1Plans[42]={"title": "Contando como foi a entrevista de emprego", "file": "", "grammar": "Perguntas indiretas relatadas: asked if/whether…", "goal": "Relate perguntas de sim ou não usando asked if… ou asked whether… com o verbo no passado.", "words": [["interviewee", "entrevistado"], ["qualify", "ser qualificado"], ["requirement", "requisito"], ["thorough", "detalhado, completo"], ["fill in", "preencher"], ["previous", "anterior"], ["reluctant", "relutante"], ["extremely", "extremamente"]]};
englishB1Content[42]=[[["Priya had a job interview at a travel company yesterday afternoon.", "A Priya fez uma entrevista de emprego numa agência de viagens ontem à tarde."], ["The manager asked her if she met every requirement for the position.", "A gerente perguntou se ela atendia a todos os requisitos da vaga."], ["He also asked whether she had a previous job in sales.", "Ele também perguntou se ela tinha um emprego anterior em vendas."], ["Priya said she was extremely nervous, but she gave a thorough answer.", "A Priya disse que estava extremamente nervosa, mas deu uma resposta completa."], ["He asked if she was reluctant to travel, and she said no.", "Ele perguntou se ela era relutante em viajar, e ela disse que não."], ["At the end, she had to fill in a short form about her experience.", "No fim, ela teve de preencher um formulário curto sobre sua experiência."]], [["How was the interview? Did they ask you a lot of hard questions?", "Como foi a entrevista? Fizeram muitas perguntas difíceis?"], ["Yes. The manager asked if I could qualify for a senior position next year.", "Sim. A gerente perguntou se eu poderia me qualificar para um cargo sênior no ano que vem."], ["Wow. Did she ask whether you were happy with a lower salary first?", "Nossa. Ela perguntou se você aceitaria um salário menor primeiro?"], ["She did. I was the third interviewee, and she looked very tired.", "Perguntou. Eu era a terceira entrevistada, e ela parecia muito cansada."], ["Poor woman. Did she ask about your previous manager?", "Coitada. Ela perguntou sobre seu gerente anterior?"], ["She asked if he would give me a good reference, and I said yes.", "Ela perguntou se ele me daria uma boa referência, e eu disse que sim."], ["Great. Were you extremely nervous? Last time you couldn't speak at all.", "Ótimo. Você ficou extremamente nervosa? Da última vez não conseguiu falar."], ["At first, yes, but my answers were thorough, and she said she would call me Friday.", "No começo, sim, mas minhas respostas foram completas, e ela disse que me ligaria sexta."]], ["/kw/ em qualify e requirement", "Em qualify e requirement, o qu soa /kw/, como 'cu-u' rápido: KWÓ-li-fai e ri-KWAI-er-ment. O u não é vogal separada.", ["qualify", "requirement"]], ["The manager asked me ___ I had a previous job.", "if", "that", "A gerente me perguntou se eu tinha um emprego anterior.", "Pergunta de sim ou não relatada usa if ou whether, não that."], [["The manager asked her if she met every requirement for the position.", "A gerente perguntou se ela atendia a todos os requisitos da vaga."], ["She asked if he would give me a good reference, and I said yes.", "Ela perguntou se ele me daria uma boa referência, e eu disse que sim."]], [{"t": "c", "q": "She asked ___ I was ready for the job.", "o": ["whether", "that", "do"], "pt": "Ela perguntou se eu estava pronta para a vaga.", "why": "Para sim ou não, usamos if ou whether depois de asked."}, {"t": "l", "say": "He asked if she met every requirement.", "o": ["He asked if she met every requirement.", "He asked if did she meet every requirement.", "He asked that she met every requirement."], "why": "No relato a ordem é normal (she met), sem did."}, {"t": "b", "pt": "Ele perguntou se ela tinha um emprego anterior.", "w": ["He", "asked", "if", "she", "had", "a", "previous", "job"]}, {"t": "b", "pt": "Ela perguntou se eu estava nervoso.", "w": ["She", "asked", "whether", "I", "was", "nervous"]}]];
