englishB1Plans[43]={"title": "Controle de segurança antes do voo para Denver", "file": "", "grammar": "Pedidos e ordens relatados: told me to… / asked me not to…", "goal": "Relate o que um oficial mandou ou pediu usando told me to… e asked me not to….", "words": [["inspection", "inspeção, revista"], ["remove", "tirar, remover"], ["fasten", "apertar, afivelar"], ["refuse", "recusar"], ["step aside", "sair da frente"], ["otherwise", "senão, caso contrário"], ["proceed", "seguir, prosseguir"], ["exact", "exato"]]};
englishB1Content[43]=[[["Kenji arrived at the airport two hours before his flight to Denver.", "O Kenji chegou ao aeroporto duas horas antes do voo para Denver."], ["At security, an officer told him to remove his belt and his shoes.", "Na segurança, um oficial mandou ele tirar o cinto e os sapatos."], ["A second officer asked him to step aside for a bag inspection.", "Um segundo oficial pediu que ele saísse da frente para a revista da bolsa."], ["She told him not to touch the box, otherwise she would start again.", "Ela disse para ele não tocar na caixa, senão ela recomeçaria."], ["Kenji did not refuse, and the officer let him proceed to gate twelve.", "O Kenji não recusou, e a oficial o deixou seguir para o portão doze."], ["On the plane, the flight attendant told everyone to fasten their seat belts.", "No avião, a comissária mandou todos apertarem os cintos."]], [["Did you make your flight, Kenji? You sounded worried on the phone.", "Você pegou seu voo, Kenji? Você parecia preocupado no telefone."], ["Yes, but barely. An officer told me to remove my shoes and my jacket.", "Sim, mas por pouco. Um oficial me mandou tirar os sapatos e a jaqueta."], ["That's normal. Did anyone ask you to open your bag, too?", "Isso é normal. Alguém pediu para você abrir a bolsa também?"], ["Yes. A second officer asked me to step aside for an inspection.", "Sim. Um segundo oficial me pediu para sair da frente para uma inspeção."], ["What did she say about the box? It was a gift for your sister, right?", "O que ela disse sobre a caixa? Era um presente para sua irmã, certo?"], ["She asked me not to touch it. She said the exact rule was no sealed boxes.", "Ela me pediu para não tocar nela. Disse que a regra exata era nada de caixas lacradas."], ["Ugh. Did you refuse to open it, or did you just pay attention and obey?", "Nossa. Você se recusou a abrir, ou só prestou atenção e obedeceu?"], ["I opened it, otherwise I couldn't proceed. The cake was fine, and I made my flight.", "Abri, senão não poderia seguir. O bolo estava bem, e eu peguei meu voo."]], ["/ʃən/ final em inspection e attention", "Em inspection e attention, o final -tion soa /ʃən/, como 'chên' curto. Acentue a sílaba antes: in-SPÉK-shən e a-TÉN-shən.", ["inspection", "attention"]], ["The officer told me ___ my shoes.", "to remove", "remove", "O oficial me mandou tirar os sapatos.", "Depois de told me usamos to + verbo: told me to remove."], [["At security, an officer told him to remove his belt and his shoes.", "Na segurança, um oficial mandou ele tirar o cinto e os sapatos."], ["She asked me not to touch it. She said the exact rule was no sealed boxes.", "Ela me pediu para não tocar nela. Disse que a regra exata era nada de caixas lacradas."]], [{"t": "c", "q": "She asked me ___ touch the bag.", "o": ["not to", "to not", "don't"], "pt": "Ela me pediu para não tocar na bolsa.", "why": "O pedido negativo relatado é asked me not to + verbo."}, {"t": "l", "say": "He told us to fasten our seat belts.", "o": ["He told us to fasten our seat belts.", "He told us fasten our seat belts.", "He told us that fasten our seat belts."], "why": "Told us + to + verbo."}, {"t": "b", "pt": "O oficial me disse para tirar os sapatos.", "w": ["The", "officer", "told", "me", "to", "remove", "my", "shoes"]}, {"t": "b", "pt": "Ele me pediu para não tocar na caixa.", "w": ["He", "asked", "me", "not", "to", "touch", "the", "box"]}]];
