englishB1Plans[44]={"title": "O vaso quebrado do apartamento", "file": "", "grammar": "Verbos de relato: promise, suggest, warn, admit", "goal": "Relate o que alguém admitiu, negou, aconselhou ou garantiu usando verbos de relato.", "words": [["admit", "admitir"], ["deny", "negar"], ["advise", "aconselhar"], ["assure", "garantir, assegurar"], ["scold", "dar bronca"], ["urge", "insistir, pedir com força"], ["suggestion", "sugestão"], ["hint", "dar uma dica"]]};
englishB1Content[44]=[[["Ben broke his roommate's favorite vase while he was cleaning the living room.", "O Ben quebrou o vaso favorito da colega de apartamento enquanto limpava a sala."], ["At first, Ben tried to deny it, but then he admitted the truth.", "No começo, o Ben tentou negar, mas depois admitiu a verdade."], ["Rosa promised that she wouldn't be angry if he told the truth.", "A Rosa prometeu que não ficaria brava se ele dissesse a verdade."], ["His friend Tom advised him to buy a new one before she came home.", "O amigo Tom o aconselhou a comprar um novo antes que ela chegasse."], ["Tom hinted that there was a sale online, and Ben liked the suggestion.", "O Tom deu a dica de que havia uma promoção online, e o Ben gostou da sugestão."], ["In the end, Rosa scolded him a little, and she urged him to be more careful.", "No fim, a Rosa deu uma bronca nele e o pediu para ter mais cuidado."]], [["Ben, I saw the empty shelf. Did something happen to my vase?", "Ben, vi a prateleira vazia. Aconteceu algo com meu vaso?"], ["I admit that I dropped it this morning. I'm so sorry, Rosa.", "Admito que derrubei hoje de manhã. Sinto muito, Rosa."], ["Tom told me that you tried to deny it. Is that true?", "O Tom me disse que você tentou negar. É verdade?"], ["Yes, but I was scared. I promise that I'll buy you a new one tomorrow.", "Sim, mas eu estava com medo. Prometo que compro um novo para você amanhã."], ["Tom also said that he advised you to tell me the truth. That was good advice.", "O Tom também disse que te aconselhou a me contar a verdade. Foi um bom conselho."], ["He urged me to call you right away, and I didn't. I feel terrible.", "Ele insistiu para eu te ligar na hora, e eu não liguei. Me sinto péssimo."], ["I won't scold you for long. Tom hinted that a shop downtown still has the same vase.", "Não vou te dar bronca por muito tempo. O Tom deu a dica de que uma loja no centro ainda tem o mesmo vaso."], ["Great suggestion. I'll go there at ten, and I assure you that it will be perfect.", "Ótima sugestão. Vou lá às dez e garanto que será perfeito."]], ["/əd/ átono em admit e advise", "Em admit e advise, a sílaba ad- é fraca e soa /əd/, quase 'ed'. A força está em -MIT e -VAIZ: ed-MIT e ed-VAIZ.", ["admit", "advise"]], ["Ben promised that he ___ buy a new one.", "would", "will", "O Ben prometeu que compraria um novo.", "Depois de promised no passado, will vira would."], [["Rosa promised that she wouldn't be angry if he told the truth.", "A Rosa prometeu que não ficaria brava se ele dissesse a verdade."], ["I admit that I dropped it this morning. I'm so sorry, Rosa.", "Admito que derrubei hoje de manhã. Sinto muito, Rosa."]], [{"t": "c", "q": "Tom advised Ben ___ call her.", "o": ["to", "that", "for"], "pt": "O Tom aconselhou o Ben a ligar para ela.", "why": "Advised + pessoa + to + verbo."}, {"t": "l", "say": "Ben admitted that he broke the vase.", "o": ["Ben admitted that he broke the vase.", "Ben admitted to that he break the vase.", "Ben admitted that he breaks the vase."], "why": "Admitted that + passado simples."}, {"t": "b", "pt": "Ele admitiu que quebrou o vaso.", "w": ["He", "admitted", "that", "he", "broke", "the", "vase"]}, {"t": "b", "pt": "Ela prometeu que não ficaria brava.", "w": ["She", "promised", "that", "she", "wouldn't", "be", "angry"]}]];
