englishB1Plans[45]={"title": "Passando recados da recepção do consultório", "file": "", "grammar": "Relatar recados e mensagens de voz", "goal": "Passe adiante um recado de voz dizendo He said that… e She asked me to….", "words": [["retell", "recontar"], ["rely", "contar com, confiar"], ["murmur", "murmurar"], ["overhear", "ouvir sem querer"], ["lately", "ultimamente"], ["frequently", "com frequência"], ["glance", "olhar rápido"], ["fade", "sumir, ficar fraco"]]};
englishB1Content[45]=[[["Lia works at the front desk of a dental clinic downtown.", "A Lia trabalha na recepção de uma clínica odontológica no centro."], ["Lately, many patients have left voice messages after closing time.", "Ultimamente, muitos pacientes têm deixado recados de voz depois do fechamento."], ["She played Mr. Park's message, but his voice faded at the end.", "Ela ouviu o recado do Sr. Park, mas a voz dele sumiu no final."], ["She heard him murmur that he would be late for his appointment.", "Ela o ouviu murmurar que se atrasaria para a consulta."], ["Lia glanced at the clock and called Dr. Silva to retell the message.", "A Lia deu uma olhada no relógio e ligou para a Dra. Silva para recontar o recado."], ["Dr. Silva said she could rely on Lia to pass on every message.", "A Dra. Silva disse que podia contar com a Lia para passar todos os recados."]], [["Did anyone call while I was at lunch? I'm expecting an important message.", "Alguém ligou enquanto eu almoçava? Estou esperando um recado importante."], ["Yes. Mr. Park left a message. He said that he couldn't come at three.", "Sim. O Sr. Park deixou um recado. Disse que não podia vir às três."], ["Did he say why? He frequently cancels, and it's getting annoying.", "Ele disse por quê? Ele cancela com frequência, e isso está ficando chato."], ["He said that his car broke down, and that he would call again tomorrow.", "Ele disse que o carro quebrou e que ligaria de novo amanhã."], ["I also overheard Dr. Silva say that she was free on Thursday.", "Também ouvi sem querer a Dra. Silva dizer que estava livre na quinta."], ["Perfect. Can you retell the whole message to her? She's busy now.", "Perfeito. Você pode recontar o recado inteiro para ela? Ela está ocupada agora."], ["Sure. He also said that he would pay by card, and I wrote it down.", "Claro. Ele também disse que pagaria no cartão, e eu anotei."], ["Great, so he'll call tomorrow and we'll move him to Thursday. Thanks, Lia.", "Ótimo, então ele liga amanhã e passamos a consulta para quinta. Obrigado, Lia."]], ["/r/ inicial em retell e rely", "Em retell e rely, o r inicial é suave, com a língua sem tocar o céu da boca (não é o 'rr' forte). Diga ri-TÉL e ri-LAI.", ["retell", "rely"]], ["Mr. Park said that he ___ come at three.", "couldn't", "can't", "O Sr. Park disse que não podia vir às três.", "No relato, can vira could (can't vira couldn't)."], [["She heard him murmur that he would be late for his appointment.", "Ela o ouviu murmurar que se atrasaria para a consulta."], ["Yes. Mr. Park left a message. He said that he couldn't come at three.", "Sim. O Sr. Park deixou um recado. Disse que não podia vir às três."]], [{"t": "c", "q": "Mr. Park said that he ___ late.", "o": ["would be", "will be", "is"], "pt": "O Sr. Park disse que chegaria atrasado.", "why": "No relato, will be vira would be."}, {"t": "l", "say": "He said that he would call tomorrow.", "o": ["He said that he would call tomorrow.", "He says that he would call yesterday.", "He said that he will call tomorrow."], "why": "Said + would: o verbo recua."}, {"t": "b", "pt": "Ele disse que não podia vir às três.", "w": ["He", "said", "that", "he", "couldn't", "come", "at", "three"]}, {"t": "b", "pt": "Ela disse que estava livre na quinta.", "w": ["She", "said", "that", "she", "was", "free", "on", "Thursday"]}]];
