englishB1Plans[46]={"title": "Quando o vizinho reclamou do barulho", "file": "", "grammar": "Relatar uma conversa em ordem", "goal": "Conte uma conversa na ordem certa com first, then, after that e finally.", "words": [["rudely", "de forma grosseira"], ["resolve", "resolver"], ["disagreement", "desentendimento"], ["confront", "confrontar"], ["involve", "envolver"], ["occur", "ocorrer"], ["nevertheless", "mesmo assim"], ["despite", "apesar de"]]};
englishB1Content[46]=[[["First, Elena knocked on her neighbor's door about the loud music.", "Primeiro, a Elena bateu na porta do vizinho por causa da música alta."], ["Then he answered rudely and said that he wasn't doing anything wrong.", "Então ele respondeu de forma grosseira e disse que não estava fazendo nada de errado."], ["She said that she didn't want to confront him, but it was late.", "Ela disse que não queria confrontá-lo, mas era tarde."], ["After that, they had a long disagreement in the hallway.", "Depois disso, eles tiveram um longo desentendimento no corredor."], ["Nevertheless, they agreed to talk again, and he promised to use headphones.", "Mesmo assim, concordaram em conversar de novo, e ele prometeu usar fones."], ["Finally, despite the bad start, they resolved the problem in ten minutes.", "Por fim, apesar do mau começo, eles resolveram o problema em dez minutos."]], [["So what happened with the neighbor? Start from the beginning, Elena.", "E o que aconteceu com o vizinho? Comece do início, Elena."], ["First, I knocked, and he rudely told me to mind my own business.", "Primeiro, bati, e ele me disse de forma grosseira para cuidar da minha vida."], ["Seriously? And then what did you say to him?", "Sério? E depois, o que você disse a ele?"], ["Then I said that I didn't want to confront him, but the music was too loud.", "Depois eu disse que não queria confrontá-lo, mas a música estava alta demais."], ["After that, did anyone else get involved? Maybe the building manager?", "Depois disso, mais alguém se envolveu? Talvez o síndico?"], ["No. He just said that he was sorry for the noise, and it didn't occur again.", "Não. Ele só disse que sentia muito pelo barulho, e não aconteceu de novo."], ["Despite the bad start, you resolved it. That's great news.", "Apesar do mau começo, você resolveu. Que ótima notícia."], ["Exactly. Nevertheless, I'll keep my earplugs, just in case.", "Exatamente. Mesmo assim, vou guardar meus protetores de ouvido, por precaução."]], ["/r/ inicial em rudely e resolve", "Em rudely e resolve, o r inicial é suave e vem de dentro da boca, sem vibrar. Diga RUD-li (com u longo, 'rúud') e ri-ZÓLV.", ["rudely", "resolve"]], ["Elena said that she ___ to confront him.", "didn't want", "doesn't want", "A Elena disse que não queria confrontá-lo.", "No relato, o presente doesn't want vira didn't want."], [["She said that she didn't want to confront him, but it was late.", "Ela disse que não queria confrontá-lo, mas era tarde."], ["Then I said that I didn't want to confront him, but the music was too loud.", "Depois eu disse que não queria confrontá-lo, mas a música estava alta demais."]], [{"t": "c", "q": "First, I knocked. ___, he answered.", "o": ["Then", "Ago", "Last"], "pt": "Primeiro, bati. Depois, ele atendeu.", "why": "Then marca o passo seguinte na ordem da história."}, {"t": "l", "say": "She said that he answered rudely.", "o": ["She said that he answered rudely.", "She says that he answered rude.", "She said that he answers rudely."], "why": "Said that + passado, e rudely é o advérbio."}, {"t": "b", "pt": "Primeiro, bati na porta dele.", "w": ["First", "I", "knocked", "on", "his", "door"]}, {"t": "b", "pt": "Depois disso ele disse que sentia muito.", "w": ["After", "that", "he", "said", "that", "he", "was", "sorry"]}]];
