englishB1Plans[47]={"title": "A reunião da prefeitura sobre a ciclovia", "file": "", "grammar": "Reported speech com present perfect e modais", "goal": "Relate falas com will, can, must e present perfect: would, could, had to e hadn't.", "words": [["oppose", "ser contra, opor-se"], ["significant", "significativo"], ["determine", "decidir, determinar"], ["emphasize", "enfatizar"], ["reveal", "revelar"], ["wise", "sábio, sensato"], ["surely", "com certeza"], ["flow", "fluxo"]]};
englishB1Content[47]=[[["Last night, the city council discussed a new bike lane on Main Street.", "Ontem à noite, a câmara discutiu uma nova ciclovia na Main Street."], ["Mayor Lopes said that the lane would improve the flow of traffic.", "A prefeita Lopes disse que a ciclovia melhoraria o fluxo do trânsito."], ["Mr. Hall said that many shop owners opposed it and could lose customers.", "O Sr. Hall disse que muitos lojistas eram contra e poderiam perder clientes."], ["The mayor said that the city hadn't revealed the final cost yet.", "A prefeita disse que a cidade ainda não tinha revelado o custo final."], ["She emphasized that a significant number of residents supported the idea.", "Ela enfatizou que um número significativo de moradores apoiava a ideia."], ["In the end, the council said that it would determine a final plan next month.", "No fim, a câmara disse que decidiria um plano final no mês que vem."]], [["Did you watch the council meeting last night? They talked about the bike lane.", "Você assistiu à reunião da câmara ontem à noite? Falaram da ciclovia."], ["I did. The mayor said that it would surely improve the traffic flow.", "Assisti. A prefeita disse que com certeza melhoraria o fluxo do trânsito."], ["Maybe it's a wise plan, but Mr. Hall said that the shop owners opposed it.", "Talvez seja um plano sensato, mas o Sr. Hall disse que os lojistas eram contra."], ["Right. He emphasized that it could hurt their business in winter.", "Isso. Ele enfatizou que poderia prejudicar o negócio deles no inverno."], ["What about the cost? Has the city told people how much it will cost?", "E o custo? A cidade já disse às pessoas quanto vai custar?"], ["The mayor said that they hadn't revealed it yet, but a report would come out in May.", "A prefeita disse que ainda não tinham revelado, mas um relatório sairia em maio."], ["Interesting. So the council said that it would determine the plan next month?", "Interessante. Então a câmara disse que decidiria o plano no mês que vem?"], ["Exactly. She said that they would vote on the fifteenth, so we can still send comments.", "Exato. Ela disse que votariam no dia quinze, então ainda podemos mandar comentários."]], ["/z/ final em oppose e emphasize", "Em oppose e emphasize, o s final soa /z/, como o 'z' de zebra. Sinta a garganta vibrar: o-PÔUZ e ÉM-fa-saiz.", ["oppose", "emphasize"]], ["The mayor said that the city ___ revealed the cost yet.", "hadn't", "hasn't", "A prefeita disse que a cidade ainda não tinha revelado o custo.", "Present perfect (hasn't) recua para had/hadn't no relato."], [["The mayor said that the city hadn't revealed the final cost yet.", "A prefeita disse que a cidade ainda não tinha revelado o custo final."], ["I did. The mayor said that it would surely improve the traffic flow.", "Assisti. A prefeita disse que com certeza melhoraria o fluxo do trânsito."]], [{"t": "c", "q": "She said that the lane ___ help traffic.", "o": ["would", "will", "can"], "pt": "Ela disse que a ciclovia ajudaria o trânsito.", "why": "Will vira would em relato no passado."}, {"t": "l", "say": "Mr. Hall said that shop owners could lose customers.", "o": ["Mr. Hall said that shop owners could lose customers.", "Mr. Hall said that shop owners can lose customers.", "Mr. Hall said that shop owners could to lose customers."], "why": "Can vira could no relato, e could não leva to."}, {"t": "b", "pt": "Ela disse que votariam na sexta.", "w": ["She", "said", "they", "would", "vote", "on", "Friday"]}, {"t": "b", "pt": "Ele disse que a cidade não tinha revelado o custo.", "w": ["He", "said", "the", "city", "hadn't", "revealed", "the", "cost"]}]];
