englishB1Plans[48]={"title": "O boato sobre o mercado da esquina", "file": "", "grammar": "Corrigir um boato: what they really said", "goal": "Corrija um boato dizendo o que a pessoa realmente disse: He said that… / That's not what he said.", "words": [["ridiculous", "ridículo"], ["skeptical", "cético"], ["shocked", "chocado"], ["notice", "reparar, notar"], ["generally", "em geral"], ["expose", "expor, revelar"], ["insight", "percepção, ideia nova"], ["dull", "sem graça, chato"]]};
englishB1Content[48]=[[["Yesterday, someone at school said that the corner market was closing for good.", "Ontem, alguém na escola disse que o mercado da esquina ia fechar de vez."], ["Everyone was shocked, and a few people said it was ridiculous.", "Todos ficaram chocados, e algumas pessoas disseram que era ridículo."], ["Mia was skeptical, so she asked the owner what he really said.", "A Mia ficou cética, então perguntou ao dono o que ele realmente disse."], ["He explained that he only said the store would close early on Sundays.", "Ele explicou que só tinha dito que a loja fecharia mais cedo aos domingos."], ["Generally, people notice only the scary part of a story.", "Em geral, as pessoas notam só a parte assustadora de uma história."], ["The owner posted a sign to expose the mistake, and the rumor died.", "O dono colocou um aviso para expor o erro, e o boato morreu."]], [["Did you hear that the corner market is closing for good?", "Você ouviu que o mercado da esquina vai fechar de vez?"], ["That sounds ridiculous. Who told you that, Omar?", "Isso parece ridículo. Quem te contou isso, Omar?"], ["A girl at school said that her mother heard it from the owner.", "Uma menina da escola disse que a mãe dela ouviu isso do dono."], ["I'm skeptical. Let me ask him what he really said.", "Estou cética. Deixa eu perguntar a ele o que ele realmente disse."], ["Good idea. I was shocked when I read the message in the group chat.", "Boa ideia. Fiquei chocado quando li a mensagem no grupo."], ["He said that the store would only close early on Sundays. That's all.", "Ele disse que a loja só fecharia mais cedo aos domingos. Só isso."], ["So the real story is dull. Did you notice how fast it spread?", "Então a história real é sem graça. Você reparou como se espalhou rápido?"], ["Yes, and it gave me some insight about rumors. I'll post the right information now.", "Sim, e me deu uma ideia nova sobre boatos. Vou postar a informação certa agora."]], ["/sk/ em skeptical e school", "Em skeptical e school, o s vem antes do k sem vogal no meio: SKÉP-ti-kal e SKUUL. Não diga 'eskool'; comece direto no sk.", ["skeptical", "school"]], ["Omar said that the store ___ closing for good, but that was wrong.", "was", "is", "O Omar disse que a loja ia fechar de vez, mas estava errado.", "No relato no passado, is vira was."], [["Mia was skeptical, so she asked the owner what he really said.", "A Mia ficou cética, então perguntou ao dono o que ele realmente disse."], ["He said that the store would only close early on Sundays. That's all.", "Ele disse que a loja só fecharia mais cedo aos domingos. Só isso."]], [{"t": "c", "q": "He said that the store ___ close early.", "o": ["would", "will", "can't"], "pt": "Ele disse que a loja fecharia mais cedo.", "why": "Will vira would no relato."}, {"t": "l", "say": "She asked what he really said.", "o": ["She asked what he really said.", "She asked what did he really say.", "She asked what he really says."], "why": "Na pergunta relatada, a ordem é normal e o verbo vai ao passado."}, {"t": "b", "pt": "Ele disse que a loja fecharia mais cedo.", "w": ["He", "said", "that", "the", "store", "would", "close", "early"]}, {"t": "b", "pt": "Não foi isso que ele realmente disse.", "w": ["That's", "not", "what", "he", "really", "said"]}]];
