englishB1Plans[49]={"title": "Segredos na copa da empresa", "file": "", "grammar": "Revisão: fofoca no escritório (mini-história)", "goal": "Revise o discurso indireto contando uma fofoca de escritório e corrigindo o que realmente foi dito.", "words": [["secretly", "em segredo"], ["jealous", "com ciúmes, invejoso"], ["nod", "acenar com a cabeça"], ["nosy", "enxerido"], ["keep a secret", "guardar segredo"], ["behind my back", "pelas minhas costas"], ["go around", "circular, espalhar-se"], ["chuckle", "dar risada baixinho"], ["stare", "encarar"], ["loyal", "leal"]]};
englishB1Content[49]=[[["Everyone in the office was secretly talking about Dana's new job in Chicago.", "Todo mundo no escritório falava em segredo sobre o novo emprego da Dana em Chicago."], ["Kim nodded and told Ben that she knew it too.", "A Kim acenou com a cabeça e disse ao Ben que também sabia."], ["A nosy intern told everyone that the boss would give Dana a huge raise.", "Um estagiário enxerido disse a todos que a chefe daria um grande aumento à Dana."], ["Dana stared at them and said that she didn't like gossip.", "A Dana os encarou e disse que não gostava de fofoca."], ["By noon, the news would go around the whole building.", "Ao meio-dia, a notícia circularia pelo prédio inteiro."], ["The boss chuckled and said that the real news was a team party.", "A chefe deu uma risada e disse que a notícia de verdade era uma festa da equipe."]], [["Did you hear the news? The intern told everyone that Dana was leaving.", "Você ouviu a novidade? O estagiário disse a todos que a Dana ia embora."], ["I did. But Dana said that she was loyal to this company, so I doubt it.", "Ouvi. Mas a Dana disse que era leal a esta empresa, então duvido."], ["Maybe she wants to keep a secret until Friday. Some people are jealous of her.", "Talvez ela queira guardar segredo até sexta. Algumas pessoas têm inveja dela."], ["Dana just told me, \"Please don't talk behind my back.\" She looked really upset.", "A Dana acabou de me dizer: \"Por favor, não falem de mim pelas costas.\" Ela estava muito chateada."], ["I feel bad. I laughed with the others, and I even nodded when they asked me.", "Me sinto mal. Eu ri com os outros e até concordei com a cabeça quando perguntaram."], ["We can fix it. Let's tell them that the boss said it was only a party.", "Podemos consertar. Vamos dizer a eles que a chefe disse que era só uma festa."], ["Good idea. And I'll ask Dana if she'd like to have lunch with us.", "Boa ideia. E vou perguntar à Dana se ela quer almoçar com a gente."], ["Deal. We'll go at noon, and I'll make sure nobody stares at her.", "Combinado. Iremos ao meio-dia, e vou garantir que ninguém a encare."]], ["/dʒ/ em jealous e job", "Em jealous e job, o j soa /dʒ/, como 'dj' em 'dji'. Diga DJÉ-las e DJÓB, com a língua tocando o céu da boca no começo.", ["jealous", "job"]], ["Dana said that she ___ like gossip.", "didn't", "doesn't", "A Dana disse que não gostava de fofoca.", "No relato, o presente doesn't recua para didn't."], [["Dana stared at them and said that she didn't like gossip.", "A Dana os encarou e disse que não gostava de fofoca."], ["I did. But Dana said that she was loyal to this company, so I doubt it.", "Ouvi. Mas a Dana disse que era leal a esta empresa, então duvido."]], [{"t": "c", "q": "The intern told everyone that Dana ___ leaving.", "o": ["was", "is", "were"], "pt": "O estagiário disse a todos que a Dana ia embora.", "why": "Told everyone that + passado: Dana was."}, {"t": "l", "say": "Kim told Ben that she knew it too.", "o": ["Kim told Ben that she knew it too.", "Kim said Ben that she knew it too.", "Kim told Ben that she knows it too."], "why": "Told + pessoa + that + passado."}, {"t": "b", "pt": "Ela disse que não gostava de fofoca.", "w": ["She", "said", "that", "she", "didn't", "like", "gossip"]}, {"t": "b", "pt": "Ele disse que Dana era leal à empresa.", "w": ["He", "said", "that", "Dana", "was", "loyal", "to", "the", "company"]}]];
