englishB1MiniStories[49]=["A semana da fofoca na empresa", "On Monday, Ms. Rivera said that the launch would be late because of a defect.~Na segunda, a Sra. Rivera disse que o lançamento atrasaria por causa de um defeito.|Tom told his team at lunch that the new supplier was a ridiculous choice.~O Tom disse à equipe no almoço que o novo fornecedor era uma escolha ridícula.|A nosy intern asked if the boss was angry, and Kim said that she didn't know.~Um estagiário enxerido perguntou se a chefe estava brava, e a Kim disse que não sabia.|By noon, the story went around the office, and it became bigger and bigger.~Ao meio-dia, a história correu pelo escritório e ficou cada vez maior.|Dana was shocked when she heard that people said she was leaving.~A Dana ficou chocada ao ouvir que as pessoas diziam que ela ia embora.|She asked everyone not to talk behind her back, and the room became quiet.~Ela pediu a todos que não falassem dela pelas costas, e a sala ficou em silêncio.|Ms. Rivera advised them to check the facts, and she promised that she would send a report.~A Sra. Rivera os aconselhou a checar os fatos e prometeu que mandaria um relatório.|Ben admitted that he repeated the rumor, and he said that he was sorry.~O Ben admitiu que repetiu o boato e disse que sentia muito.|Kim told everyone to take a break, and they all had coffee together.~A Kim disse a todos para fazerem uma pausa, e todos tomaram café juntos.|On Friday, Ms. Rivera said that the new supplier would arrive on time, and everyone cheered.~Na sexta, a Sra. Rivera disse que o novo fornecedor chegaria no prazo, e todos comemoraram."];
englishB1Plans[50]={"title": "O pacote estranho na recepção", "file": "", "grammar": "Must be / can’t be / might be: deduções no presente", "goal": "Faça deduções sobre uma caixa misteriosa usando must be, can’t be e might be.", "words": [["peculiar", "estranho, esquisito"], ["belong to", "pertencer a"], ["sender", "remetente"], ["suspect", "suspeitar"], ["whoever", "quem quer que"], ["vague", "vago, impreciso"], ["unlikely", "improvável"], ["ordinary", "comum, normal"], ["out of the ordinary", "fora do comum"]]};
englishB1Content[50]=[[["This morning, a peculiar box was sitting on the reception desk at Rosa’s office.", "Hoje de manhã, uma caixa estranha estava na mesa da recepção do escritório da Rosa."], ["It had no return address, and the sender’s name was too vague to read.", "Não tinha endereço de retorno, e o nome do remetente estava vago demais para ler."], ["Rosa said, “It must be for the accounting team, because they order a lot of boxes.”", "Rosa disse: “Deve ser para o pessoal da contabilidade, porque eles pedem muitas caixas.”"], ["Ben looked closely and said, “It can’t be for accounting. The name on it is Kim.”", "Ben olhou de perto e disse: “Não pode ser da contabilidade. O nome nela é Kim.”"], ["Kim is on vacation, so it might be a gift from a friend.", "A Kim está de férias, então pode ser um presente de um amigo."], ["On Monday, Kim opened it, and it was just an ordinary book from her sister.", "Na segunda, a Kim abriu, e era só um livro comum da irmã dela."]], [["Look at this box on the desk. Does it belong to anyone on our floor?", "Olhe esta caixa na mesa. Ela é de alguém do nosso andar?"], ["I don’t think so. The sender wrote a vague note, so it might be from a client.", "Acho que não. O remetente escreveu um bilhete vago, então pode ser de um cliente."], ["A client? That’s unlikely. Clients usually send emails, and this box looks really old.", "Um cliente? É improvável. Clientes costumam mandar e-mails, e esta caixa parece bem velha."], ["True. It can’t be anything dangerous, though. Nothing here is out of the ordinary, except the weird tape.", "Verdade. Mas não pode ser nada perigoso. Nada aqui é fora do comum, exceto a fita esquisita."], ["Well, I suspect it’s a gift for Kim. She’s on vacation until Monday, isn’t she?", "Bom, suspeito que seja um presente para a Kim. Ela está de férias até segunda, não é?"], ["Yes, until Monday. So whoever sent it doesn’t know she’s away. That must be it.", "Sim, até segunda. Então quem quer que tenha mandado não sabe que ela viajou. Deve ser isso."], ["Right. It’s an ordinary box, so let’s leave it in her office.", "Certo. É uma caixa comum, então vamos deixá-la na sala dela."], ["Good idea. I’ll put a note on it, and we can check with her on Monday.", "Boa ideia. Vou colocar um bilhete nela, e podemos confirmar com ela na segunda."]], ["/ʌ/ em must e unlikely", "O /ʌ/ de must e unlikely é curto e relaxado, parecido com o 'â' de 'cama'. Não abra a boca como em 'a' nem arredonde como em 'ó'.", ["must", "unlikely"]], ["The name on the box is Kim’s, so it ___ be hers.", "must", "can’t", "O nome na caixa é da Kim, então deve ser dela.", "Quando temos quase certeza de que algo é verdade, usamos must be; can’t be diz o contrário."], [["It can’t be anything dangerous, though.", "Mas não pode ser nada perigoso."], ["That must be it.", "Deve ser isso."]], [{"t": "c", "q": "Tom is at work, so he ___ be at the gym right now.", "o": ["can’t", "must", "might"], "pt": "O Tom está no trabalho, então não pode estar na academia agora.", "why": "Se ele está no trabalho, é impossível estar na academia: usamos can’t be."}, {"t": "l", "say": "It might be a gift from a friend.", "o": ["It might be a gift from a friend.", "It must be a gift from a friend.", "It can’t be a gift from a friend."], "why": "Might be indica só uma possibilidade; must be indicaria quase certeza e can’t be, impossibilidade."}, {"t": "b", "pt": "Isso deve ser um erro", "w": ["That", "must", "be", "a", "mistake"]}, {"t": "b", "pt": "Pode ser da minha irmã", "w": ["It", "might", "be", "from", "my", "sister"]}]];
