englishB1Plans[51]={"title": "Quem invadiu a loja durante a noite", "file": "", "grammar": "Must have / can’t have / might have + particípio: deduções no passado", "goal": "Deduza o que aconteceu ontem usando must have, can’t have e might have.", "words": [["burglar", "ladrão (que invade)"], ["break in", "arrombar, invadir"], ["damage", "dano, estrago"], ["incident", "incidente, ocorrência"], ["investigation", "investigação"], ["careless", "descuidado"], ["evident", "evidente"], ["debris", "entulho, cacos"], ["hasty", "apressado"]]};
englishB1Content[51]=[[["On Tuesday morning, Mia found broken glass and debris all over the shop floor.", "Na terça de manhã, a Mia encontrou vidro quebrado e cacos pelo chão da loja."], ["The back window was open, and the burglar had to break in there.", "A janela dos fundos estava aberta, e o ladrão teve que arrombar por ali."], ["He can’t have taken much, because the cash register was still locked.", "Ele não pode ter levado muito, porque o caixa ainda estava trancado."], ["Mia said, “He might have been in a hurry, and the damage is small.”", "Mia disse: “Ele pode ter estado com pressa, e o estrago é pequeno.”"], ["The officer said, “This incident looks hasty, so the investigation should be quick.”", "O policial disse: “Esta ocorrência parece apressada, então a investigação deve ser rápida.”"], ["Mia felt better, but she will fix the lock and never be careless again.", "A Mia se sentiu melhor, mas vai consertar a fechadura e nunca mais ser descuidada."]], [["Good morning, Ms. Costa. Tell me what you saw when you arrived today.", "Bom dia, Sra. Costa. Conte o que a senhora viu quando chegou hoje."], ["The back window was open. It’s evident that someone came in during the night.", "A janela dos fundos estava aberta. É evidente que alguém entrou durante a noite."], ["Do you know how they got in? The front lock looks fine to me.", "A senhora sabe como entraram? A fechadura da frente parece boa para mim."], ["They must have climbed through the window. Look, there are muddy footprints under it.", "Devem ter subido pela janela. Olhe, há pegadas de lama embaixo dela."], ["Good catch. They can’t have stayed long, because nothing important is missing.", "Boa observação. Não podem ter ficado muito tempo, porque nada importante sumiu."], ["They might have heard a noise and run away. May I clean up now?", "Podem ter ouvido um barulho e fugido. Posso limpar agora?"], ["Not yet, please. Don’t touch anything until I finish, and I’ll call you this afternoon.", "Ainda não, por favor. Não toque em nada até eu terminar, e ligo para a senhora à tarde."], ["Okay, I understand. I’ll wait outside, and I’ll call my husband about a new lock.", "Está bem, entendi. Vou esperar lá fora e ligar para meu marido sobre uma fechadura nova."]], ["/ɜr/ em burglar e hurry", "O /ɜr/ de burglar e hurry tem o 'r' americano: a língua sobe e se curva para trás, sem tocar o céu da boca. Não pronuncie 'bur-gu-lar' separado.", ["burglar", "hurry"]], ["The door is locked from inside, so the burglar ___ have left through it.", "can’t", "must", "A porta está trancada por dentro, então o ladrão não pode ter saído por ela.", "Para dizer que algo no passado era impossível, usamos can’t have + particípio."], [["They must have climbed through the window.", "Devem ter subido pela janela."], ["He can’t have taken much, because the cash register was still locked.", "Ele não pode ter levado muito, porque o caixa ainda estava trancado."]], [{"t": "c", "q": "The street is wet, so it ___ have rained last night.", "o": ["must", "can’t", "might not"], "pt": "A rua está molhada, então deve ter chovido ontem à noite.", "why": "Há uma prova clara (rua molhada), então usamos must have + particípio."}, {"t": "l", "say": "They might have heard a noise.", "o": ["They might have heard a noise.", "They must have heard a noise.", "They can’t have heard a noise."], "why": "Might have indica uma possibilidade no passado; must have seria certeza e can’t have, impossibilidade."}, {"t": "b", "pt": "Ele pode ter esquecido a chave", "w": ["He", "might", "have", "forgotten", "the", "key"]}, {"t": "b", "pt": "Ela não pode ter saído", "w": ["She", "can’t", "have", "left"]}]];
