englishB1Plans[52]={"title": "O relatório que não foi salvo", "file": "", "grammar": "Should have + particípio: arrependimento e crítica", "goal": "Lamente um erro do passado ou critique uma decisão usando should have e shouldn’t have.", "words": [["procrastination", "procrastinação"], ["ignore", "ignorar"], ["failure", "falha, fracasso"], ["wasted", "desperdiçado"], ["foolish", "tolo, bobo"], ["deserve", "merecer"], ["tell off", "dar bronca em"], ["attempt", "tentativa"]]};
englishB1Content[52]=[[["Noah worked on his sales report all night, but the computer crashed at six.", "Noah trabalhou no relatório de vendas a noite toda, mas o computador travou às seis."], ["It was a total failure, and four hours of work were wasted.", "Foi uma falha total, e quatro horas de trabalho foram desperdiçadas."], ["He should have saved the file, and he should have listened to the warning.", "Ele devia ter salvo o arquivo, e devia ter ouvido o aviso."], ["“I shouldn’t have ignored that message,” he said. “That was foolish.”", "“Eu não devia ter ignorado aquela mensagem”, disse ele. “Foi bobagem.”"], ["His boss said, “Procrastination caused this. You should have started on Monday.”", "A chefe dele disse: “A procrastinação causou isso. Você devia ter começado na segunda.”"], ["Noah made a second attempt and saved the file every ten minutes.", "Noah fez uma segunda tentativa e salvou o arquivo a cada dez minutos."]], [["You look terrible, Noah. Did you sleep at all last night?", "Você está péssimo, Noah. Você dormiu um pouco ontem à noite?"], ["Not really. My computer crashed, and I lost the whole report. I should have saved it.", "Nem tanto. Meu computador travou e perdi o relatório inteiro. Eu devia ter salvado."], ["Oh no! You shouldn’t have waited until the last night. Why didn’t you start earlier?", "Ai, não! Você não devia ter esperado até a última noite. Por que não começou antes?"], ["I know, I know. I don’t deserve any sympathy. It’s my own fault.", "Eu sei, eu sei. Não mereço nenhuma compaixão. A culpa é minha."], ["Don’t say that. I don’t think she’ll tell off anyone for one computer crash.", "Não diga isso. Não acho que ela vá dar bronca em ninguém por uma falha do computador."], ["Maybe not, but she wants the report today. I have only two hours to rewrite it.", "Talvez não, mas ela quer o relatório hoje. Só tenho duas horas para reescrevê-lo."], ["I can help. Send me your notes, and I’ll check the numbers while you write.", "Posso ajudar. Mande suas anotações, e eu confiro os números enquanto você escreve."], ["Thank you, Lia. You’re a lifesaver! I’ll send them right now.", "Obrigado, Lia. Você me salvou! Vou mandar agora mesmo."]], ["/ʊ/ em should e shouldn’t", "Em should e shouldn’t, o 'l' é mudo e o /ʊ/ é curto, como o 'u' de 'bula' dito rápido. Não diga 'shóu-ld'.", ["should", "shouldn’t"]], ["I ___ have ignored the warning, and now my file is gone.", "shouldn’t", "should", "Eu não devia ter ignorado o aviso, e agora meu arquivo sumiu.", "Shouldn’t have + particípio critica algo que a pessoa fez e que foi um erro."], [["I should have saved it.", "Eu devia ter salvado."], ["You shouldn’t have waited until the last night.", "Você não devia ter esperado até a última noite."]], [{"t": "c", "q": "You ___ have driven so fast. The road was wet.", "o": ["shouldn’t", "should", "couldn’t"], "pt": "Você não devia ter dirigido tão rápido. A pista estava molhada.", "why": "É uma crítica a algo que foi feito, então usamos shouldn’t have + particípio."}, {"t": "l", "say": "I should have called her yesterday.", "o": ["I should have called her yesterday.", "I should call her yesterday.", "I should had called her yesterday."], "why": "O certo é should have + particípio (called). Should had não existe."}, {"t": "b", "pt": "Eu devia ter começado mais cedo", "w": ["I", "should", "have", "started", "earlier"]}, {"t": "b", "pt": "Você não devia ter ignorado o aviso", "w": ["You", "shouldn’t", "have", "ignored", "the", "warning"]}]];
