englishB1Plans[53]={"title": "A prateleira que caiu no supermercado", "file": "", "grammar": "Could have + particípio: possibilidades que não aconteceram", "goal": "Conte um susto dizendo o que poderia ter acontecido com could have.", "words": [["collapse", "desabar, cair"], ["narrowly", "por pouco"], ["close call", "escapada por pouco"], ["severe", "grave, severo"], ["fortunate", "sortudo, com sorte"], ["scare", "susto"], ["avoid", "evitar"], ["survive", "resistir, sobreviver"]]};
englishB1Content[53]=[[["Yesterday, a heavy shelf started to collapse in the supermarket, right behind Priya.", "Ontem, uma prateleira pesada começou a desabar no supermercado, bem atrás da Priya."], ["She narrowly avoided it by stepping back to answer her phone.", "Ela escapou por pouco, dando um passo para trás para atender o telefone."], ["It could have hit her head, and the injury could have been severe.", "Poderia ter batido na cabeça dela, e o ferimento poderia ter sido grave."], ["The manager said, “You’re fortunate, ma’am. This could have been much worse.”", "O gerente disse: “A senhora teve sorte. Poderia ter sido bem pior.”"], ["Priya said, “That was a close call. I could have ended up in the hospital.”", "Priya disse: “Foi por pouco. Eu poderia ter ido parar no hospital.”"], ["A cheap shelf like that can’t survive a heavy load, so the store closed early.", "Uma prateleira barata assim não resiste a muito peso, então a loja fechou mais cedo."]], [["Priya, are you okay? The manager called me, and he sounded really worried.", "Priya, você está bem? O gerente me ligou e parecia muito preocupado."], ["I’m fine, Tom. A shelf collapsed at the supermarket, and it missed me by a few inches.", "Estou bem, Tom. Uma prateleira desabou no supermercado e passou a poucos centímetros de mim."], ["What? That sounds severe! You could have been badly hurt. Where exactly were you standing?", "O quê? Isso parece grave! Você poderia ter se machucado feio. Onde exatamente você estava?"], ["Next to the cereal. I stepped back to answer your call, so you saved me, actually.", "Do lado dos cereais. Dei um passo para trás para atender sua ligação, então você me salvou, na verdade."], ["Wow, what a close call. The scare must have been terrible.", "Nossa, que escapada por pouco. O susto deve ter sido terrível."], ["It was. My hands are still shaking. I could have lost my phone, too, but I held it tight.", "Foi. Minhas mãos ainda tremem. Eu poderia ter perdido o celular também, mas o segurei firme."], ["Let’s go to dinner tonight. You deserve something nice after a day like this.", "Vamos jantar hoje à noite. Você merece algo bom depois de um dia assim."], ["That’s a great idea. Pick me up at seven, and I’ll avoid that supermarket for a week!", "Ótima ideia. Me busque às sete, e eu vou evitar esse supermercado por uma semana!"]], ["/k/ em could e close", "O /k/ de could e close é aspirado: solte um pequeno sopro de ar depois dele. Em could, o 'l' é mudo e a palavra soa como 'kud'.", ["could", "close"]], ["The ball hit the wall. It ___ have broken the window.", "could", "can", "A bola bateu na parede. Poderia ter quebrado a janela.", "Could have + particípio fala de algo que era possível no passado, mas não aconteceu."], [["You could have been badly hurt.", "Você poderia ter se machucado feio."], ["This could have been much worse.", "Poderia ter sido bem pior."]], [{"t": "c", "q": "The bus almost hit us. We ___ have been in an accident.", "o": ["could", "can", "would"], "pt": "O ônibus quase nos atingiu. Poderíamos ter sofrido um acidente.", "why": "Algo possível que não aconteceu no passado usa could have + particípio."}, {"t": "l", "say": "He narrowly avoided the accident.", "o": ["He narrowly avoided the accident.", "He narrowly avoid the accident.", "He narrow avoided the accident."], "why": "Narrowly é o advérbio e o verbo vai no passado: avoided."}, {"t": "b", "pt": "Eu poderia ter perdido o voo", "w": ["I", "could", "have", "missed", "the", "flight"]}, {"t": "b", "pt": "Foi um susto e tanto", "w": ["That", "was", "a", "real", "scare"]}]];
