englishB1Plans[54]={"title": "Comida demais para a festa do escritório", "file": "", "grammar": "Needn’t have e didn’t need to", "goal": "Diga que algo foi desnecessário usando needn’t have e didn’t need to.", "words": [["refreshments", "comes e bebes, lanche"], ["fuss", "confusão, estardalhaço"], ["excess", "excesso"], ["stressed", "estressado"], ["grab", "pegar rápido"], ["wrapping", "embalagem"], ["overdo", "exagerar"], ["unnecessary", "desnecessário"], ["overreact", "reagir com exagero"]]};
englishB1Content[54]=[[["Elena bought refreshments for forty people, but only fifteen came to the office party.", "A Elena comprou comes e bebes para quarenta pessoas, mas só quinze vieram à festa do escritório."], ["She needn’t have bought so much, and the excess filled the whole kitchen.", "Ela não precisava ter comprado tanto, e o excesso encheu a cozinha inteira."], ["Her coworker Sam said, “You didn’t need to worry. People bring snacks, too.”", "O colega dela, Sam, disse: “Você não precisava se preocupar. As pessoas trazem lanches também.”"], ["Elena felt stressed, and she didn’t want to overreact, so she just laughed.", "A Elena ficou estressada e não queria reagir com exagero, então só riu."], ["They grabbed a few sandwiches, and they gave the rest to the night guard.", "Eles pegaram alguns sanduíches e deram o resto ao guarda noturno."], ["On Monday, Elena said, “Next year, I won’t overdo it. I’ll order less.”", "Na segunda, a Elena disse: “No ano que vem, não vou exagerar. Vou pedir menos.”"]], [["Elena, why are there so many boxes in the kitchen? Did you buy lunch for the whole building?", "Elena, por que há tantas caixas na cozinha? Você comprou almoço para o prédio inteiro?"], ["Almost! I ordered refreshments for forty people, but only fifteen came. I’m so stressed.", "Quase! Pedi comes e bebes para quarenta pessoas, mas só quinze vieram. Estou muito estressada."], ["You needn’t have ordered so much. Everyone brought something, and the wrapping alone is a mess.", "Você não precisava ter pedido tanto. Todo mundo trouxe alguma coisa, e só a embalagem já é uma bagunça."], ["I know. It was unnecessary, but I didn’t want to run out of food. Do you want a sandwich?", "Eu sei. Foi desnecessário, mas não queria ficar sem comida. Você quer um sanduíche?"], ["Sure, I’ll grab two. I didn’t need to bring cookies, either. Look at all this!", "Claro, vou pegar dois. Eu também não precisava ter trazido biscoitos. Olhe só tudo isso!"], ["Don’t make a big fuss about it. Next time, I’ll ask people how many are coming.", "Não faça tanto estardalhaço. Da próxima vez, vou perguntar quantas pessoas vêm."], ["Good plan. We can take the excess to the shelter downtown after work, if you want.", "Bom plano. Podemos levar o excesso ao abrigo do centro depois do trabalho, se você quiser."], ["That’s perfect! We’ll leave at six, and I’ll call them right now.", "Perfeito! Saímos às seis, e eu ligo para eles agora mesmo."]], ["/f/ em fuss e refreshments", "Para o /f/ de fuss e refreshments, encoste os dentes de cima no lábio de baixo e sopre. Não troque por /h/ nem por /p/.", ["fuss", "refreshments"]], ["You ___ have brought a gift. The party is only for friends.", "needn’t", "mustn’t", "Você não precisava ter trazido um presente. A festa é só para amigos.", "Needn’t have + particípio diz que a ação foi feita sem necessidade; mustn’t have não se usa assim."], [["You needn’t have ordered so much.", "Você não precisava ter pedido tanto."], ["I didn’t need to bring cookies, either.", "Eu também não precisava ter trazido biscoitos."]], [{"t": "c", "q": "She ___ have cooked so much. Nobody was hungry.", "o": ["needn’t", "mustn’t", "can’t"], "pt": "Ela não precisava ter cozinhado tanto. Ninguém estava com fome.", "why": "Para uma ação feita sem necessidade, usamos needn’t have + particípio."}, {"t": "l", "say": "We didn’t need to wait in line.", "o": ["We didn’t need to wait in line.", "We didn’t need wait in line.", "We don’t needed to wait in line."], "why": "Didn’t need to é seguido do verbo no infinitivo: wait."}, {"t": "b", "pt": "Você não precisava ter vindo", "w": ["You", "needn’t", "have", "come"]}, {"t": "b", "pt": "Eu não precisava me preocupar", "w": ["I", "didn’t", "need", "to", "worry"]}]];
