englishB1Plans[55]={"title": "Quem vai ganhar o campeonato de boliche", "file": "", "grammar": "Graus de certeza: definitely, probably, perhaps, I doubt", "goal": "Fale do futuro com graus de certeza usando definitely, probably, perhaps e I doubt.", "words": [["probability", "probabilidade"], ["certainty", "certeza"], ["estimate", "estimar, calcular"], ["supposedly", "supostamente"], ["hopefully", "com sorte, tomara"], ["no doubt", "sem dúvida"], ["likely", "provável"], ["chances", "chances"], ["predict", "prever"], ["odds", "probabilidades, chances"]]};
englishB1Content[55]=[[["Every year, Omar’s company has a bowling championship, and everyone tries to predict the winner.", "Todo ano, a empresa do Omar faz um campeonato de boliche, e todos tentam prever o vencedor."], ["Priya is definitely the best player, and her odds of winning are very high.", "A Priya é, sem dúvida, a melhor jogadora, e as chances de ela ganhar são altíssimas."], ["Supposedly, Tom practices every night, but I doubt he can beat her.", "Supostamente, o Tom treina toda noite, mas duvido que ele consiga vencê-la."], ["Omar said, “There is no doubt about it. I estimate her chances at ninety percent.”", "Omar disse: “Não há dúvida. Estimo as chances dela em noventa por cento.”"], ["Perhaps Kenji will surprise us, but a win for him is not very likely.", "Talvez o Kenji nos surpreenda, mas uma vitória dele não é muito provável."], ["Hopefully, the final will be close, because certainty makes the game boring.", "Tomara que a final seja equilibrada, porque a certeza deixa o jogo chato."]], [["So, who is going to win the bowling championship on Friday? I need to place my bet.", "Então, quem vai ganhar o campeonato de boliche na sexta? Preciso fazer minha aposta."], ["Priya will definitely win. She hasn’t lost a single game this month, and the odds are on her side.", "A Priya vai ganhar com certeza. Ela não perdeu um jogo este mês, e as chances estão com ela."], ["I doubt it’s that simple. Kenji probably practiced all summer, and he’s a very serious player.", "Duvido que seja tão simples. O Kenji provavelmente treinou o verão todo, e é um jogador muito sério."], ["Perhaps, but Priya has more experience. I’d estimate her probability of winning at about eighty percent.", "Talvez, mas a Priya tem mais experiência. Eu estimaria a probabilidade de ela ganhar em uns oitenta por cento."], ["That’s no doubt a good estimate. Still, nobody can predict a bowling game with certainty.", "Sem dúvida, é uma boa estimativa. Mesmo assim, ninguém prevê um jogo de boliche com certeza."], ["True. Supposedly, Tom is likely to come in third, but he says he’ll surprise us.", "Verdade. Supostamente o Tom deve ficar em terceiro, mas ele diz que vai nos surpreender."], ["Well, hopefully it will be a close game. I’ll bring snacks, and we can watch together.", "Bem, tomara que seja um jogo equilibrado. Levo lanches, e podemos assistir juntos."], ["Great! Bring a lot, because I’ll probably be nervous and hungry. Friday at seven, right?", "Ótimo! Leve bastante, porque provavelmente vou ficar nervoso e com fome. Sexta às sete, certo?"]], ["/p/ aspirado em probably e perhaps", "O /p/ inicial de probably e perhaps é aspirado: solte um sopro de ar. Em probably, muita gente diz só 'probly': as sílabas do meio são rápidas.", ["probably", "perhaps"]], ["Don’t worry about the test. You will ___ pass it.", "definitely", "doubt", "Não se preocupe com a prova. Você vai passar com certeza.", "Definitely vem antes do verbo principal e mostra certeza; doubt é um verbo e não cabe aqui."], [["Priya will definitely win.", "A Priya vai ganhar com certeza."], ["I doubt it’s that simple.", "Duvido que seja tão simples."]], [{"t": "c", "q": "I’m not sure. Maybe it will rain, but ___ it won’t.", "o": ["perhaps", "definitely", "I doubt"], "pt": "Não tenho certeza. Talvez chova, mas talvez não.", "why": "Perhaps indica possibilidade incerta; definitely seria certeza e I doubt exige outra estrutura."}, {"t": "l", "say": "He will probably be late.", "o": ["He will probably be late.", "He will probable be late.", "He probably will late."], "why": "Probably é o advérbio e vem entre will e o verbo be."}, {"t": "b", "pt": "Eu duvido que ele venha", "w": ["I", "doubt", "he", "will", "come"]}, {"t": "b", "pt": "Ela vai com certeza ganhar", "w": ["She", "will", "definitely", "win"]}]];
