englishB1Plans[56]={"title": "A primeira impressão do novo chefe", "file": "", "grammar": "Fazer suposições sobre pessoas e situações", "goal": "Faça suposições sobre pessoas com I assume, I bet, he must be e probably, sem tirar conclusões apressadas.", "words": [["assume", "supor, presumir"], ["assumption", "suposição"], ["first impression", "primeira impressão"], ["jump to conclusions", "tirar conclusões precipitadas"], ["judgment", "julgamento"], ["prejudice", "preconceito"], ["easygoing", "tranquilo, de boa"], ["stereotype", "estereótipo"], ["reserved", "reservado"], ["arrogant", "arrogante"]]};
englishB1Content[56]=[[["When Dr. Lopez arrived, Mia’s first impression was that he looked arrogant and cold.", "Quando o Dr. Lopez chegou, a primeira impressão da Mia foi que ele parecia arrogante e frio."], ["She assumed he was strict, because he never smiled in the elevator.", "Ela supôs que ele era rígido, porque ele nunca sorria no elevador."], ["Her friend Sam said, “Don’t jump to conclusions. He’s probably just shy.”", "O amigo dela, Sam, disse: “Não tire conclusões precipitadas. Ele provavelmente é só tímido.”"], ["Sam added, “I bet he’s reserved with strangers, but easygoing with friends.”", "Sam acrescentou: “Aposto que ele é reservado com estranhos, mas tranquilo com amigos.”"], ["At lunch, Dr. Lopez joked about his bad cooking, and Mia laughed with him.", "No almoço, o Dr. Lopez brincou sobre sua comida ruim, e a Mia riu com ele."], ["Mia admitted that her assumption was wrong and that quick judgment is unfair.", "A Mia admitiu que sua suposição estava errada e que julgar rápido é injusto."]], [["Our new boss walked past me this morning and didn’t even say hello. He must be arrogant.", "Nosso novo chefe passou por mim hoje de manhã e nem disse oi. Ele deve ser arrogante."], ["Come on, Mia. Don’t jump to conclusions. You’ve only seen him once, and you were in the elevator.", "Calma, Mia. Não tire conclusões precipitadas. Você só o viu uma vez, e foi no elevador."], ["True, but my first impression wasn’t great. I assume he thinks he’s better than all of us.", "Verdade, mas minha primeira impressão não foi boa. Suponho que ele ache que é melhor que todos nós."], ["That’s a big assumption. He’s probably just shy, and I bet he’s reserved with new people.", "Isso é uma suposição e tanto. Ele provavelmente é só tímido, e aposto que é reservado com gente nova."], ["Maybe. Some people have a stereotype in their heads about bosses: always serious and strict.", "Talvez. Algumas pessoas têm um estereótipo na cabeça sobre chefes: sempre sérios e rígidos."], ["Exactly, and that kind of prejudice isn’t fair. Wait until you talk to him before any judgment.", "Exato, e esse tipo de preconceito não é justo. Espere falar com ele antes de qualquer julgamento."], ["You’re right. I suppose he might be easygoing after all. Let’s invite him to lunch.", "Você tem razão. Suponho que ele possa ser tranquilo, afinal. Vamos convidá-lo para almoçar."], ["Great idea. I’ll ask him today, and we can all go to the Thai place at noon.", "Ótima ideia. Vou convidá-lo hoje, e podemos ir todos ao tailandês ao meio-dia."]], ["/dʒ/ em judgment e jump", "O /dʒ/ de judgment e jump é como o 'dj' de 'djembê': comece com a língua no céu da boca e solte. Não diga 'ch' nem 'j' francês.", ["judgment", "jump"]], ["He didn’t smile, but he ___ be unfriendly. He may just be shy.", "might not", "must", "Ele não sorriu, mas pode não ser antipático. Talvez seja só tímido.", "Might not be mostra uma possibilidade; must be afirmaria uma conclusão forte demais."], [["He must be arrogant.", "Ele deve ser arrogante."], ["I bet he’s reserved with new people.", "Aposto que ele é reservado com gente nova."]], [{"t": "c", "q": "She never talks in meetings. She ___ be very shy.", "o": ["might", "can’t", "doesn’t"], "pt": "Ela nunca fala nas reuniões. Ela pode ser muito tímida.", "why": "É uma suposição possível, então usamos might be."}, {"t": "l", "say": "I assume he is a doctor.", "o": ["I assume he is a doctor.", "I assume he are a doctor.", "I assumed he be a doctor."], "why": "Depois de I assume, a frase segue normal: he is a doctor."}, {"t": "b", "pt": "Não tire conclusões precipitadas", "w": ["Don’t", "jump", "to", "conclusions"]}, {"t": "b", "pt": "Aposto que ele é muito simpático", "w": ["I", "bet", "he’s", "very", "friendly"]}]];
