englishB1Plans[57]={"title": "Abrindo a padaria apesar dos obstáculos", "file": "", "grammar": "Ability in the past: could, was able to, managed to", "goal": "Conte como alguém conseguiu fazer algo difícil usando was able to e managed to.", "words": [["struggle", "luta, dificuldade"], ["obstacle", "obstáculo"], ["pull off", "conseguir realizar"], ["persistence", "persistência"], ["succeed", "ter sucesso"], ["cope with", "lidar com"], ["manage to", "conseguir (com esforço)"], ["capable", "capaz"], ["tough", "difícil, duro"]]};
englishB1Content[57]=[[["Kenji wanted to open a bakery, but the struggle began on day one.", "Kenji queria abrir uma padaria, mas a luta começou no primeiro dia."], ["The oven broke twice, but he could manage to fix it with a neighbor’s help.", "O forno quebrou duas vezes, mas ele conseguiu consertar com a ajuda de um vizinho."], ["Every obstacle seemed bigger than the last one, and he was often very tired.", "Cada obstáculo parecia maior que o anterior, e ele vivia muito cansado."], ["With persistence, he was able to pull off a perfect opening day.", "Com persistência, ele conseguiu realizar um dia de abertura perfeito."], ["Last month, he couldn’t pay the rent, but this month he succeeded in selling out.", "No mês passado, ele não conseguia pagar o aluguel, mas este mês conseguiu vender tudo."], ["Now he can cope with stress better, and he knows he’s capable of more.", "Agora ele lida melhor com o estresse e sabe que é capaz de mais."]], [["Kenji, your bakery is full today! How did you manage to open in just three weeks?", "Kenji, sua padaria está cheia hoje! Como você conseguiu abrir em apenas três semanas?"], ["Honestly, it was tough. The oven broke twice, and I couldn’t get flour for a whole week.", "Sinceramente, foi difícil. O forno quebrou duas vezes, e não consegui farinha por uma semana inteira."], ["Really? You must have been exhausted. How did you cope with all that stress?", "Sério? Você deve ter ficado exausto. Como lidou com todo esse estresse?"], ["Mostly with coffee! A neighbor was able to fix the oven for free, and that helped a lot.", "Principalmente com café! Um vizinho conseguiu consertar o forno de graça, e isso ajudou muito."], ["Nice. A lot of people give up, but you succeeded. You’re clearly capable of handling a big project.", "Legal. Muita gente desiste, mas você teve sucesso. Você é claramente capaz de cuidar de um grande projeto."], ["Thanks. My persistence was the secret. I couldn’t afford to stop, because I had a loan to pay.", "Obrigado. Minha persistência foi o segredo. Eu não podia parar, porque tinha um empréstimo para pagar."], ["And the opening day? How did you pull off such a perfect party with no money?", "E o dia de abertura? Como você realizou uma festa tão perfeita sem dinheiro?"], ["Friends came, and we sold out by noon. Take a free loaf; you’ve earned it!", "Os amigos vieram, e vendemos tudo ao meio-dia. Leve um pão de graça; você merece!"]], ["/s/ inicial em struggle e succeed", "O /s/ inicial de struggle e succeed é um chiado limpo, sem vogal antes. Não diga 'estruggle': comece direto com 'sss'.", ["struggle", "succeed"]], ["Our car broke down, but we ___ get home before midnight.", "managed to", "could", "Nosso carro quebrou, mas conseguimos chegar em casa antes da meia-noite.", "Para uma conquista específica no passado, usamos managed to ou was able to; could soaria estranho aqui."], [["How did you manage to open in just three weeks?", "Como você conseguiu abrir em apenas três semanas?"], ["A neighbor was able to fix the oven for free", "Um vizinho conseguiu consertar o forno de graça"]], [{"t": "c", "q": "The train was late, but I ___ catch the bus.", "o": ["was able to", "could to", "can"], "pt": "O trem atrasou, mas eu consegui pegar o ônibus.", "why": "Para um fato específico que deu certo no passado, usamos was able to ou managed to."}, {"t": "l", "say": "He couldn’t find his keys.", "o": ["He couldn’t find his keys.", "He can’t find his keys.", "He didn’t could find his keys."], "why": "Couldn’t é o passado negativo de can: He couldn’t find his keys."}, {"t": "b", "pt": "Eles conseguiram abrir a loja", "w": ["They", "were", "able", "to", "open", "the", "shop"]}, {"t": "b", "pt": "Foi uma semana difícil", "w": ["It", "was", "a", "tough", "week"]}]];
