englishB1Plans[58]={"title": "As regras do internato", "file": "", "grammar": "Permissão e proibição no passado: was allowed to / had to", "goal": "Conte o que era permitido e proibido no passado com was allowed to, wasn’t allowed to e had to.", "words": [["boarding school", "internato"], ["detention", "castigo (ficar depois da aula)"], ["permitted", "permitido"], ["sneak out", "sair escondido"], ["restricted", "restrito, limitado"], ["punish", "punir, castigar"], ["disobey", "desobedecer"], ["get away with", "escapar impune de"], ["in trouble", "encrencado"]]};
englishB1Content[58]=[[["When Priya was fourteen, she lived at a boarding school in Ohio.", "Quando a Priya tinha quatorze anos, ela morava num internato em Ohio."], ["Students weren’t allowed to leave the campus, and they had to wear uniforms.", "Os alunos não podiam sair do campus e tinham que usar uniforme."], ["Phones were restricted, and students were permitted to use them only on weekends.", "Os celulares eram restritos, e os alunos podiam usá-los só nos fins de semana."], ["One night, Priya tried to sneak out, but a teacher caught her.", "Uma noite, a Priya tentou sair escondida, mas um professor a pegou."], ["She got detention for two weeks, and she wasn’t allowed to go on the trip.", "Ela ficou de castigo por duas semanas e não pôde ir à viagem."], ["Now Priya laughs about it, but she never wanted to disobey again.", "Hoje a Priya ri disso, mas nunca mais quis desobedecer."]], [["Priya, is it true that you lived at a boarding school? What was it like?", "Priya, é verdade que você morou num internato? Como era?"], ["It was strict. We weren’t allowed to leave the campus, and we had to be in bed by ten.", "Era rígido. Não podíamos sair do campus, e tínhamos que estar na cama às dez."], ["Wow! Were you allowed to have your phone? I couldn’t live without mine.", "Nossa! Vocês podiam ter celular? Eu não viveria sem o meu."], ["Only on weekends. Phones were restricted during the week, and teachers could take them away.", "Só nos fins de semana. Os celulares eram restritos durante a semana, e os professores podiam tirá-los."], ["Did anyone ever disobey the rules? I think I’d try to sneak out every night.", "Alguém desobedecia às regras? Acho que eu tentaria sair escondido toda noite."], ["One night, I did it! I thought I’d get away with it, but a teacher saw me, and I was in trouble.", "Uma noite, eu fiz isso! Achei que escaparia impune, mas um professor me viu, e fiquei encrencada."], ["Seriously? How did they punish you? Did you get detention?", "Sério? Como puniram você? Você ficou de castigo?"], ["Yes, two weeks of detention, and I wasn’t allowed to go on the trip. I never did it again!", "Sim, duas semanas de castigo, e não pude ir à viagem. Nunca mais fiz isso!"]], ["/aʊ/ em allowed e out", "O /aʊ/ de allowed e out é um ditongo: comece em 'a' bem aberto e deslize para 'u'. Em allowed, o acento está na segunda sílaba: a-LOWED.", ["allowed", "out"]], ["When I was a kid, I ___ to ask permission before I went out.", "had", "was allowed", "Quando eu era criança, eu tinha que pedir permissão antes de sair.", "Had to expressa obrigação no passado; was allowed to expressa permissão."], [["We weren’t allowed to leave the campus, and we had to be in bed by ten.", "Não podíamos sair do campus, e tínhamos que estar na cama às dez."], ["Phones were restricted during the week, and teachers could take them away.", "Os celulares eram restritos durante a semana, e os professores podiam tirá-los."]], [{"t": "c", "q": "At my old school, we ___ to wear a uniform.", "o": ["had", "were allowed", "must"], "pt": "Na minha antiga escola, tínhamos que usar uniforme.", "why": "Era uma obrigação no passado, então usamos had to; must não tem passado."}, {"t": "l", "say": "We weren’t allowed to use phones.", "o": ["We weren’t allowed to use phones.", "We weren’t allow to use phones.", "We didn’t allowed to use phones."], "why": "A forma certa é weren’t allowed to + verbo."}, {"t": "b", "pt": "Nós tínhamos que acordar cedo", "w": ["We", "had", "to", "wake", "up", "early"]}, {"t": "b", "pt": "Eu não podia sair à noite", "w": ["I", "wasn’t", "allowed", "to", "go", "out"]}]];
