englishB1Plans[59]={"title": "O notebook que desapareceu da sala de reunião", "file": "", "grammar": "Revisão: deduções e habilidade no passado (um mistério no escritório)", "goal": "Revise deduções no presente e no passado para resolver um mistério no escritório.", "words": [["culprit", "culpado"], ["confess", "confessar"], ["track down", "localizar, rastrear"], ["suspicion", "suspeita"], ["stolen", "roubado"], ["footage", "imagens gravadas"], ["go missing", "desaparecer"], ["take place", "acontecer, ocorrer"], ["pretend", "fingir"]]};
englishB1Content[59]=[[["On Friday, Lia’s laptop seemed to go missing from the meeting room.", "Na sexta, o notebook da Lia pareceu desaparecer da sala de reunião."], ["Security checked the footage, and the screen showed a man in a gray jacket.", "A segurança verificou as imagens, e a tela mostrou um homem de jaqueta cinza."], ["Lia said, “It can’t have been a stranger. The door was locked.”", "Lia disse: “Não pode ter sido um estranho. A porta estava trancada.”"], ["The manager had a suspicion that someone inside the company had taken it.", "O gerente tinha a suspeita de que alguém de dentro da empresa o havia levado."], ["They had to track down the culprit before the client meeting on Monday.", "Eles tinham que localizar o culpado antes da reunião com o cliente na segunda."], ["Noah finally decided to confess: he had borrowed it and pretended to know nothing.", "Noah finalmente decidiu confessar: ele o havia pegado emprestado e fingido não saber de nada."]], [["Mr. Reed, my laptop is gone. I left it in the meeting room, and now it’s stolen.", "Sr. Reed, meu notebook sumiu. Deixei na sala de reunião, e agora foi roubado."], ["Calm down, Lia. It might not be stolen. When did you last see it?", "Calma, Lia. Pode não ter sido roubado. Quando você o viu pela última vez?"], ["At four o’clock. A meeting was going to take place there, so I left it on the table.", "Às quatro horas. Ia acontecer uma reunião lá, então deixei na mesa."], ["Let’s check the footage. Someone must have gone in after you left.", "Vamos ver as imagens. Alguém deve ter entrado depois que você saiu."], ["Look at the screen. That man in the gray jacket can’t be a stranger, because he used a badge.", "Olhe a tela. Aquele homem de jaqueta cinza não pode ser um estranho, porque usou um crachá."], ["You’re right. It must be someone from our team. I have a suspicion, but I can’t say yet.", "Você tem razão. Deve ser alguém da nossa equipe. Tenho uma suspeita, mas ainda não posso dizer."], ["Can we track down the culprit before Monday? The client is coming at nine, and I need that file.", "Podemos localizar o culpado antes de segunda? O cliente chega às nove, e preciso desse arquivo."], ["I think so. Wait, here comes Noah with your laptop. I think he wants to confess.", "Acho que sim. Espere, aí vem o Noah com seu notebook. Acho que ele quer confessar."]], ["/ʌ/ em culprit e suspicion", "O /ʌ/ de culprit e da sílaba 'cul' é curto e relaxado, quase um 'â'. Em suspicion, a primeira sílaba também é fraca: s’SPI-shn.", ["culprit", "suspicion"]], ["The door was locked, so it ___ have been a stranger.", "can’t", "must", "A porta estava trancada, então não pode ter sido um estranho.", "Quando uma possibilidade passada é impossível, usamos can’t have + particípio."], [["Someone must have gone in after you left.", "Alguém deve ter entrado depois que você saiu."], ["It can’t have been a stranger.", "Não pode ter sido um estranho."]], [{"t": "c", "q": "The lights are off, so they ___ be at home.", "o": ["can’t", "must", "should have"], "pt": "As luzes estão apagadas, então eles não podem estar em casa.", "why": "Pela evidência (luzes apagadas), a dedução é negativa: can’t be."}, {"t": "l", "say": "He pretended to be asleep.", "o": ["He pretended to be asleep.", "He pretended be asleep.", "He pretend to be asleep."], "why": "Depois de pretended vem to + verbo: to be asleep."}, {"t": "b", "pt": "Alguém deve ter pegado o notebook", "w": ["Someone", "must", "have", "taken", "the", "laptop"]}, {"t": "b", "pt": "Ele decidiu confessar tudo", "w": ["He", "decided", "to", "confess", "everything"]}]];
englishB1PhotoThemes[59]="map";
englishB1MiniStories[59]=["Uma semana de mistérios", "Last week, strange things happened at Rosa’s office, and everybody had a theory.~Na semana passada, coisas estranhas aconteceram no escritório da Rosa, e todos tinham uma teoria.|On Monday, a peculiar box arrived, and Ben said it might be a gift for Kim.~Na segunda, chegou uma caixa estranha, e o Ben disse que podia ser um presente para a Kim.|On Tuesday, a burglar broke into the shop next door, and Mia said he must have been in a hurry.~Na terça, um ladrão invadiu a loja ao lado, e a Mia disse que ele devia estar com pressa.|Noah lost his report on Wednesday and said he should have saved it earlier.~O Noah perdeu o relatório na quarta e disse que devia tê-lo salvo antes.|A shelf collapsed in the supermarket, and Priya said it could have been much worse.~Uma prateleira desabou no supermercado, e a Priya disse que poderia ter sido bem pior.|Elena ordered too much food, so she needn’t have worried about the party.~A Elena pediu comida demais, então não precisava ter se preocupado com a festa.|Everyone tried to predict the bowling winner, and nobody had any certainty.~Todos tentaram prever o vencedor do boliche, e ninguém tinha certeza.|On Friday, Lia’s laptop went missing, and the manager said the culprit can’t be a stranger.~Na sexta, o notebook da Lia sumiu, e o gerente disse que o culpado não podia ser um estranho.|They managed to track him down, and Noah was able to confess before lunch.~Eles conseguiram localizá-lo, e o Noah pôde confessar antes do almoço.|In the end, nothing was stolen, and the whole office laughed at their wild assumptions.~No fim, nada foi roubado, e o escritório inteiro riu das suposições malucas."];
englishB1Plans[60]={"title": "Conhecendo os vizinhos do prédio novo", "file": "", "grammar": "Orações relativas definidoras: who, which, that, whose", "goal": "Identifique pessoas e coisas com who, which, that e whose, como em ‘the man whose dog barks’.", "words": [["neighbourhood", "bairro, vizinhança"], ["politely", "educadamente"], ["resident", "morador"], ["settle", "se instalar"], ["untidy", "bagunçado"], ["unfriendly", "pouco amigável"], ["unwanted", "indesejado"], ["behave", "se comportar"], ["courtesy", "gentileza, cortesia"]]};
englishB1Content[60]=[[["Omar moved to a neighbourhood that is quiet, but his building has a few problems.", "Omar se mudou para um bairro que é tranquilo, mas o prédio dele tem alguns problemas."], ["The resident who lives upstairs is untidy and leaves boxes in the hall every day.", "A moradora que mora lá em cima é bagunceira e deixa caixas no corredor todos os dias."], ["Omar asked her politely to move the boxes, and she said she was sorry.", "Omar pediu a ela educadamente para tirar as caixas, e ela disse que sentia muito."], ["The man whose dog barks at night seemed unfriendly when they first met.", "O homem cujo cachorro late à noite parecia pouco amigável quando se conheceram."], ["Omar left a note that asked him to behave with a little courtesy after ten.", "Omar deixou um bilhete que pedia a ele que se comportasse com um pouco de gentileza depois das dez."], ["Now the man says hello every morning, and Omar can finally settle in.", "Agora o homem diz bom dia toda manhã, e Omar finalmente pode se acomodar."]], [["Hi, are you the new resident who moved into apartment 4B?", "Oi, você é o novo morador que se mudou para o apartamento 4B?"], ["Yes, I am. I’m still trying to settle in, but the neighbourhood seems really nice.", "Sou sim. Ainda estou tentando me ajeitar, mas o bairro parece muito bom."], ["It is. Most people here are great, but the man next door can be a little unfriendly.", "É. A maioria das pessoas aqui é ótima, mas o homem do lado pode ser meio antipático."], ["Really? Last night I heard a dog barking until two. Is that his dog?", "Sério? Ontem à noite ouvi um cachorro latindo até as duas. É o cachorro dele?"], ["Yes, it’s the dog whose owner works nights, so please speak to him politely.", "É sim, é o cachorro cujo dono trabalha à noite, então fale com ele educadamente."], ["Sure, I’ll leave a note tonight. I just want to stop the unwanted noise after ten o’clock.", "Claro, vou deixar um bilhete hoje. Só quero acabar com o barulho indesejado depois das dez."], ["Good idea. And sorry about the boxes in the hall. I’m a little untidy, and I’m moving things on Sunday.", "Boa ideia. E desculpe pelas caixas no corredor. Sou meio bagunceira e vou arrumar tudo no domingo."], ["No problem, Rosa. Thanks for your courtesy. I’ll talk to him tomorrow morning.", "Sem problema, Rosa. Obrigado pela gentileza. Vou falar com ele amanhã de manhã."]], ["/eɪ/ em neighbourhood e behave", "O som é um ditongo, como o ‘ei’ de ‘lei’. Em neighbourhood o ‘gh’ é mudo: NEI-bor-hud.", ["neighbourhood", "behave"]], ["She’s the resident ___ moved into apartment 4B.", "who", "which", "Ela é a moradora que se mudou para o apartamento 4B.", "Para pessoas use who (ou that); which é para coisas."], [["The resident who lives upstairs is untidy and leaves boxes in the hall every day.", "A moradora que mora lá em cima é bagunceira e deixa caixas no corredor todos os dias."], ["Yes, it’s the dog whose owner works nights, so please speak to him politely.", "É sim, é o cachorro cujo dono trabalha à noite, então fale com ele educadamente."]], [{"t": "c", "q": "I know a woman ___ son plays in the band.", "o": ["whose", "who", "which"], "pt": "Conheço uma mulher cujo filho toca na banda.", "why": "Whose indica posse e vem antes do substantivo (whose son)."}, {"t": "l", "say": "The man who lives next door is unfriendly.", "o": ["The man who lives next door is unfriendly.", "The man which lives next door is unfriendly.", "The man who live next door is unfriendly."], "why": "Who para pessoa, e lives com -s porque o sujeito é singular."}, {"t": "b", "pt": "O vizinho que mora lá em cima é bagunceiro", "w": ["The", "neighbor", "who", "lives", "upstairs", "is", "untidy"]}, {"t": "b", "pt": "Ele pediu educadamente ao novo morador", "w": ["He", "asked", "the", "new", "resident", "politely"]}]];
englishB1PhotoThemes[60]="map";
englishB1Plans[61]={"title": "A primeira reunião com a nova gerente", "file": "", "grammar": "Orações relativas não definidoras com vírgulas", "goal": "Acrescente informação extra entre vírgulas, como em ‘Priya, who is our new manager, …’.", "words": [["management", "gerência, administração"], ["experienced", "experiente"], ["leadership", "liderança"], ["newcomer", "recém-chegado"], ["responsibility", "responsabilidade"], ["enthusiastic", "entusiasmado"], ["reputation", "reputação"], ["specialist", "especialista"], ["take the lead", "assumir a frente"]]};
englishB1Content[61]=[[["Our new manager, Priya, who is very experienced, started on Monday morning.", "Nossa nova gerente, Priya, que é muito experiente, começou na segunda de manhã."], ["She came from the management team in Chicago, which has a great reputation.", "Ela veio da equipe de gerência de Chicago, que tem uma ótima reputação."], ["Priya, who is a specialist in customer service, wants to take the lead on the new project.", "A Priya, que é especialista em atendimento ao cliente, quer assumir a frente do novo projeto."], ["Ken, whose desk is next to hers, was the only newcomer in the room.", "O Ken, cuja mesa fica ao lado da dela, era o único recém-chegado na sala."], ["She said that leadership is not about orders, but about taking responsibility.", "Ela disse que liderança não é dar ordens, e sim assumir responsabilidade."], ["Everyone felt enthusiastic after the meeting, which finished earlier than we expected.", "Todos ficaram entusiasmados depois da reunião, que terminou mais cedo do que esperávamos."]], [["Did you meet Priya, our new manager, at the meeting this morning?", "Você conheceu a Priya, nossa nova gerente, na reunião desta manhã?"], ["Yes, I did. She seems very experienced, and her reputation is great.", "Conheci sim. Ela parece muito experiente, e a reputação dela é ótima."], ["She worked in management at Delta Foods, which is one of the biggest companies in Ohio.", "Ela trabalhou na gerência da Delta Foods, que é uma das maiores empresas de Ohio."], ["Wow. Ken, who sits behind me, told me she’s a specialist in training new staff.", "Nossa. O Ken, que senta atrás de mim, disse que ela é especialista em treinar funcionários novos."], ["That’s good news. I’m a newcomer too, so I want her help with my first project.", "Que boa notícia. Também sou recém-chegada, então quero a ajuda dela no meu primeiro projeto."], ["Me too. She said someone should take the lead on the Monday report next week.", "Eu também. Ela disse que alguém deveria assumir o relatório de segunda-feira na semana que vem."], ["I’d love to do it, but I’m a little afraid of the responsibility.", "Eu adoraria fazer, mas tenho um pouco de medo da responsabilidade."], ["Don’t worry, Lia. You’re enthusiastic, and that’s what good leadership needs.", "Não se preocupe, Lia. Você é entusiasmada, e é disso que uma boa liderança precisa."], ["Thanks, Sam. Okay, I’ll tell her at nine tomorrow that I can do it.", "Obrigada, Sam. Tá bom, amanhã às nove eu digo a ela que posso fazer."], ["Great, and I’ll be there at nine to support you.", "Ótimo, e eu estarei lá às nove para te apoiar."]], ["/dʒ/ em management e manager", "O ‘g’ antes de e/i soa como o ‘j’ de ‘jeans’: /dʒ/. Em manager a força cai na primeira sílaba: MA-ni-jer.", ["management", "manager"]], ["My boss, ___ lives in Denver, is visiting us today.", "who", "which", "Minha chefe, que mora em Denver, está nos visitando hoje.", "Em oração com vírgulas, who se refere a pessoa; that não pode ser usado."], [["Our new manager, Priya, who is very experienced, started on Monday morning.", "Nossa nova gerente, Priya, que é muito experiente, começou na segunda de manhã."], ["She worked in management at Delta Foods, which is one of the biggest companies in Ohio.", "Ela trabalhou na gerência da Delta Foods, que é uma das maiores empresas de Ohio."]], [{"t": "c", "q": "The office, ___ is on the tenth floor, has a great view.", "o": ["which", "who", "whose"], "pt": "O escritório, que fica no décimo andar, tem uma vista ótima.", "why": "Which se refere a coisa; entre vírgulas, that não é usado."}, {"t": "l", "say": "Ken, who sits behind me, is a newcomer.", "o": ["Ken, who sits behind me, is a newcomer.", "Ken, that sits behind me, is a newcomer.", "Ken who sits behind me is a newcomer."], "why": "Informação extra sobre uma pessoa leva vírgulas e who, não that."}, {"t": "b", "pt": "Priya, que é experiente, quer a frente", "w": ["Priya", "who", "is", "experienced", "wants", "the", "lead"]}, {"t": "b", "pt": "A reunião, que acabou cedo, foi ótima", "w": ["The", "meeting", "which", "ended", "early", "was", "great"]}]];
