englishB1Plans[62]={"title": "Fim de semana na praia que deu errado", "file": "", "grammar": "Although, though, even though e however", "goal": "Mostre contraste com although, even though, though e however, como em ‘Although it rained, we went out’.", "words": [["disappointment", "decepção"], ["frustrated", "frustrado"], ["unexpected", "inesperado"], ["memorable", "memorável"], ["disaster", "desastre"], ["temporary", "temporário"], ["unlucky", "azarado"], ["call off", "cancelar"], ["make the best of", "tirar o melhor de"]]};
englishB1Content[62]=[[["Although the forecast said sunny, it rained all day on Saturday morning.", "Embora a previsão dissesse sol, choveu o dia todo no sábado de manhã."], ["The beach closed because of the storm, and Noah called the trip a disaster.", "A praia fechou por causa da tempestade, e o Noah chamou a viagem de desastre."], ["They were frustrated, but the unexpected rain was only a temporary problem.", "Eles estavam frustrados, mas a chuva inesperada era só um problema passageiro."], ["The hotel called off the boat tour, even though they had paid for it already.", "O hotel cancelou o passeio de barco, mesmo eles já tendo pagado por ele."], ["They were unlucky; however, they decided to make the best of the day.", "Eles tiveram azar; porém, decidiram tirar o melhor do dia."], ["They played cards in the lobby, and it became a memorable trip, though not the one they expected.", "Eles jogaram cartas no saguão, e foi uma viagem memorável, embora não a que esperavam."]], [["I know you feel frustrated, Noah, but we can’t change the weather today.", "Sei que você está frustrado, Noah, mas não podemos mudar o tempo hoje."], ["I know. Although I’m trying to stay positive, the disappointment is huge.", "Eu sei. Embora eu esteja tentando ficar positivo, a decepção é enorme."], ["The woman at the front desk offered us a free dinner tonight, though the restaurant is small.", "A moça da recepção nos ofereceu um jantar grátis hoje, embora o restaurante seja pequeno."], ["Really? That’s nice. We drove three hours, and we haven’t seen the ocean yet.", "Sério? Que legal. Dirigimos três horas e ainda não vimos o mar."], ["Even though it’s raining, we can walk to the pier. I brought two umbrellas.", "Mesmo com chuva, podemos ir andando até o píer. Trouxe dois guarda-chuvas."], ["Okay, let’s do that. At least the rain is only temporary, right?", "Tá bom, vamos. Pelo menos a chuva é só passageira, certo?"], ["The forecast says it will stop at four, so we can go after lunch.", "A previsão diz que para às quatro, então podemos ir depois do almoço."], ["Sounds good. Let’s meet in the lobby at four thirty, then.", "Fechado. Então vamos nos encontrar no saguão às quatro e meia."]], ["/ð/ em although e though", "O ‘th’ é /ð/: coloque a língua entre os dentes e use a voz. O ‘gh’ não soa: al-DHÔ, dhô.", ["although", "though"]], ["___ it was cold, we went to the lake.", "Although", "However", "Embora estivesse frio, fomos ao lago.", "Although liga duas orações; however vem em outra frase, antes de vírgula."], [["Although the forecast said sunny, it rained all day on Saturday morning.", "Embora a previsão dissesse sol, choveu o dia todo no sábado de manhã."], ["Even though it’s raining, we can walk to the pier. I brought two umbrellas.", "Mesmo com chuva, podemos ir andando até o píer. Trouxe dois guarda-chuvas."]], [{"t": "c", "q": "I was tired. ___, I finished the report.", "o": ["However", "Although", "Even though"], "pt": "Eu estava cansado. Mesmo assim, terminei o relatório.", "why": "However começa uma nova frase e é seguido de vírgula; although liga duas orações."}, {"t": "l", "say": "Although it rained, we had fun.", "o": ["Although it rained, we had fun.", "Although it rained but we had fun.", "However it rained, we had fun."], "why": "Although já indica contraste, então não se usa but na mesma frase."}, {"t": "b", "pt": "Mesmo estando cansada ela continuou trabalhando", "w": ["Even", "though", "she", "was", "tired", "she", "kept", "working"]}, {"t": "b", "pt": "Eles tiveram azar mas tiraram o melhor", "w": ["They", "were", "unlucky", "but", "made", "the", "best", "of"]}]];
