englishB1ExtraWordExamples[62]={"call off": ["They had to call off the picnic because of the rain.", "Eles tiveram de cancelar o piquenique por causa da chuva."]};
englishB1Plans[63]={"title": "Treinando para a subida da serra de bicicleta", "file": "", "grammar": "Despite / in spite of + substantivo ou -ing", "goal": "Mostre que algo aconteceu apesar de um obstáculo, usando despite e in spite of.", "words": [["challenging", "desafiador"], ["overcome", "superar"], ["motivate", "motivar"], ["workout", "treino, exercício"], ["competitor", "concorrente, adversário"], ["immediately", "imediatamente"], ["keep going", "continuar, não parar"], ["stamina", "resistência física"]]};
englishB1Content[63]=[[["Despite the heat, Elena finished her morning workout on the hill road.", "Apesar do calor, a Elena terminou seu treino matinal na estrada da colina."], ["The climb was challenging, and in spite of her tired legs, she decided to keep going.", "A subida foi desafiadora, e apesar das pernas cansadas, ela decidiu continuar."], ["Another cyclist, a competitor from her club, passed her on the last curve.", "Outro ciclista, um adversário do clube dela, passou por ela na última curva."], ["Despite having little stamina last year, Elena can now ride thirty kilometers.", "Apesar de ter pouca resistência no ano passado, a Elena agora consegue pedalar trinta quilômetros."], ["Training with friends helps to motivate her, in spite of the early hour.", "Treinar com amigos a ajuda a se motivar, apesar do horário cedo."], ["At the top, she felt proud that she could overcome her fear of long climbs.", "No topo, ela sentiu orgulho por superar o medo de subidas longas."]], [["Elena, you look great! How was the climb in spite of the heat?", "Elena, você está ótima! Como foi a subida apesar do calor?"], ["It was tough, but I did it. I never stopped, and my legs are fine now.", "Foi duro, mas consegui. Não parei nunca, e minhas pernas estão bem agora."], ["Really? Last month you couldn’t finish ten kilometers. What changed?", "Sério? No mês passado você não terminava dez quilômetros. O que mudou?"], ["I follow a plan, and my coach helps to motivate me. Training every day builds stamina.", "Sigo um plano, e meu treinador me ajuda a ficar motivada. Treinar todo dia cria resistência."], ["Impressive. I want to join your group, despite being a slow rider.", "Impressionante. Quero entrar no seu grupo, apesar de ser um ciclista lento."], ["Come on Saturday. We start at seven, and someone will help you immediately if you have a problem.", "Venha no sábado. Começamos às sete, e alguém ajuda você na hora se tiver algum problema."], ["Seven? That’s early, but despite the hour, I’m in. Do I need to bring water?", "Sete? É cedo, mas apesar do horário, eu vou. Preciso levar água?"], ["Yes, bring two bottles. See you at the park gate at seven sharp.", "Sim, leve duas garrafas. Te vejo no portão do parque às sete em ponto."]], ["/st/ e /sp/ sem ‘i’ na frente, em stamina e despite", "Não coloque ‘i’ antes de st/sp, como em ‘istamina’. Comece direto com /st/ e /sp/: STA-mi-na, dis-SPAIT.", ["stamina", "despite"]], ["___ the rain, we played soccer.", "Despite", "Although", "Apesar da chuva, jogamos futebol.", "Despite vem antes de substantivo ou -ing; although precisa de sujeito e verbo."], [["Despite the heat, Elena finished her morning workout on the hill road.", "Apesar do calor, a Elena terminou seu treino matinal na estrada da colina."], ["Impressive. I want to join your group, despite being a slow rider.", "Impressionante. Quero entrar no seu grupo, apesar de ser um ciclista lento."]], [{"t": "c", "q": "___ feeling sick, he went to work.", "o": ["In spite of", "Although", "However"], "pt": "Apesar de estar doente, ele foi trabalhar.", "why": "In spite of é seguido de -ing ou substantivo; although pede sujeito e verbo."}, {"t": "l", "say": "Despite the heat, she kept going.", "o": ["Despite the heat, she kept going.", "Despite of the heat, she kept going.", "Despite the heat is, she kept going."], "why": "Despite nunca leva of; já in spite of leva."}, {"t": "b", "pt": "Apesar do calor ela continuou", "w": ["Despite", "the", "heat", "she", "kept", "going"]}, {"t": "b", "pt": "Ela superou o medo apesar do cansaço", "w": ["She", "overcame", "her", "fear", "in", "spite", "of", "being", "tired"]}]];
