englishB1Plans[64]={"title": "Mutirão de limpeza do rio", "file": "", "grammar": "So that, in order to e to + verbo (finalidade)", "goal": "Explique o objetivo de uma ação com to, in order to e so that.", "words": [["environmental", "ambiental"], ["reduction", "redução"], ["participate", "participar"], ["participant", "participante"], ["equipment", "equipamento"], ["ensure", "garantir"], ["organization", "organização"], ["hand out", "distribuir"]]};
englishB1Content[64]=[[["Rosa works for an environmental organization that cleans the river every spring.", "A Rosa trabalha numa organização ambiental que limpa o rio toda primavera."], ["This year she sent emails so that more people could participate.", "Este ano ela mandou e-mails para que mais pessoas pudessem participar."], ["Sam printed flyers in order to hand out information at the market.", "O Sam imprimiu panfletos para distribuir informações na feira."], ["Each participant gets gloves and a bag so that nobody touches dirty things.", "Cada participante recebe luvas e um saco para que ninguém encoste em coisas sujas."], ["The city lent them equipment to carry heavy trash to the trucks.", "A prefeitura emprestou equipamentos para levar o lixo pesado até os caminhões."], ["They also cleaned the banks to ensure a reduction of plastic in the water.", "Eles também limparam as margens para garantir uma redução do plástico na água."]], [["Sam, did you call the city about the trucks and the equipment for Saturday?", "Sam, você ligou para a prefeitura sobre os caminhões e os equipamentos de sábado?"], ["Yes. I called this morning so that they can confirm the date by Friday.", "Sim. Liguei hoje de manhã para que eles confirmem a data até sexta."], ["Great. We need at least forty people, so I’m posting the event online tonight.", "Ótimo. Precisamos de pelo menos quarenta pessoas, então vou postar o evento online hoje à noite."], ["I’m printing flyers right now to give to people at the supermarket tomorrow.", "Estou imprimindo panfletos agora para dar às pessoas no supermercado amanhã."], ["Good. Ask everyone to write their names, and then we’ll know who is coming.", "Bom. Peça a todos que escrevam os nomes, e assim saberemos quem vem."], ["Will do. I also bought twenty extra gloves in order to have enough for everyone.", "Pode deixar. Também comprei vinte luvas extras para ter o suficiente para todos."], ["Perfect. I’ll arrive early and put the tables near the bridge, okay?", "Perfeito. Vou chegar cedo e colocar as mesas perto da ponte, tá?"], ["Yes. So we meet at the bridge at eight on Saturday, and I’ll bring coffee.", "Sim. Então nos encontramos na ponte às oito de sábado, e eu levo café."]], ["/p/ aspirado em participate e participant", "O /p/ inicial leva um sopro de ar. A sílaba forte é a segunda: par-TI-ci-pate, par-TI-ci-pant.", ["participate", "participant"]], ["I went to the store ___ buy bread.", "to", "for", "Fui à loja para comprar pão.", "Para dizer a finalidade antes de um verbo, use to + verbo; for não serve aqui."], [["This year she sent emails so that more people could participate.", "Este ano ela mandou e-mails para que mais pessoas pudessem participar."], ["Sam printed flyers in order to hand out information at the market.", "O Sam imprimiu panfletos para distribuir informações na feira."]], [{"t": "c", "q": "She wrote the date down ___ she wouldn’t forget it.", "o": ["so that", "for", "to"], "pt": "Ela anotou a data para não esquecer.", "why": "So that + sujeito + verbo explica a finalidade; to e for não aceitam sujeito novo."}, {"t": "l", "say": "We cleaned the river to reduce plastic.", "o": ["We cleaned the river to reduce plastic.", "We cleaned the river for reduce plastic.", "We cleaned the river to reduces plastic."], "why": "Depois de to vem o verbo base, sem -s, e nunca for."}, {"t": "b", "pt": "Ele comprou luvas para ajudar no mutirão", "w": ["He", "bought", "gloves", "in", "order", "to", "help", "clean"]}, {"t": "b", "pt": "Ela enviou e-mails para que todos soubessem", "w": ["She", "sent", "emails", "so", "that", "everyone", "would", "know"]}]];
