englishB1Plans[65]={"title": "Ao vivo na praça: uma banda de rua incrível", "file": "", "grammar": "Such… that / so… that: consequência", "goal": "Conte consequências com so… that e such… that, como em ‘It was so loud that we left’.", "words": [["spectacular", "espetacular"], ["impressive", "impressionante"], ["incredible", "incrível"], ["stunning", "deslumbrante"], ["entertainer", "artista, animador"], ["spectator", "espectador"], ["excitement", "empolgação"], ["magnificent", "magnífico"], ["massive", "enorme"]]};
englishB1Content[65]=[[["The street show was so spectacular that hundreds of spectators stopped to watch.", "O show de rua foi tão espetacular que centenas de espectadores pararam para ver."], ["The main entertainer was such a funny man that the whole square laughed.", "O artista principal era um homem tão engraçado que a praça inteira riu."], ["His massive drum set was so loud that the kids covered their ears and giggled.", "A bateria enorme dele era tão alta que as crianças taparam os ouvidos e riram."], ["The lights on the old building were stunning, and people took photos all night.", "As luzes no prédio antigo eram deslumbrantes, e as pessoas tiraram fotos a noite toda."], ["It was such a magnificent night that nobody wanted to go home early.", "Foi uma noite tão magnífica que ninguém queria ir embora cedo."], ["Priya felt so much excitement that she couldn’t sleep afterward.", "A Priya sentiu tanta empolgação que não conseguiu dormir depois."]], [["Priya, that was such an incredible show that I still can’t believe it!", "Priya, aquele show foi tão incrível que ainda não consigo acreditar!"], ["I know! The guitarist was so impressive that I recorded his whole solo.", "Eu sei! O guitarrista foi tão impressionante que gravei o solo inteiro."], ["Did you see the little boy in front of us? He was dancing on his father’s shoulders.", "Você viu o menino na nossa frente? Ele dançava nos ombros do pai."], ["Yes! And his dad was dancing too. I think the whole square forgot about work.", "Vi! E o pai dele também dançava. Acho que a praça inteira esqueceu o trabalho."], ["Is it true that the band is playing again tomorrow night at the theater?", "É verdade que a banda toca de novo amanhã à noite no teatro?"], ["Yes, but the tickets are so expensive that I’m not sure I can go.", "É, mas os ingressos estão tão caros que não sei se posso ir."], ["Let’s check online. Maybe we can find cheaper seats in the back of the theater.", "Vamos olhar online. Talvez a gente ache lugares mais baratos no fundo do teatro."], ["Good idea. If we find two tickets under forty dollars, I’ll buy them tonight.", "Boa ideia. Se acharmos dois ingressos por menos de quarenta dólares, eu compro hoje à noite."]], ["/ʌ/ em such e stunning", "O /ʌ/ é curto, entre ‘a’ e ‘é’ abafado, como em ‘cup’. Não diga ‘sutch’ com u: é SATCH e STA-ning.", ["such", "stunning"]], ["The movie was ___ long that we fell asleep.", "so", "such", "O filme foi tão longo que dormimos.", "So vem antes de adjetivo; such vem antes de (a/an) + substantivo."], [["The street show was so spectacular that hundreds of spectators stopped to watch.", "O show de rua foi tão espetacular que centenas de espectadores pararam para ver."], ["It was such a magnificent night that nobody wanted to go home early.", "Foi uma noite tão magnífica que ninguém queria ir embora cedo."]], [{"t": "c", "q": "It was ___ a cold day that we stayed home.", "o": ["such", "so", "very"], "pt": "Foi um dia tão frio que ficamos em casa.", "why": "Such a + adjetivo + substantivo; so vai direto com adjetivo."}, {"t": "l", "say": "The music was so loud that I left.", "o": ["The music was so loud that I left.", "The music was such loud that I left.", "The music was so loud what I left."], "why": "So + adjetivo + that + resultado."}, {"t": "b", "pt": "Estava tão quente que não saímos", "w": ["It", "was", "so", "hot", "that", "we", "stayed", "inside"]}, {"t": "b", "pt": "Foi uma noite tão boa que dançamos", "w": ["It", "was", "such", "a", "good", "night", "that", "we", "danced"]}]];
