englishB1Plans[66]={"title": "Escolhendo um tablet para a faculdade", "file": "", "grammar": "Too e enough com infinitivo", "goal": "Diga se algo é ou não é suficiente com too e enough + infinitivo, como em ‘too heavy to carry’.", "words": [["option", "opção"], ["standard", "padrão, comum"], ["limited", "limitado"], ["capacity", "capacidade"], ["efficient", "eficiente"], ["electronic", "eletrônico"], ["practical", "prático"], ["valuable", "valioso"]]};
englishB1Content[66]=[[["Ana needs a tablet to take notes in class, but her budget is limited.", "A Ana precisa de um tablet para anotar nas aulas, mas o orçamento dela é limitado."], ["The first option was too heavy to carry in her bag every day.", "A primeira opção era pesada demais para carregar na bolsa todo dia."], ["The second one had a standard screen, and it was big enough to read comfortably.", "O segundo tinha uma tela padrão, e era grande o bastante para ler com conforto."], ["Its battery was efficient enough to last the whole day at school.", "A bateria era eficiente o bastante para durar o dia todo na escola."], ["The salesman said electronic books are practical, because one tablet can hold hundreds.", "O vendedor disse que livros eletrônicos são práticos, porque um tablet guarda centenas."], ["Ana thought the capacity was good enough, so she paid and took it home.", "A Ana achou a capacidade boa o bastante, então pagou e levou para casa."]], [["So, did you buy the tablet? Was the price low enough to fit your budget?", "Então, você comprou o tablet? O preço era baixo o bastante para caber no orçamento?"], ["Yes, and I’m happy. The first option was too heavy to use on the bus, so I chose another.", "Comprei, e estou feliz. A primeira opção era pesada demais para usar no ônibus, então escolhi outra."], ["Smart. What about the storage? Is it large enough to keep all your class files?", "Esperto. E o armazenamento? É grande o bastante para guardar todos os arquivos das aulas?"], ["It has sixty-four gigabytes, which is plenty for me. I use the cloud for the rest.", "Tem sessenta e quatro gigabytes, que é bastante para mim. Uso a nuvem para o resto."], ["Great. Did the store include a case? Your notes are valuable, and a screen can break easily.", "Ótimo. A loja incluiu uma capa? Suas anotações são valiosas, e a tela pode quebrar fácil."], ["They offered one for forty dollars, but I’ll look online and compare a few prices first.", "Ofereceram uma por quarenta dólares, mas vou olhar online e comparar alguns preços primeiro."], ["Good plan. Send me the link when you find one, and I’ll check it for you.", "Bom plano. Me mande o link quando achar uma, e eu confiro para você."], ["Sure, I’ll send it tonight. Thanks for the advice, Ben!", "Claro, mando hoje à noite. Obrigada pelo conselho, Ben!"]], ["/f/ em enough e efficient", "Em enough o ‘gh’ soa como /f/: i-NAF. Em efficient o ‘ff’ também é /f/ e a força vai na segunda sílaba: i-FI-shent.", ["enough", "efficient"]], ["The box is ___ heavy to carry.", "too", "very", "A caixa é pesada demais para carregar.", "Too + adjetivo + to indica excesso; very não aceita to + verbo nesse sentido."], [["The first option was too heavy to carry in her bag every day.", "A primeira opção era pesada demais para carregar na bolsa todo dia."], ["The second one had a standard screen, and it was big enough to read comfortably.", "O segundo tinha uma tela padrão, e era grande o bastante para ler com conforto."]], [{"t": "c", "q": "The screen is big ___ to read easily.", "o": ["enough", "too", "very"], "pt": "A tela é grande o bastante para ler com facilidade.", "why": "Enough vem depois do adjetivo (big enough)."}, {"t": "l", "say": "The bag is too small to hold my laptop.", "o": ["The bag is too small to hold my laptop.", "The bag is enough small to hold my laptop.", "The bag is too small for hold my laptop."], "why": "Too + adjetivo + to + verbo; enough nunca vem antes do adjetivo."}, {"t": "b", "pt": "O tablet é caro demais para comprar", "w": ["The", "tablet", "is", "too", "expensive", "to", "buy"]}, {"t": "b", "pt": "Ela é forte o bastante para carregar", "w": ["She", "is", "strong", "enough", "to", "carry", "it"]}]];
