englishB1Plans[67]={"title": "Rastreando uma encomenda que não chega", "file": "", "grammar": "As soon as, while, until, whenever: tempo e repetição", "goal": "Fale de tempo e repetição com as soon as, while, until e whenever.", "words": [["shortly", "em breve"], ["shortage", "falta, escassez"], ["anxiously", "ansiosamente"], ["whenever", "sempre que"], ["nowhere", "lugar nenhum"], ["meanwhile", "enquanto isso"], ["show up", "aparecer, chegar"], ["track a package", "rastrear uma encomenda"], ["constantly", "o tempo todo"]]};
englishB1Content[67]=[[["Tom ordered a jacket online, and it was supposed to show up on Friday.", "O Tom comprou uma jaqueta online, e ela devia chegar na sexta."], ["He constantly checks the app whenever he has a free minute at work.", "Ele confere o app o tempo todo sempre que tem um minuto livre no trabalho."], ["The page says there is a shortage of drivers, so the box is nowhere near his street.", "A página diz que faltam motoristas, então a caixa não está nem perto da rua dele."], ["Meanwhile, Tom waited anxiously at home while the rain fell outside.", "Enquanto isso, o Tom esperou ansioso em casa enquanto a chuva caía lá fora."], ["He decided to track a package on the company’s website until someone answered the phone.", "Ele decidiu rastrear a encomenda no site da empresa até alguém atender o telefone."], ["As soon as the driver rang the bell, Tom opened the door and smiled.", "Assim que o motorista tocou a campainha, o Tom abriu a porta e sorriu."]], [["Tom, did your jacket arrive yet? You’ve been checking your phone all morning.", "Tom, sua jaqueta chegou? Você está olhando o celular a manhã toda."], ["Not yet. The website says it will arrive shortly, but I don’t believe it.", "Ainda não. O site diz que chega em breve, mas não acredito."], ["Call customer service. They can tell you where it is while you wait on the line.", "Ligue para o atendimento. Eles dizem onde está enquanto você espera na linha."], ["I did that twice. The agent said there’s a delay because of the storm last week.", "Já fiz isso duas vezes. O atendente disse que há atraso por causa da tempestade da semana passada."], ["That’s annoying. Whenever I order something in December, the same thing happens.", "Que chato. Sempre que peço algo em dezembro, acontece a mesma coisa."], ["I’ll wait until six o’clock, and if it doesn’t come, I’ll ask for my money back.", "Vou esperar até as seis, e se não chegar, peço o dinheiro de volta."], ["Good plan. Text me when it arrives, and I’ll come see the jacket on Saturday.", "Bom plano. Me mande mensagem quando chegar, e eu vou ver a jaqueta no sábado."], ["Deal. I’ll send you a photo tonight, I promise.", "Combinado. Mando uma foto hoje à noite, prometo."]], ["/ʃ/ em shortly e shortage", "O ‘sh’ é /ʃ/, como o ‘ch’ de ‘chá’ em português. Fale SHÓRT-li e SHÓR-tij.", ["shortly", "shortage"]], ["Call me ___ you get home.", "as soon as", "until", "Me ligue assim que chegar em casa.", "As soon as = assim que; until = até, e indicaria que a ligação só ocorre depois."], [["As soon as the driver rang the bell, Tom opened the door and smiled.", "Assim que o motorista tocou a campainha, o Tom abriu a porta e sorriu."], ["I’ll wait until six o’clock, and if it doesn’t come, I’ll ask for my money back.", "Vou esperar até as seis, e se não chegar, peço o dinheiro de volta."]], [{"t": "c", "q": "I’ll wait here ___ the bus comes.", "o": ["until", "while", "whenever"], "pt": "Vou esperar aqui até o ônibus chegar.", "why": "Until indica o ponto em que a espera termina."}, {"t": "l", "say": "Whenever it rains, I take the bus.", "o": ["Whenever it rains, I take the bus.", "Whenever it will rain, I take the bus.", "Whenever it rains, I will to take the bus."], "why": "Depois de whenever, use o presente simples, mesmo para hábitos."}, {"t": "b", "pt": "Ligue para mim assim que chegar", "w": ["Call", "me", "as", "soon", "as", "you", "arrive"]}, {"t": "b", "pt": "Eu leio enquanto espero o ônibus", "w": ["I", "read", "while", "I", "wait", "for", "the", "bus"]}]];
