englishB1Plans[68]={"title": "Aceitar ou não a vaga em outra cidade", "file": "", "grammar": "On the other hand, besides, therefore: conectivos de opinião", "goal": "Compare prós e contras com on the other hand, besides, therefore e furthermore.", "words": [["relationship", "relacionamento"], ["potential", "potencial"], ["policy", "política (regra)"], ["tend", "tender a, costumar"], ["relocate", "mudar de cidade (a trabalho)"], ["job offer", "proposta de emprego"], ["furthermore", "além disso"], ["consequently", "consequentemente"]]};
englishB1Content[68]=[[["Omar got a job offer from a company in Seattle, and he must answer by Friday.", "O Omar recebeu uma proposta de emprego de uma empresa em Seattle, e deve responder até sexta."], ["The salary is higher; on the other hand, he would have to relocate far from his family.", "O salário é maior; por outro lado, ele teria de se mudar para longe da família."], ["Besides the money, the new job has great potential for growth in the next five years.", "Além do dinheiro, o novo emprego tem grande potencial de crescimento nos próximos cinco anos."], ["His relationship with his sister is very close, and he tends to visit her every weekend.", "O relacionamento dele com a irmã é muito próximo, e ele costuma visitá-la todo fim de semana."], ["Therefore, leaving would be hard, and consequently he asked about the company policy on remote work.", "Portanto, sair seria difícil, e consequentemente ele perguntou sobre a política da empresa para trabalho remoto."], ["Furthermore, his future boss said he could work from home two days a week.", "Além disso, o futuro chefe disse que ele poderia trabalhar de casa dois dias por semana."]], [["Omar, you look worried. Did you decide about the job in Seattle?", "Omar, você parece preocupado. Decidiu sobre o emprego em Seattle?"], ["Not yet. The salary is higher, but on the other hand, I’d miss my family a lot.", "Ainda não. O salário é maior, mas por outro lado eu sentiria muita falta da família."], ["I understand. Besides, you just bought furniture for your apartment here, right?", "Entendo. Além disso, você acabou de comprar móveis para o apartamento daqui, não é?"], ["Right. And they want me to start in March, so I don’t have much time to decide.", "Isso. E eles querem que eu comece em março, então tenho pouco tempo para decidir."], ["What does your sister think? You two are so close.", "O que sua irmã acha? Vocês dois são muito próximos."], ["She wants me to go. She says chances like this don’t come every year.", "Ela quer que eu vá. Diz que chances assim não aparecem todo ano."], ["Then ask them about working from home. Therefore you might keep both your job and your family.", "Então pergunte sobre trabalhar de casa. Assim você talvez mantenha o emprego e a família."], ["Good idea. I’ll write them an email tonight and call you tomorrow.", "Boa ideia. Vou escrever um e-mail hoje à noite e te ligo amanhã."]], ["sílaba forte em policy e relationship", "Em policy a força cai na primeira sílaba: PÓ-li-si. Em relationship, na segunda: ri-LEI-shon-ship.", ["policy", "relationship"]], ["I like the house. ___, it’s too expensive.", "However", "Therefore", "Eu gosto da casa. Porém, é cara demais.", "However marca contraste; therefore marca resultado, o que não faz sentido aqui."], [["The salary is higher; on the other hand, he would have to relocate far from his family.", "O salário é maior; por outro lado, ele teria de se mudar para longe da família."], ["Right. And they want me to start in March, so I don’t have much time to decide.", "Isso. E eles querem que eu comece em março, então tenho pouco tempo para decidir."]], [{"t": "c", "q": "The car is cheap. ___, it uses a lot of gas.", "o": ["On the other hand", "Therefore", "Besides"], "pt": "O carro é barato. Por outro lado, gasta muita gasolina.", "why": "On the other hand apresenta o lado oposto de uma ideia."}, {"t": "l", "say": "It’s late; therefore, we should go home.", "o": ["It’s late; therefore, we should go home.", "It’s late; besides, we should go home.", "It’s late; on the other hand, we should go home."], "why": "Therefore indica consequência: é tarde, logo devemos ir."}, {"t": "b", "pt": "Além disso eu estou cansada", "w": ["Besides", "I", "am", "very", "tired"]}, {"t": "b", "pt": "Por outro lado o emprego paga mais", "w": ["On", "the", "other", "hand", "the", "job", "pays", "more"]}]];
