englishB1Plans[69]={"title": "Debate: ruas do centro sem carros", "file": "", "grammar": "Revisão: argumentar a favor e contra (mini-história)", "goal": "Defenda e rebata ideias combinando conectivos como although, despite, besides e therefore.", "words": [["transportation", "transporte"], ["opposition", "oposição"], ["politician", "político"], ["viewpoint", "ponto de vista"], ["obviously", "obviamente"], ["public transit", "transporte público"], ["in favor of", "a favor de"], ["pollutant", "poluente"], ["limitation", "limitação, restrição"]]};
englishB1Content[69]=[[["The city council wants to close the downtown streets to cars, and people are arguing about it.", "A câmara da cidade quer fechar as ruas do centro para carros, e as pessoas estão discutindo."], ["Rosa is in favor of the idea because cars create pollutants that make the air dirty.", "A Rosa é a favor da ideia porque os carros criam poluentes que sujam o ar."], ["Ben, whose shop is on Main Street, is against it, although he understands the problem.", "O Ben, cuja loja fica na Main Street, é contra, embora entenda o problema."], ["He says that public transit is too slow to bring customers, so the limitation could hurt small shops.", "Ele diz que o transporte público é lento demais para trazer clientes, então a restrição pode prejudicar lojas pequenas."], ["The opposition group, which met on Monday, also said that transportation costs are already high for workers.", "O grupo de oposição, que se reuniu na segunda, também disse que o custo do transporte já é alto para os trabalhadores."], ["The politician who proposed the plan listened to both viewpoints and asked for another meeting.", "O político que propôs o plano ouviu os dois pontos de vista e pediu outra reunião."]], [["Ben, are you coming to the council meeting tonight about closing the downtown streets?", "Ben, você vai à reunião da câmara hoje à noite sobre fechar as ruas do centro?"], ["Yes, I’ll be there. I’m not in favor of the plan, although I understand your point.", "Vou sim. Não sou a favor do plano, embora entenda o seu ponto."], ["Obviously, I disagree. Cars create a lot of pollution, and the air near the school is terrible.", "Obviamente discordo. Carros criam muita poluição, e o ar perto da escola é péssimo."], ["I agree about the air. On the other hand, my customers need to park near my shop.", "Concordo sobre o ar. Por outro lado, meus clientes precisam estacionar perto da minha loja."], ["Besides, a pedestrian street could bring more people, so you may earn more money.", "Além disso, uma rua de pedestres pode trazer mais gente, então você pode ganhar mais."], ["Maybe. Therefore, I’m asking the city to try it for three months first.", "Talvez. Por isso, estou pedindo à prefeitura que teste por três meses primeiro."], ["That’s fair. A three-month test would let everyone see the results before the final decision.", "É justo. Um teste de três meses deixaria todos verem os resultados antes da decisão final."], ["Exactly. Let’s sit together at the meeting and support the test idea.", "Exato. Vamos sentar juntos na reunião e apoiar a ideia do teste."]], ["/ʃ/ em -tion, em transportation e opposition", "O final -tion soa /ʃən/, como ‘chân’. A força vem antes: trans-por-TEI-shon, o-po-ZI-shon.", ["transportation", "opposition"]], ["___ the rain, hundreds of people came to the meeting.", "Despite", "Although", "Apesar da chuva, centenas de pessoas vieram à reunião.", "Despite é seguido de substantivo (the rain); although pediria sujeito e verbo."], [["Rosa is in favor of the idea because cars create pollutants that make the air dirty.", "A Rosa é a favor da ideia porque os carros criam poluentes que sujam o ar."], ["I agree about the air. On the other hand, my customers need to park near my shop.", "Concordo sobre o ar. Por outro lado, meus clientes precisam estacionar perto da minha loja."]], [{"t": "c", "q": "I like the plan. ___, it needs more time.", "o": ["However", "Despite", "So that"], "pt": "Eu gosto do plano. Porém, ele precisa de mais tempo.", "why": "However liga duas frases e mostra contraste."}, {"t": "l", "say": "Despite the rain, the meeting was full.", "o": ["Despite the rain, the meeting was full.", "Despite it rained, the meeting was full.", "Despite of the rain, the meeting was full."], "why": "Despite + substantivo, sem of e sem verbo conjugado."}, {"t": "b", "pt": "Ela é a favor do novo plano", "w": ["She", "is", "in", "favor", "of", "the", "new", "plan"]}, {"t": "b", "pt": "Além disso o ar está sujo", "w": ["Besides", "the", "air", "is", "very", "dirty"]}]];
englishB1PhotoThemes[69]="map";
englishB1MiniStories[69]=["A rua que ficou sem carros", "Last spring, the mayor, who loves bikes, wanted to close Main Street to cars.~Na primavera passada, o prefeito, que adora bicicletas, quis fechar a Main Street para os carros.|Rosa, whose café is on that street, was in favor of the plan.~A Rosa, cujo café fica naquela rua, era a favor do plano.|Ben, whose shoe shop is next door, was worried about his customers.~O Ben, cuja sapataria fica ao lado, estava preocupado com seus clientes.|Although many people liked the idea, others said parking was already too difficult.~Embora muita gente gostasse da ideia, outros diziam que estacionar já era difícil demais.|Despite the rain, three hundred residents came to the meeting so that everyone could speak.~Apesar da chuva, trezentos moradores foram à reunião para que todos pudessem falar.|It was such a long meeting that the mayor ordered pizza for the room.~Foi uma reunião tão longa que o prefeito pediu pizza para o salão.|As soon as the voting started, the room became quiet.~Assim que a votação começou, o salão ficou em silêncio.|Finally they agreed on a test; therefore, Main Street closed on Sundays for three months.~No fim, concordaram com um teste; por isso, a Main Street fechou aos domingos por três meses.|Ben put chairs outside his shop, and the street was beautiful enough to bring new customers.~O Ben pôs cadeiras na frente da loja, e a rua estava bonita o bastante para trazer novos clientes.|In the end, even Ben was happy, and the city made the test permanent.~No fim, até o Ben ficou feliz, e a cidade tornou o teste permanente."];
englishB1Plans[70]={"title": "Primeiro ano morando no Canadá", "file": "", "grammar": "Used to, be used to e get used to", "goal": "Fale de hábitos do passado e de coisas a que você já se acostumou usando used to e be used to.", "words": [["adjust", "adaptar-se"], ["household", "lar, casa (as pessoas da casa)"], ["immigration", "imigração"], ["emotional", "emocionado, emotivo"], ["attitude", "atitude"], ["citizen", "cidadão"], ["status", "situação, status"], ["foreign", "estrangeiro"]]};
englishB1Content[70]=[[["When Lucas moved to Canada, he wasn’t used to the cold winters at all.", "Quando o Lucas se mudou para o Canadá, ele não estava nada acostumado aos invernos frios."], ["He used to live with his big family, but now his household is just him.", "Ele morava com a família grande, mas agora a casa dele é só ele."], ["The immigration office told him his status would change after two years.", "O escritório de imigração disse que a situação dele mudaria depois de dois anos."], ["He used to call his mother every night, because the first months were emotional.", "Ele ligava para a mãe toda noite, porque os primeiros meses foram emotivos."], ["Slowly his attitude changed, and he got used to taking the bus in the snow.", "Aos poucos a atitude dele mudou, e ele se acostumou a pegar o ônibus na neve."], ["Now he’s trying to adjust to life here, and he wants to become a citizen.", "Agora ele tenta se adaptar à vida aqui e quer se tornar cidadão."]], [["Do you miss Brazil, or have you already adjusted to life in Toronto?", "Você sente falta do Brasil ou já se adaptou à vida em Toronto?"], ["I used to miss it every day, but now I’m used to it.", "Eu sentia falta todo dia, mas agora já estou acostumado."], ["Really? I’m still not used to the cold. I wear three sweaters at home!", "Sério? Eu ainda não me acostumei com o frio. Uso três blusas em casa!"], ["Me too at first. I used to complain about it every morning.", "Eu também no começo. Eu reclamava disso toda manhã."], ["Did you have any trouble at the immigration office last week?", "Você teve algum problema no escritório de imigração semana passada?"], ["A little. They asked about my household, so I brought every paper I could find.", "Um pouco. Perguntaram sobre a minha casa, então levei todos os papéis que achei."], ["Good idea. You’ll get used to the waiting lines, too. Everybody does.", "Boa ideia. Você também vai se acostumar às filas. Todo mundo se acostuma."], ["Thanks, Lucas. So we’re meeting at the coffee shop at six, right?", "Obrigado, Lucas. Então nos encontramos na cafeteria às seis, certo?"]], ["/ʃ/ em immigration e emotional", "O grupo -tion e -tional soa como /ʃ/: im-mi-GRAY-shun e e-MO-shuh-nul. Não pronuncie um /t/ separado.", ["immigration", "emotional"]], ["I ___ live in São Paulo, but now I live in Toronto.", "used to", "am used to", "Eu morava em São Paulo, mas agora moro em Toronto.", "Used to + verbo fala de um hábito ou estado que existiu no passado e acabou."], [["He used to live with his big family, but now his household is just him.", "Ele morava com a família grande, mas agora a casa dele é só ele."], ["I used to miss it every day, but now I’m used to it.", "Eu sentia falta todo dia, mas agora já estou acostumado."]], [{"t": "c", "q": "She ___ the cold winters, so she wears a big coat.", "o": ["is used to", "used to", "is use to"], "pt": "Ela está acostumada aos invernos frios, então usa um casaco grande.", "why": "Be used to + substantivo mostra o que já é normal para você agora."}, {"t": "l", "say": "I used to miss it every day, but now I’m used to it.", "o": ["I used to miss it every day, but now I’m used to it.", "I use to miss it every day, but now I’m used to it.", "I used to miss it every day, but now I’m use to it."], "why": "Passado: used to; agora: be used to."}, {"t": "b", "pt": "Eu me acostumei a pegar o ônibus.", "w": ["I", "got", "used", "to", "taking", "the", "bus"]}, {"t": "b", "pt": "Ele morava com a família grande.", "w": ["He", "used", "to", "live", "with", "his", "big", "family"]}]];
