englishB1Plans[71]={"title": "Depois da cirurgia do vovô", "file": "", "grammar": "Verbo + gerúndio ou infinitivo: remember, stop, try, forget", "goal": "Diga se você lembrou de fazer algo ou esqueceu, e se parou ou tentou algo, usando remember, stop, try e forget.", "words": [["surgery", "cirurgia"], ["therapy", "terapia, fisioterapia"], ["anxious", "ansioso, preocupado"], ["recognize", "reconhecer"], ["embrace", "abraço"], ["support", "apoio"], ["get over", "superar, se recuperar de"], ["encouragement", "incentivo, ânimo"]]};
englishB1Content[71]=[[["Grandpa Joe had surgery on his knee last month, and the whole family was anxious.", "O vovô Joe fez uma cirurgia no joelho mês passado, e a família toda ficou ansiosa."], ["He stopped walking for weeks, but the doctor said physical therapy would help.", "Ele parou de andar por semanas, mas o médico disse que a fisioterapia ajudaria."], ["Joe remembered to do his exercises, but he forgot to take his pills twice.", "O Joe lembrou de fazer os exercícios, mas esqueceu de tomar os remédios duas vezes."], ["His granddaughter Nina gave him a lot of support and encouragement.", "A neta dele, Nina, deu a ele muito apoio e incentivo."], ["When she arrived, he almost didn’t recognize her, and they gave each other a big embrace.", "Quando ela chegou, ele quase não a reconheceu, e eles se deram um grande abraço."], ["He says it takes time to get over an operation, but he’s trying to stay positive.", "Ele diz que leva tempo para se recuperar de uma operação, mas está tentando se manter positivo."]], [["Did you remember to call Grandpa about his therapy appointment?", "Você lembrou de ligar para o vovô sobre a consulta de fisioterapia?"], ["Yes, I did. He’s anxious, but he remembers to do the exercises every morning.", "Sim. Ele está ansioso, mas lembra de fazer os exercícios toda manhã."], ["Good. He forgot to take his pills twice last week, though.", "Que bom. Mas ele esqueceu de tomar os remédios duas vezes semana passada."], ["I’ll try putting a note on the fridge. Maybe that will help him remember.", "Vou tentar colar um bilhete na geladeira. Talvez isso o ajude a lembrar."], ["Great idea. I stopped worrying about his knee when I saw him walk yesterday.", "Ótima ideia. Parei de me preocupar com o joelho dele quando o vi andar ontem."], ["Me too. Do you think he’ll get over the surgery soon?", "Eu também. Você acha que ele vai se recuperar logo da cirurgia?"], ["The doctor said yes, but he needs our support and encouragement.", "O médico disse que sim, mas ele precisa do nosso apoio e incentivo."], ["Then let’s visit him on Saturday at three. Don’t forget to bring the cake!", "Então vamos visitá-lo no sábado às três. Não esqueça de levar o bolo!"]], ["/θ/ em therapy e month", "Para o /θ/, ponha a ponta da língua entre os dentes e solte o ar sem voz: THE-ra-py, MONTH. Não troque por /f/ nem por /t/.", ["therapy", "month"]], ["I forgot ___ my pills this morning.", "to take", "taking", "Eu esqueci de tomar meus remédios hoje de manhã.", "Forget + to + verbo = esquecer de fazer algo que era necessário."], [["Joe remembered to do his exercises, but he forgot to take his pills twice.", "O Joe lembrou de fazer os exercícios, mas esqueceu de tomar os remédios duas vezes."], ["Did you remember to call Grandpa about his therapy appointment?", "Você lembrou de ligar para o vovô sobre a consulta de fisioterapia?"]], [{"t": "c", "q": "She stopped ___ when she felt tired.", "o": ["walking", "to walk", "walk"], "pt": "Ela parou de andar quando se sentiu cansada.", "why": "Stop + gerúndio = parar uma atividade."}, {"t": "l", "say": "I’ll try putting a note on the fridge.", "o": ["I’ll try putting a note on the fridge.", "I’ll try put a note on the fridge.", "I’ll try to putting a note on the fridge."], "why": "Try + gerúndio = experimentar algo para ver se funciona."}, {"t": "b", "pt": "Você lembrou de ligar para ele?", "w": ["Did", "you", "remember", "to", "call", "him"]}, {"t": "b", "pt": "Ele precisa do nosso apoio.", "w": ["He", "needs", "our", "support"]}]];
