englishB1Plans[72]={"title": "Campanha por uma praça nova no bairro", "file": "", "grammar": "Preposição + gerúndio: interested in, good at, afraid of", "goal": "Fale do que você tem interesse, do que faz bem e do que tem medo usando preposição + gerúndio.", "words": [["protest", "protesto"], ["community", "comunidade"], ["justice", "justiça"], ["contribute", "contribuir"], ["equal", "igual"], ["assist", "ajudar, auxiliar"], ["organize", "organizar"], ["campaign", "campanha"]]};
englishB1Content[72]=[[["Rosa is interested in organizing a campaign for a new playground in her community.", "A Rosa tem interesse em organizar uma campanha por um novo parquinho na comunidade dela."], ["She’s good at talking to people, but she’s afraid of speaking in public.", "Ela é boa em conversar com as pessoas, mas tem medo de falar em público."], ["Her neighbors are tired of waiting, so they plan a peaceful protest on Saturday.", "Os vizinhos estão cansados de esperar, então planejam um protesto pacífico no sábado."], ["They call it a question of justice, because every child deserves an equal chance to play.", "Eles chamam isso de questão de justiça, porque toda criança merece uma chance igual de brincar."], ["Tom offered to assist by printing posters, and everyone wants to contribute something.", "O Tom se ofereceu para ajudar imprimindo cartazes, e todos querem contribuir com algo."], ["By noon they had two hundred signatures, and Rosa forgot about being afraid.", "Ao meio-dia eles tinham duzentas assinaturas, e a Rosa esqueceu o medo."]], [["Are you still thinking of organizing the protest on Saturday?", "Você ainda está pensando em organizar o protesto no sábado?"], ["Yes, I am. I’m excited about meeting everyone at the park at ten.", "Estou sim. Estou animada para encontrar todo mundo no parque às dez."], ["I’m afraid of forgetting something important. Can you assist me with the posters?", "Tenho medo de esquecer algo importante. Você pode me ajudar com os cartazes?"], ["Sure. I’m good at drawing, so I’ll make the signs for the campaign.", "Claro. Sou bom em desenhar, então faço as placas da campanha."], ["Thanks. And who’s in charge of talking to the local newspaper?", "Obrigada. E quem fica responsável por falar com o jornal local?"], ["Lia. She’s interested in working with the media, and she’s good at explaining things.", "A Lia. Ela se interessa por trabalhar com a mídia e é boa em explicar as coisas."], ["Perfect. Everyone wants to contribute, so we shouldn’t have a problem.", "Perfeito. Todo mundo quer contribuir, então não devemos ter problemas."], ["Right. See you at ten, and remember to bring water for the kids!", "Certo. Nos vemos às dez, e lembre de levar água para as crianças!"]], ["/dʒ/ em justice e organizing", "O /dʒ/ de justice começa como um /d/ e termina como um /ʒ/: DJUS-tis. Em organizing, o -g- também soa /dʒ/.", ["justice", "organizing"]], ["She’s afraid ___ in public.", "of speaking", "to speak", "Ela tem medo de falar em público.", "Depois de uma preposição (of, in, at) o verbo vai no gerúndio (-ing)."], [["She’s good at talking to people, but she’s afraid of speaking in public.", "Ela é boa em conversar com as pessoas, mas tem medo de falar em público."], ["I’m afraid of forgetting something important. Can you assist me with the posters?", "Tenho medo de esquecer algo importante. Você pode me ajudar com os cartazes?"]], [{"t": "c", "q": "I’m good ___ cooking for large groups.", "o": ["at", "in", "for"], "pt": "Eu sou bom em cozinhar para grupos grandes.", "why": "Good at + gerúndio = ser bom em fazer algo."}, {"t": "l", "say": "She’s interested in working with the media.", "o": ["She’s interested in working with the media.", "She’s interested to work with the media.", "She’s interested on working with the media."], "why": "Interested in + gerúndio."}, {"t": "b", "pt": "Estamos cansados de esperar.", "w": ["We", "are", "tired", "of", "waiting"]}, {"t": "b", "pt": "Ele tem medo de esquecer algo.", "w": ["He", "is", "afraid", "of", "forgetting", "something"]}]];
