englishB1Plans[73]={"title": "A crise de moradia na cidade pequena", "file": "", "grammar": "Quantifiers avançados: a great deal of, plenty of, several, hardly any", "goal": "Descreva quantidades com a great deal of, plenty of, several e hardly any ao falar de um problema da cidade.", "words": [["crisis", "crise"], ["conflict", "conflito"], ["propose", "propor"], ["complicated", "complicado"], ["inspect", "inspecionar, vistoriar"], ["furnish", "mobiliar"], ["promote", "promover, incentivar"], ["poverty", "pobreza"]]};
englishB1Content[73]=[[["The town has a housing crisis, and plenty of families can’t afford rent.", "A cidade tem uma crise de moradia, e muitas famílias não conseguem pagar aluguel."], ["A great deal of money goes to rent, so hardly any is left for food.", "Uma grande quantia vai para o aluguel, então quase nada sobra para comida."], ["At the meeting, Mayor Diaz proposed building several small apartment buildings near the station.", "Na reunião, a prefeita Diaz propôs construir vários prédios pequenos perto da estação."], ["An inspector will inspect each building, and the city will furnish a few apartments for families in poverty.", "Um fiscal vai vistoriar cada prédio, e a cidade vai mobiliar alguns apartamentos para famílias em situação de pobreza."], ["Some neighbors fear a conflict, because there aren’t many parking spaces and hardly any free land.", "Alguns vizinhos temem um conflito, porque há poucas vagas e quase nenhum terreno livre."], ["It’s a complicated problem, but the council wants to promote a fair plan before winter.", "É um problema complicado, mas a câmara quer incentivar um plano justo antes do inverno."]], [["Did you go to the meeting about the housing crisis last night?", "Você foi à reunião sobre a crise de moradia ontem à noite?"], ["I did. There were plenty of people, and several of them were really angry.", "Fui. Havia muita gente, e vários deles estavam muito bravos."], ["Really? What did the mayor propose?", "Sério? O que a prefeita propôs?"], ["She wants to build a few small buildings, but there’s hardly any money in the budget.", "Ela quer construir alguns prédios pequenos, mas quase não há dinheiro no orçamento."], ["That’s a great deal of work. Did anyone have an idea about parking?", "É muito trabalho. Alguém teve uma ideia sobre o estacionamento?"], ["Not really. There aren’t many spaces now, and there will be even fewer.", "Na verdade, não. Não há muitas vagas agora, e vai haver menos ainda."], ["It’s complicated. I hope they inspect everything carefully before families move in.", "É complicado. Espero que vistoriem tudo com cuidado antes de as famílias se mudarem."], ["They will. There’s another meeting on Thursday at seven. Are you coming?", "Vão sim. Tem outra reunião na quinta às sete. Você vem?"]], ["/k/ em crisis e complicated", "O c de crisis e de complicated soa /k/ forte: KRAI-sis, KOM-pli-kay-tid. Em crisis, o i soa /aɪ/ como em my.", ["crisis", "complicated"]], ["There are ___ people at the meeting tonight.", "plenty of", "a great deal of", "Há muita gente na reunião hoje à noite.", "Plenty of serve para contáveis e incontáveis; a great deal of só para incontáveis."], [["The town has a housing crisis, and plenty of families can’t afford rent.", "A cidade tem uma crise de moradia, e muitas famílias não conseguem pagar aluguel."], ["I did. There were plenty of people, and several of them were really angry.", "Fui. Havia muita gente, e vários deles estavam muito bravos."]], [{"t": "c", "q": "There is hardly ___ money left in the budget.", "o": ["any", "many", "a few"], "pt": "Quase não sobra dinheiro no orçamento.", "why": "Hardly any = quase nenhum; money é incontável, então any serve."}, {"t": "l", "say": "A great deal of money goes to rent.", "o": ["A great deal of money goes to rent.", "A great deal of moneys goes to rent.", "A great deal money goes to rent."], "why": "A great deal of + incontável."}, {"t": "b", "pt": "Vários vizinhos estavam bravos.", "w": ["Several", "neighbors", "were", "angry"]}, {"t": "b", "pt": "Há muitas famílias aqui.", "w": ["There", "are", "plenty", "of", "families", "here"]}]];
