englishB1Plans[74]={"title": "O relatório que não podia esperar", "file": "", "grammar": "Phrasal verbs separáveis e inseparáveis", "goal": "Use phrasal verbs comuns no trabalho e saiba quando o objeto vai no meio (point it out) ou depois (look up to him).", "words": [["put off", "adiar"], ["pick up on", "perceber"], ["break down", "quebrar, pifar"], ["look up to", "admirar"], ["catch up with", "alcançar, pôr o assunto em dia"], ["take on", "assumir, aceitar (trabalho)"], ["point out", "apontar, destacar"], ["step in", "intervir, ajudar"]]};
englishB1Content[74]=[[["We can’t put off the report any longer, because the client wants it on Friday.", "Não podemos adiar mais o relatório, porque o cliente o quer na sexta."], ["Sam can pick up on small mistakes quickly, and he likes to point out each one politely.", "O Sam percebe erros pequenos rápido e gosta de apontar cada um com educação."], ["I really look up to Sam, but he doesn’t want to take on more clients.", "Eu admiro muito o Sam, mas ele não quer assumir mais clientes."], ["When the printer started to break down again, Lia had to step in and bring hers.", "Quando a impressora começou a pifar de novo, a Lia teve que intervir e trazer a dela."], ["Mia was out sick, so she has to catch up with the team on Monday.", "A Mia estava doente, então ela tem que se atualizar com a equipe na segunda."], ["Now we’ve picked up our pace, and we can finish before dinner.", "Agora aceleramos o ritmo e podemos terminar antes do jantar."]], [["Did you put off the budget again? You promised to send it today.", "Você adiou o orçamento de novo? Prometeu enviar hoje."], ["I’m sorry. My laptop started to break down this morning, so I lost two hours.", "Desculpe. Meu notebook começou a pifar hoje de manhã, e perdi duas horas."], ["Ugh. Can you point out which pages still need work?", "Ai. Você pode apontar quais páginas ainda precisam de trabalho?"], ["Sure. Pages four and five. I’ll look them over again after lunch.", "Claro. Páginas quatro e cinco. Vou dar outra olhada nelas depois do almoço."], ["Don’t worry. I’ll step in and write page five myself.", "Não se preocupe. Eu vou ajudar e escrever a página cinco."], ["Really? You’re a lifesaver. I really look up to you, Sam.", "Sério? Você me salvou. Eu admiro muito você, Sam."], ["Thanks, but you can’t take on every job alone. We’re a team.", "Obrigado, mas você não pode assumir todo o trabalho sozinho. Somos uma equipe."], ["True. So I’ll send the whole report by five, and you’ll check it, right?", "Verdade. Então envio o relatório inteiro às cinco, e você confere, certo?"]], ["/p/ aspirado em point e put", "No início de palavra tônica, o /p/ sai com um sopro de ar: Ppoint, Pput. Coloque a mão na frente da boca e sinta o ar.", ["point", "put"]], ["Please ___, because I’m still not ready.", "put it off", "put off it", "Por favor, adie isso, porque eu ainda não estou pronto.", "Em phrasal verbs separáveis, um pronome (it, them) vai no meio: put it off."], [["We can’t put off the report any longer, because the client wants it on Friday.", "Não podemos adiar mais o relatório, porque o cliente o quer na sexta."], ["Ugh. Can you point out which pages still need work?", "Ai. Você pode apontar quais páginas ainda precisam de trabalho?"]], [{"t": "c", "q": "I really ___ my grandmother because she works so hard.", "o": ["look up to", "look up", "look to up"], "pt": "Eu admiro muito minha avó porque ela trabalha muito.", "why": "Look up to é inseparável: o objeto vem depois."}, {"t": "l", "say": "Can you point out which pages still need work?", "o": ["Can you point out which pages still need work?", "Can you point which pages out still need work?", "Can you point out what pages still needs work?"], "why": "Point out + objeto: aqui o objeto longo vem depois."}, {"t": "b", "pt": "Não podemos adiar isso.", "w": ["We", "can’t", "put", "it", "off"]}, {"t": "b", "pt": "A impressora começou a pifar.", "w": ["The", "printer", "started", "to", "break", "down"]}]];
