englishB1Plans[75]={"title": "Despedida de uma professora querida", "file": "", "grammar": "Question tags e respostas curtas", "goal": "Confirme informações com question tags e dê respostas curtas naturais ao falar de um evento triste.", "words": [["funeral", "funeral"], ["grief", "luto, dor da perda"], ["mourning", "luto, tempo de luto"], ["sympathy", "condolências, compaixão"], ["loyalty", "lealdade"], ["honesty", "honestidade"], ["condolences", "pêsames"], ["retirement", "aposentadoria"]]};
englishB1Content[75]=[[["Mrs. Lopez taught history for thirty years, and her funeral was on Saturday.", "A sra. Lopez ensinou história por trinta anos, e o funeral dela foi no sábado."], ["Her retirement was only last spring, so the news came as a big shock.", "A aposentadoria dela foi só na primavera passada, então a notícia foi um grande choque."], ["Hundreds of former students came to offer their condolences and share memories.", "Centenas de ex-alunos vieram dar os pêsames e compartilhar lembranças."], ["Her son thanked everyone for their sympathy, and he spoke about her honesty and loyalty.", "O filho dela agradeceu a todos pela compaixão e falou da honestidade e da lealdade dela."], ["Many people were in mourning, but they smiled when they remembered her jokes.", "Muita gente estava de luto, mas sorriu ao lembrar das piadas dela."], ["Grief is hard, but sharing stories together made the day a little easier.", "O luto é difícil, mas compartilhar histórias juntos deixou o dia um pouco mais leve."]], [["You went to Mrs. Lopez’s funeral, didn’t you?", "Você foi ao funeral da sra. Lopez, não foi?"], ["Yes, I did. It was a beautiful service, wasn’t it? Everyone cried.", "Fui sim. Foi uma cerimônia linda, não foi? Todo mundo chorou."], ["I couldn’t go. I was out of town, but I sent my condolences to her son.", "Eu não pude ir. Estava viajando, mas enviei meus pêsames ao filho dela."], ["That was kind. She didn’t have any other family here, did she?", "Foi gentil. Ela não tinha outros parentes aqui, tinha?"], ["No, she didn’t. But her students were like family, and they all came.", "Não, não tinha. Mas os alunos eram como família, e todos vieram."], ["She was such an honest teacher. Her loyalty to the school was amazing.", "Ela era uma professora tão honesta. A lealdade dela à escola era incrível."], ["It was. We’re going to plant a tree for her next month. You’ll come, won’t you?", "Era mesmo. Vamos plantar uma árvore para ela no mês que vem. Você vem, não vem?"], ["Of course I will. Just send me the date and the time, please.", "Claro que vou. Só me mande a data e a hora, por favor."]], ["/f/ em funeral e former", "O /f/ é feito com os dentes de cima tocando o lábio de baixo: FYOO-nuh-rul, FOR-mer. Não use /p/.", ["funeral", "former"]], ["You went to the funeral, ___?", "didn’t you", "don’t you", "Você foi ao funeral, não foi?", "Frase afirmativa no passado simples: a tag usa didn’t + pronome."], [["Hundreds of former students came to offer their condolences and share memories.", "Centenas de ex-alunos vieram dar os pêsames e compartilhar lembranças."], ["You went to Mrs. Lopez’s funeral, didn’t you?", "Você foi ao funeral da sra. Lopez, não foi?"]], [{"t": "c", "q": "She isn’t coming today, ___?", "o": ["is she", "isn’t she", "does she"], "pt": "Ela não vem hoje, vem?", "why": "Frase negativa pede tag positiva com o mesmo verbo auxiliar: is she."}, {"t": "l", "say": "You’ll come, won’t you?", "o": ["You’ll come, won’t you?", "You’ll come, don’t you?", "You’ll come, aren’t you?"], "why": "Com will, a tag usa won’t."}, {"t": "b", "pt": "Foi uma cerimônia linda, não foi?", "w": ["It", "was", "a", "beautiful", "service", "wasn’t", "it"]}, {"t": "b", "pt": "Ela não tinha família aqui, tinha?", "w": ["She", "didn’t", "have", "family", "here", "did", "she"]}]];
