englishB1Plans[76]={"title": "Colegas que brigaram e fizeram as pazes", "file": "", "grammar": "Pronomes reflexivos e recíprocos: each other, themselves", "goal": "Use each other e os pronomes reflexivos (myself, themselves) para falar de uma briga e de uma reconciliação.", "words": [["cooperate", "cooperar"], ["respect", "respeitar"], ["offend", "ofender"], ["insult", "insultar, ofensa"], ["furious", "furioso"], ["admire", "admirar"], ["accuse", "acusar"], ["greedy", "ganancioso"]]};
englishB1Content[76]=[[["Kenji and Ana used to cooperate well, but last week they stopped speaking to each other.", "O Kenji e a Ana cooperavam bem, mas semana passada pararam de falar um com o outro."], ["Ana was furious because Kenji accused her of being greedy about the bonus.", "A Ana ficou furiosa porque o Kenji a acusou de ser gananciosa por causa do bônus."], ["He didn’t mean to offend her, but his words did insult her.", "Ele não queria ofendê-la, mas as palavras dele a insultaram."], ["They both blamed themselves later, because they truly respect each other’s work.", "Depois, os dois se culparam, porque realmente respeitam o trabalho um do outro."], ["Their manager told them to talk to each other, not about each other.", "A gerente disse para conversarem um com o outro, e não um sobre o outro."], ["Ana said she would always admire Kenji, and they promised to cooperate again.", "A Ana disse que sempre admiraria o Kenji, e eles prometeram cooperar de novo."]], [["Kenji, can we talk? I don’t want us to stop talking to each other.", "Kenji, podemos conversar? Não quero que a gente pare de se falar."], ["Sure, Ana. I’m sorry I accused you of being greedy. I was angry at myself.", "Claro, Ana. Desculpe por ter te acusado de ser gananciosa. Eu estava com raiva de mim mesmo."], ["Thanks. I was furious, but I know I can be difficult. I should ask myself why.", "Obrigada. Eu fiquei furiosa, mas sei que posso ser difícil. Devo me perguntar por quê."], ["We both said things we didn’t mean. We need to respect each other more.", "Nós dois dissemos coisas que não queríamos. Precisamos nos respeitar mais."], ["Agreed. The team can’t solve its problems by itself if we keep fighting.", "Concordo. A equipe não resolve os problemas sozinha se a gente continuar brigando."], ["Right. Our clients don’t see us fighting, but they feel it. People notice everything.", "Certo. Os clientes não nos veem brigando, mas sentem. As pessoas notam tudo."], ["Exactly. So let’s help each other with the new project instead of working alone.", "Exatamente. Então vamos nos ajudar no projeto novo em vez de trabalhar sozinhos."], ["Deal. Lunch tomorrow at noon, and we’ll plan everything for ourselves?", "Combinado. Almoço amanhã ao meio-dia, e a gente planeja tudo juntos, certo?"]], ["Acento em ofFEND e inSULT", "Como verbos, offend e insult têm a força na segunda sílaba: oFFEND, inSULT. Como substantivo, insult muda para INsult.", ["offend", "insult"]], ["They help ___ with the new project.", "each other", "themselves", "Eles se ajudam no projeto novo.", "Each other = um ao outro; themselves = a si mesmos (a ação volta para o próprio sujeito)."], [["They both blamed themselves later, because they truly respect each other’s work.", "Depois, os dois se culparam, porque realmente respeitam o trabalho um do outro."], ["Right. Our clients don’t see us fighting, but they feel it. People notice everything.", "Certo. Os clientes não nos veem brigando, mas sentem. As pessoas notam tudo."]], [{"t": "c", "q": "She hurt ___ while she was cooking.", "o": ["herself", "her", "each other"], "pt": "Ela se machucou enquanto cozinhava.", "why": "Quando sujeito e objeto são a mesma pessoa, usamos herself."}, {"t": "l", "say": "We need to respect each other more.", "o": ["We need to respect each other more.", "We need to respect ourselves more.", "We need to respect themselves more."], "why": "Each other = um ao outro."}, {"t": "b", "pt": "Eles pararam de falar um com o outro.", "w": ["They", "stopped", "speaking", "to", "each", "other"]}, {"t": "b", "pt": "Eu estava com raiva de mim mesmo.", "w": ["I", "was", "angry", "at", "myself"]}]];
