englishB1Plans[77]={"title": "Preparando o seminário da próxima semana", "file": "", "grammar": "Futuro contínuo e futuro perfeito simples: this time next week", "goal": "Fale de ações em andamento num momento futuro (will be -ing) e de ações concluídas até um prazo (will have + particípio).", "words": [["seminar", "seminário"], ["attendee", "participante"], ["delegate", "delegado, representante"], ["theme", "tema"], ["accommodation", "hospedagem"], ["hold off", "esperar, adiar"], ["persuasive", "persuasivo"], ["logical", "lógico"]]};
englishB1Content[77]=[[["This time next week, Priya will be giving a seminar on teamwork in Chicago.", "Nesta hora, na semana que vem, a Priya estará dando um seminário sobre trabalho em equipe em Chicago."], ["By Monday, the organizers will have booked accommodation for every delegate.", "Até segunda, os organizadores terão reservado hospedagem para todos os delegados."], ["About two hundred attendees will be arriving on Sunday evening.", "Cerca de duzentos participantes estarão chegando no domingo à noite."], ["The theme is communication, so Priya wants a logical plan and a persuasive speech.", "O tema é comunicação, então a Priya quer um plano lógico e um discurso persuasivo."], ["She’ll have finished her slides by Friday, but she’ll hold off on printing until the last minute.", "Ela terá terminado os slides até sexta, mas vai esperar para imprimir até o último minuto."], ["Next Tuesday at noon, she’ll be answering questions and smiling with relief.", "Na terça que vem, ao meio-dia, ela estará respondendo perguntas e sorrindo aliviada."]], [["This time next week, I’ll be standing on stage in front of two hundred people.", "Nesta hora, na semana que vem, estarei no palco diante de duzentas pessoas."], ["You’ll be great! Will you have finished your slides by Friday?", "Você vai arrasar! Você terá terminado os slides até sexta?"], ["I think so. I’ll have sent them to the organizers by Thursday night.", "Acho que sim. Eu os terei enviado aos organizadores até quinta à noite."], ["And what about your hotel? Will they have booked your accommodation by then?", "E o seu hotel? Eles já terão reservado a sua hospedagem até lá?"], ["They said yes. A delegate from Brazil will be staying in the same hotel, too.", "Disseram que sim. Um delegado do Brasil também vai estar hospedado no mesmo hotel."], ["Nice! What time will you be arriving on Sunday?", "Legal! A que horas você estará chegando no domingo?"], ["Around seven, so I’ll be having dinner with the other attendees at eight.", "Por volta das sete, então estarei jantando com os outros participantes às oito."], ["Perfect. I’ll be waiting for your call at nine. Don’t forget, okay?", "Perfeito. Estarei esperando sua ligação às nove. Não esqueça, tá?"]], ["Acento em SEMinar e atTENdee", "Em seminar a força cai na primeira sílaba: SEM-i-nar. Em attendee ela cai na terceira: at-ten-DEE.", ["seminar", "attendee"]], ["This time next week, I ___ on a beach.", "will be lying", "will lie", "Nesta hora, na semana que vem, estarei deitado numa praia.", "Para uma ação em andamento num momento futuro, use will be + -ing."], [["This time next week, Priya will be giving a seminar on teamwork in Chicago.", "Nesta hora, na semana que vem, a Priya estará dando um seminário sobre trabalho em equipe em Chicago."], ["This time next week, I’ll be standing on stage in front of two hundred people.", "Nesta hora, na semana que vem, estarei no palco diante de duzentas pessoas."]], [{"t": "c", "q": "By Friday, she ___ all the slides.", "o": ["will have finished", "will be finishing", "finished"], "pt": "Até sexta, ela terá terminado todos os slides.", "why": "Will have + particípio mostra algo concluído antes de um prazo futuro."}, {"t": "l", "say": "About two hundred attendees will be arriving on Sunday evening.", "o": ["About two hundred attendees will be arriving on Sunday evening.", "About two hundred attendees will arriving on Sunday evening.", "About two hundred attendees will have arriving on Sunday evening."], "why": "Will be + -ing para ação em andamento no futuro."}, {"t": "b", "pt": "Estarei chegando às sete.", "w": ["I’ll", "be", "arriving", "at", "seven"]}, {"t": "b", "pt": "Eles terão reservado o hotel até lá.", "w": ["They", "will", "have", "booked", "the", "hotel", "by", "then"]}]];
