englishB1Plans[78]={"title": "Debatendo o final de um filme de tribunal", "file": "", "grammar": "Expressar opinião e chegar a acordo em uma discussão", "goal": "Dê sua opinião, concorde ou discorde com educação e chegue a um acordo.", "words": [["critical", "crítico, exigente"], ["similarity", "semelhança"], ["concept", "conceito, ideia"], ["innocent", "inocente"], ["controversial", "polêmico"], ["jury", "júri"], ["verdict", "veredito"], ["trial", "julgamento"]]};
englishB1Content[78]=[[["Mia and Ben watched a courtroom movie where the jury must reach a verdict.", "A Mia e o Ben assistiram a um filme de tribunal em que o júri precisa chegar a um veredito."], ["The trial was controversial, because the young man seemed innocent but nobody believed him.", "O julgamento foi polêmico, porque o rapaz parecia inocente, mas ninguém acreditava nele."], ["In Mia’s opinion, the concept is clever, but the ending is too predictable.", "Na opinião da Mia, o conceito é inteligente, mas o final é previsível demais."], ["Ben disagreed, because he thinks the acting is great and the story feels real.", "O Ben discordou, porque acha a atuação ótima e a história parece real."], ["They noticed a similarity with a real case they read about last year.", "Eles notaram uma semelhança com um caso real sobre o qual leram no ano passado."], ["After an hour, they agreed to disagree, and they promised to be less critical.", "Depois de uma hora, concordaram em discordar e prometeram ser menos críticos."]], [["So what did you think of the ending? In my opinion, it was too predictable.", "E o que você achou do final? Na minha opinião, foi previsível demais."], ["I see your point, but I think the jury’s verdict was a surprise.", "Entendo o seu ponto, mas acho que o veredito do júri foi uma surpresa."], ["Really? Everyone knew the young man was innocent from the first scene.", "Sério? Todo mundo sabia que o rapaz era inocente desde a primeira cena."], ["That’s true, but I liked the concept. The trial felt very real to me.", "É verdade, mas eu gostei da ideia. O julgamento pareceu muito real para mim."], ["I agree with you about the acting. It was excellent, and the lawyer was great.", "Concordo com você sobre a atuação. Foi excelente, e o advogado foi ótimo."], ["Still, I think the movie was controversial for the wrong reasons.", "Mesmo assim, acho que o filme foi polêmico pelas razões erradas."], ["You may be right. Maybe we’re both being too critical. Let’s agree to disagree.", "Talvez você tenha razão. Talvez estejamos sendo críticos demais. Vamos concordar em discordar."], ["Deal. And next Friday we’ll watch a comedy, so there won’t be an argument, okay?", "Combinado. E na sexta que vem vamos ver uma comédia, para não haver discussão, certo?"]], ["/t/ final em verdict e concept", "Em verdict e concept, o /t/ final é solto e curto, sem vogal extra: VER-dikt, KON-sept. Não diga “verdicte”.", ["verdict", "concept"]], ["I ___ you about the acting.", "agree with", "am agree with", "Concordo com você sobre a atuação.", "Em inglês, agree é um verbo: I agree, sem be."], [["In Mia’s opinion, the concept is clever, but the ending is too predictable.", "Na opinião da Mia, o conceito é inteligente, mas o final é previsível demais."], ["I agree with you about the acting. It was excellent, and the lawyer was great.", "Concordo com você sobre a atuação. Foi excelente, e o advogado foi ótimo."]], [{"t": "c", "q": "In my ___, the ending is too predictable.", "o": ["opinion", "opinions", "think"], "pt": "Na minha opinião, o final é previsível demais.", "why": "In my opinion é uma expressão fixa para dar opinião."}, {"t": "l", "say": "I see your point, but I think the jury was wrong.", "o": ["I see your point, but I think the jury was wrong.", "I see your point, but I think the jury were wrong.", "I see you point, but I think the jury was wrong."], "why": "I see your point + but: concordar em parte e depois discordar."}, {"t": "b", "pt": "Vamos concordar em discordar.", "w": ["Let’s", "agree", "to", "disagree"]}, {"t": "b", "pt": "Na minha opinião foi previsível.", "w": ["In", "my", "opinion", "it", "was", "predictable"]}]];
