englishB1Plans[79]={"title": "Formatura no curso de cidadania", "file": "", "grammar": "Revisão final do bloco inicial de B1 (mini-história)", "goal": "Revise used to, remember e forget, preposição + gerúndio, quantifiers, phrasal verbs, tags, each other, futuro e opinião numa só cena.", "words": [["discrimination", "discriminação"], ["citizenship", "cidadania"], ["generosity", "generosidade"], ["pension", "aposentadoria (benefício)"], ["commitment", "compromisso"], ["enthusiasm", "entusiasmo"], ["pride", "orgulho"], ["equality", "igualdade"]]};
englishB1Content[79]=[[["Rosa teaches a citizenship class for adults, and she has great enthusiasm for her work.", "A Rosa dá aula de cidadania para adultos e tem muito entusiasmo pelo trabalho."], ["She used to work in a bank, but her commitment to equality changed her plans.", "Ela trabalhava num banco, mas o compromisso dela com a igualdade mudou seus planos."], ["Her students are interested in learning about discrimination and the rights of every citizen.", "Os alunos dela têm interesse em aprender sobre discriminação e os direitos de cada cidadão."], ["Hector, an older student, almost forgot to bring his papers to the final test.", "O Hector, um aluno mais velho, quase esqueceu de levar os papéis para a prova final."], ["Rosa remembered to call him, and he stopped worrying about the exam.", "A Rosa lembrou de ligar para ele, e ele parou de se preocupar com a prova."], ["By June, all of them will have passed, and Rosa will be smiling with pride.", "Em junho, todos terão passado, e a Rosa estará sorrindo de orgulho."]], [["Hector, you’re ready for the final test tomorrow, aren’t you?", "Hector, você está pronto para a prova final amanhã, não está?"], ["I think so, Rosa. I’m afraid of making mistakes, but I studied a great deal.", "Acho que sim, Rosa. Tenho medo de errar, mas estudei muito."], ["That’s good. In my opinion, your commitment is the real secret to success.", "Que bom. Na minha opinião, o seu compromisso é o verdadeiro segredo do sucesso."], ["Thanks. I used to be shy, but I’m used to speaking in class now.", "Obrigado. Eu era tímido, mas agora estou acostumado a falar em aula."], ["Don’t forget to bring your papers. I’ll hold your pension form in my office.", "Não esqueça de levar seus papéis. Vou guardar o seu formulário de aposentadoria na minha sala."], ["Great. By Friday, I’ll have passed the test, and I’ll be celebrating with everybody.", "Ótimo. Até sexta terei passado na prova e estarei comemorando com todos."], ["We’ll all be there. We help each other, and that’s what a community does.", "Todos estaremos lá. A gente se ajuda, e é isso que uma comunidade faz."], ["You’re right. So I’ll see you at nine, and I’ll bring a cake for the class.", "Você tem razão. Então te vejo às nove, e levo um bolo para a turma."]], ["/ʃ/ em discrimination e citizenship", "O -tion de discrimination e o -ship de citizenship soam /ʃ/: dis-kri-mi-NAY-shun, SIT-i-zun-ship. Mantenha o som longo e suave.", ["discrimination", "citizenship"]], ["By June, all of them ___ the test.", "will have passed", "will be passing", "Em junho, todos terão passado na prova.", "Para algo concluído até um prazo futuro, use will have + particípio."], [["By June, all of them will have passed, and Rosa will be smiling with pride.", "Em junho, todos terão passado, e a Rosa estará sorrindo de orgulho."], ["Thanks. I used to be shy, but I’m used to speaking in class now.", "Obrigado. Eu era tímido, mas agora estou acostumado a falar em aula."]], [{"t": "c", "q": "You’re ready for the test, ___?", "o": ["aren’t you", "don’t you", "won’t you"], "pt": "Você está pronto para a prova, não está?", "why": "Frase afirmativa com be pede tag negativa com be: aren’t you."}, {"t": "l", "say": "We help each other, and that’s what a community does.", "o": ["We help each other, and that’s what a community does.", "We help ourselves, and that’s what a community does.", "We help each others, and that’s what a community does."], "why": "Each other = um ao outro."}, {"t": "b", "pt": "Eu tenho medo de errar.", "w": ["I’m", "afraid", "of", "making", "mistakes"]}, {"t": "b", "pt": "Ele parou de se preocupar com a prova.", "w": ["He", "stopped", "worrying", "about", "the", "exam"]}]];
englishB1PhotoThemes[79]="notebook";
englishB1MiniStories[79]=["O curso de cidadania da Rosa", "Rosa teaches a citizenship class for adults, and she has great enthusiasm for it.~A Rosa dá aula de cidadania para adultos e tem muito entusiasmo por isso.|She used to work in a bank, but her commitment to equality changed her plans.~Ela trabalhava num banco, mas o compromisso dela com a igualdade mudou seus planos.|Her students are interested in learning about discrimination and the rights of every citizen.~Os alunos dela têm interesse em aprender sobre discriminação e os direitos de cada cidadão.|Hector, an older student, almost forgot to bring his papers to the final test.~O Hector, um aluno mais velho, quase esqueceu de levar os papéis para a prova final.|Rosa remembered to call him, and he stopped worrying when she said, “You’ll do well, won’t you?”~A Rosa lembrou de ligar para ele, e ele parou de se preocupar quando ela disse: “Você vai bem, não vai?”|He says he’s used to hard work, but he’s afraid of making mistakes in English.~Ele diz que está acostumado ao trabalho duro, mas tem medo de errar no inglês.|The class helped each other, and nobody had to prepare for the test by themselves.~A turma se ajudou, e ninguém precisou se preparar para a prova sozinho.|By the end of June, all of them will have passed, and Rosa will be smiling with pride.~No fim de junho, todos terão passado, e a Rosa estará sorrindo de orgulho.|Hector also showed generosity: he gave his small pension to buy a cake for the party.~O Hector também mostrou generosidade: usou a pequena aposentadoria para comprar um bolo para a festa.|In his opinion, it was the best day of his life, and the whole class agreed.~Na opinião dele, foi o melhor dia da vida dele, e a turma toda concordou."];
englishB1ExtraWordExamples[79]={"generosity": ["His generosity surprised everyone.", "A generosidade dele surpreendeu todos."]};
